	internal static class AdornerExtensions
	{
		public static void AddAdorner<TAdorner>(this UIElement element, TAdorner adorner) where TAdorner : Adorner
		{
			if (adorner == null)
			{
				throw new ArgumentNullException("adorner");
			}
			(AdornerLayer.GetAdornerLayer(element) ?? throw new InvalidOperationException("This element has no adorner layer.")).Add(adorner);
		}

		public static void RemoveAdorners<TAdorner>(this UIElement element) where TAdorner : Adorner
		{
			AdornerLayer adornerLayer = AdornerLayer.GetAdornerLayer(element);
			Adorner[] array = adornerLayer?.GetAdorners(element);
			if (array == null)
			{
				return;
			}
			foreach (TAdorner item in array.OfType<TAdorner>())
			{
				adornerLayer.Remove(item);
			}
		}
	}
