	public static class BehaviorsAssist
	{
		private static readonly DependencyProperty OriginalBehaviorProperty = DependencyProperty.RegisterAttached("OriginalBehavior", typeof(Behavior), typeof(BehaviorsAssist), new UIPropertyMetadata(null));

		public static readonly DependencyProperty BehaviorsProperty = DependencyProperty.RegisterAttached("Behaviors", typeof(BehaviorCollection), typeof(BehaviorsAssist), new FrameworkPropertyMetadata(null, OnPropertyChanged));

		private static void SetOriginalBehavior(DependencyObject obj, Behavior? value)
		{
			obj.SetValue(OriginalBehaviorProperty, value);
		}

		private static Behavior? GetOriginalBehavior(DependencyObject obj)
		{
			return (Behavior)obj.GetValue(OriginalBehaviorProperty);
		}

		public static void SetBehaviors(DependencyObject uie, BehaviorCollection? value)
		{
			uie.SetValue(BehaviorsProperty, value);
		}

		public static BehaviorCollection? GetBehaviors(DependencyObject uie)
		{
			return (BehaviorCollection)uie.GetValue(BehaviorsProperty);
		}

		private static void OnPropertyChanged(DependencyObject dpo, DependencyPropertyChangedEventArgs e)
		{
			if (!(dpo is FrameworkElement frameworkElement))
			{
				return;
			}
			BehaviorCollection behaviorCollection = e.NewValue as BehaviorCollection;
			BehaviorCollection behaviorCollection2 = e.OldValue as BehaviorCollection;
			if (behaviorCollection == behaviorCollection2)
			{
				return;
			}
			Microsoft.Xaml.Behaviors.BehaviorCollection behaviors = Interaction.GetBehaviors(frameworkElement);
			frameworkElement.Unloaded -= FrameworkElementUnloaded;
			if (behaviorCollection2 != null)
			{
				foreach (Behavior item in behaviorCollection2)
				{
					int indexOf = GetIndexOf(behaviors, item);
					if (indexOf >= 0)
					{
						behaviors.RemoveAt(indexOf);
					}
				}
			}
			if (behaviorCollection != null)
			{
				foreach (Behavior item2 in behaviorCollection)
				{
					if (GetIndexOf(behaviors, item2) < 0)
					{
						Behavior behavior = (Behavior)item2.Clone();
						SetOriginalBehavior(behavior, item2);
						behaviors.Add(behavior);
					}
				}
			}
			if (behaviors.Count > 0)
			{
				frameworkElement.Unloaded += FrameworkElementUnloaded;
			}
		}

		private static void FrameworkElementUnloaded(object sender, RoutedEventArgs e)
		{
			if (!(sender is FrameworkElement frameworkElement))
			{
				return;
			}
			foreach (Behavior behavior in Interaction.GetBehaviors(frameworkElement))
			{
				behavior.Detach();
			}
			frameworkElement.Loaded += FrameworkElementLoaded;
		}

		private static void FrameworkElementLoaded(object sender, RoutedEventArgs e)
		{
			if (!(sender is FrameworkElement frameworkElement))
			{
				return;
			}
			frameworkElement.Loaded -= FrameworkElementLoaded;
			foreach (Behavior behavior in Interaction.GetBehaviors(frameworkElement))
			{
				behavior.Attach(frameworkElement);
			}
		}

		private static int GetIndexOf(Microsoft.Xaml.Behaviors.BehaviorCollection itemBehaviors, Behavior behavior)
		{
			int result = -1;
			Behavior originalBehavior = GetOriginalBehavior(behavior);
			for (int i = 0; i < itemBehaviors.Count; i++)
			{
				Behavior behavior2 = itemBehaviors[i];
				if (behavior2 == behavior || behavior2 == originalBehavior)
				{
					result = i;
					break;
				}
				Behavior originalBehavior2 = GetOriginalBehavior(behavior2);
				if (originalBehavior2 == behavior || originalBehavior2 == originalBehavior)
				{
					result = i;
					break;
				}
			}
			return result;
		}
	}
