			}
			set
			{
				if (SetField(ref _colorAdjustment, value))
				{
					SetTheme();
				}
			}
		}

		private void SetTheme()
		{
			BaseTheme? baseTheme = BaseTheme;
			if (!baseTheme.HasValue)
			{
				return;
			}
			BaseTheme valueOrDefault = baseTheme.GetValueOrDefault();
			PrimaryColor? primaryColor = PrimaryColor;
			if (primaryColor.HasValue)
			{
				PrimaryColor valueOrDefault2 = primaryColor.GetValueOrDefault();
				SecondaryColor? secondaryColor = SecondaryColor;
				if (secondaryColor.HasValue)
				{
					SecondaryColor valueOrDefault3 = secondaryColor.GetValueOrDefault();
					Lazy<Color?> lazy = new Lazy<Color?>(Theme.GetSystemAccentColor);
					Color primary = ((valueOrDefault2 == MaterialDesignColors.PrimaryColor.Inherit) ? lazy.Value.GetValueOrDefault() : SwatchHelper.Lookup[(MaterialDesignColor)valueOrDefault2]);
					Color secondary = ((valueOrDefault3 == MaterialDesignColors.SecondaryColor.Inherit) ? lazy.Value.GetValueOrDefault() : SwatchHelper.Lookup[(MaterialDesignColor)valueOrDefault3]);
					Theme theme = Theme.Create(valueOrDefault, primary, secondary);
					theme.ColorAdjustment = ColorAdjustment;
					ApplyTheme(theme);
				}
			}
		}

		protected static bool SetField<T>(ref T field, T value)
		{
			if (EqualityComparer<T>.Default.Equals(field, value))
			{
				return false;
			}
			field = value;
			return true;
		}

		protected virtual void ApplyTheme(Theme theme)
		{
			this.SetTheme(theme);
		}
	}
