		private static void TimePropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs e)
		{
			Clock clock = (Clock)dependencyObject;
			SetFlags(clock);
			TimeChangedEventArgs timeChangedEventArgs = new TimeChangedEventArgs(TimeChangedEvent, (DateTime)e.OldValue, (DateTime)e.NewValue);
			clock.OnTimeChanged(timeChangedEventArgs);
		}

