			};
			clock.RaiseEvent(e);
		}

		public override void OnApplyTemplate()
		{
			SetFlags(this);
			GenerateButtons();
			if (_hourReadOutPartName != null)
			{
				_hourReadOutPartName.PreviewMouseLeftButtonDown -= HourReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			if (_minuteReadOutPartName != null)
			{
				_minuteReadOutPartName.PreviewMouseLeftButtonDown -= MinuteReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			if (_secondReadOutPartName != null)
			{
				_secondReadOutPartName.PreviewMouseLeftButtonDown -= SecondReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			_hourReadOutPartName = GetTemplateChild("PART_HourReadOut") as Grid;
			_minuteReadOutPartName = GetTemplateChild("PART_MinuteReadOut") as Grid;
			_secondReadOutPartName = GetTemplateChild("PART_SecondReadOut") as Grid;
			if (_hourReadOutPartName != null)
			{
				_hourReadOutPartName.PreviewMouseLeftButtonDown += HourReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			if (_minuteReadOutPartName != null)
			{
				_minuteReadOutPartName.PreviewMouseLeftButtonDown += MinuteReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			if (_secondReadOutPartName != null)
			{
				_secondReadOutPartName.PreviewMouseLeftButtonDown += SecondReadOutPartNameOnPreviewMouseLeftButtonDown;
			}
			base.OnApplyTemplate();
			GotoVisualState(useTransitions: false);
		}

		private void GotoVisualState(bool useTransitions)
		{
			Clock control = this;
			string stateName;
			if (DisplayMode != ClockDisplayMode.Hours)
			{
				stateName = ((DisplayMode == ClockDisplayMode.Minutes) ? "Minutes" : "Seconds");
			}
			else
			{
				stateName = "Hours";
			}
			VisualStateManager.GoToState(control, stateName, useTransitions);
		}

		private void GenerateButtons()
		{
			if (GetTemplateChild("PART_HoursCanvas") is Canvas canvas)
			{
				RemoveExistingButtons(canvas);
				if (Is24Hours)
				{
					GenerateButtons(canvas, Enumerable.Range(13, 12).ToList(), ButtonRadiusRatio, new ClockItemIsCheckedConverter(() => Time, ClockDisplayMode.Hours, Is24Hours), (int i) => "ButtonStyle", "00", ClockDisplayMode.Hours);
					GenerateButtons(canvas, Enumerable.Range(1, 12).ToList(), ButtonRadiusInnerRatio, new ClockItemIsCheckedConverter(() => Time, ClockDisplayMode.Hours, Is24Hours), (int i) => "ButtonStyle", "#", ClockDisplayMode.Hours);
				}
				else
				{
					GenerateButtons(canvas, Enumerable.Range(1, 12).ToList(), ButtonRadiusRatio, new ClockItemIsCheckedConverter(() => Time, ClockDisplayMode.Hours, Is24Hours), (int i) => "ButtonStyle", "0", ClockDisplayMode.Hours);
				}
			}
			if (GetTemplateChild("PART_MinutesCanvas") is Canvas canvas2)
			{
				RemoveExistingButtons(canvas2);
				GenerateButtons(canvas2, Enumerable.Range(1, 60).ToList(), ButtonRadiusRatio, new ClockItemIsCheckedConverter(() => Time, ClockDisplayMode.Minutes, Is24Hours), (int i) => ((double)i / 5.0 % 1.0 != 0.0) ? "LesserButtonStyle" : "ButtonStyle", "0", ClockDisplayMode.Minutes, (int i) => i % 60 % MinuteSelectionStep == 0);
			}
			if (GetTemplateChild("PART_SecondsCanvas") is Canvas canvas3)
			{
				RemoveExistingButtons(canvas3);
				GenerateButtons(canvas3, Enumerable.Range(1, 60).ToList(), ButtonRadiusRatio, new ClockItemIsCheckedConverter(() => Time, ClockDisplayMode.Seconds, Is24Hours), (int i) => ((double)i / 5.0 % 1.0 != 0.0) ? "LesserButtonStyle" : "ButtonStyle", "0", ClockDisplayMode.Seconds);
			}
			static void RemoveExistingButtons(Canvas canvas4)
			{
				for (int num = canvas4.Children.Count - 1; num >= 0; num--)
				{
					if (canvas4.Children[num] is ClockItemButton)
					{
						canvas4.Children.RemoveAt(num);
					}
				}
			}
		}

		private void SecondReadOutPartNameOnPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
		{
			SetCurrentValue(DisplayModeProperty, ClockDisplayMode.Seconds);
		}

		private void MinuteReadOutPartNameOnPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
		{
			SetCurrentValue(DisplayModeProperty, ClockDisplayMode.Minutes);
		}

		private void HourReadOutPartNameOnPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs mouseButtonEventArgs)
		{
			SetCurrentValue(DisplayModeProperty, ClockDisplayMode.Hours);
		}

		private void GenerateButtons(Panel canvas, List<int> range, double radiusRatio, IValueConverter isCheckedConverter, Func<int, string> stylePropertySelector, string format, ClockDisplayMode clockDisplayMode, Func<int, bool>? isEnabledSelector = null)
		{
			double num = 360.0 / (double)range.Count * (Math.PI / 180.0);
			if (canvas.Width < 10.0 || Math.Abs(canvas.Height - canvas.Width) > 0.0)
			{
				return;
			}
			_centreCanvas = new Point(canvas.Width / 2.0, canvas.Height / 2.0);
			double num2 = _centreCanvas.X * radiusRatio;
			foreach (int item in range)
			{
				ClockItemButton clockItemButton = new ClockItemButton();
				clockItemButton.SetBinding(FrameworkElement.StyleProperty, GetBinding(stylePropertySelector(item)));
				double num3 = Math.Cos((double)item * num) * num2;
				double num4 = Math.Sin((double)item * num) * num2;
				clockItemButton.CentreX = _centreCanvas.X + num4;
				clockItemButton.CentreY = _centreCanvas.Y - num3;
				clockItemButton.SetBinding(ToggleButton.IsCheckedProperty, GetBinding("Time", null, isCheckedConverter, item));
				clockItemButton.SetBinding(Canvas.LeftProperty, GetBinding("X", clockItemButton));
				clockItemButton.SetBinding(Canvas.TopProperty, GetBinding("Y", clockItemButton));
				clockItemButton.Content = ((item != 60) ? ((item != 24 || clockDisplayMode != ClockDisplayMode.Hours) ? item : 0) : 0).ToString(format);
				if (isEnabledSelector != null)
				{
					bool isEnabled = isEnabledSelector(item);
					clockItemButton.IsEnabled = isEnabled;
				}
				canvas.Children.Add(clockItemButton);
			}
			BindingBase GetBinding(string propertyName, object? owner = null, IValueConverter? converter = null, object? converterParameter = null)
			{
				return new Binding(propertyName)
				{
					Source = (owner ?? this),
					Converter = converter,
					ConverterParameter = converterParameter
				};
			}
		}

		private void ClockItemDragCompletedHandler(object sender, DragCompletedEventArgs e)
		{
			OnClockChoiceMade(this, DisplayMode);
			switch (DisplayAutomation)
			{
			case ClockDisplayAutomation.Cycle:
				DisplayMode = ((DisplayMode == ClockDisplayMode.Hours) ? ClockDisplayMode.Minutes : ClockDisplayMode.Hours);
				break;
			case ClockDisplayAutomation.CycleWithSeconds:
				if (DisplayMode == ClockDisplayMode.Hours)
				{
					DisplayMode = ClockDisplayMode.Minutes;
				}
				else if (DisplayMode == ClockDisplayMode.Minutes)
				{
					DisplayMode = ClockDisplayMode.Seconds;
				}
				else
				{
					DisplayMode = ClockDisplayMode.Hours;
				}
				break;
			case ClockDisplayAutomation.ToMinutesOnly:
				if (DisplayMode == ClockDisplayMode.Hours)
				{
					DisplayMode = ClockDisplayMode.Minutes;
				}
				break;
			case ClockDisplayAutomation.ToSeconds:
				if (DisplayMode == ClockDisplayMode.Hours)
				{
					DisplayMode = ClockDisplayMode.Minutes;
				}
				else if (DisplayMode == ClockDisplayMode.Minutes)
				{
					DisplayMode = ClockDisplayMode.Seconds;
				}
				break;
			default:
				throw new ArgumentOutOfRangeException();
			case ClockDisplayAutomation.None:
				break;
			}
		}

		private void ClockItemDragStartedHandler(object sender, DragStartedEventArgs dragStartedEventArgs)
		{
			_currentStartPosition = new Point(dragStartedEventArgs.HorizontalOffset, dragStartedEventArgs.VerticalOffset);
		}

		private void ClockItemDragDeltaHandler(object sender, DragDeltaEventArgs dragDeltaEventArgs)
		{
			Point point = new Point(_currentStartPosition.X + dragDeltaEventArgs.HorizontalChange, _currentStartPosition.Y + dragDeltaEventArgs.VerticalChange);
			Point point2 = new Point(point.X - _centreCanvas.X, point.Y - _centreCanvas.Y);
			double num = Math.Atan2(point2.X, 0.0 - point2.Y);
			if (num < 0.0)
			{
				num += Math.PI * 2.0;
			}
			DateTime dateTime;
			if (DisplayMode == ClockDisplayMode.Hours)
			{
				if (Is24Hours)
				{
					double num2 = _centreCanvas.X * ButtonRadiusInnerRatio + (_centreCanvas.X * ButtonRadiusRatio - _centreCanvas.X * ButtonRadiusInnerRatio) / 2.0;
					bool flag = Math.Sqrt((_centreCanvas.X - point.X) * (_centreCanvas.X - point.X) + (_centreCanvas.Y - point.Y) * (_centreCanvas.Y - point.Y)) > num2;
					int num3 = (int)Math.Round(6.0 * num / Math.PI, MidpointRounding.AwayFromZero) % 12 + (flag ? 12 : 0);
					switch (num3)
					{
					case 12:
						num3 = 0;
						break;
					case 0:
						num3 = 12;
						break;
					}
					dateTime = new DateTime(Time.Year, Time.Month, Time.Day, num3, Time.Minute, Time.Second);
				}
				else
				{
					dateTime = new DateTime(Time.Year, Time.Month, Time.Day, (int)Math.Round(6.0 * num / Math.PI, MidpointRounding.AwayFromZero) % 12 + (IsPostMeridiem ? 12 : 0), Time.Minute, Time.Second);
				}
			}
			else
			{
				int num4 = (int)Math.Round(30.0 * num / Math.PI, MidpointRounding.AwayFromZero) % 60;
				int num5 = ((DisplayMode == ClockDisplayMode.Minutes) ? ((int)Math.Round((double)num4 / (double)MinuteSelectionStep, MidpointRounding.AwayFromZero) * MinuteSelectionStep % 60) : num4);
				dateTime = ((DisplayMode != ClockDisplayMode.Minutes) ? new DateTime(Time.Year, Time.Month, Time.Day, Time.Hour, Time.Minute, num5) : new DateTime(Time.Year, Time.Month, Time.Day, Time.Hour, num5, Time.Second));
			}
			SetCurrentValue(TimeProperty, dateTime);
		}

		private static void SetFlags(Clock clock)
		{
			clock.IsPostMeridiem = clock.Time.Hour >= 12;
			clock.IsMidnightHour = clock.Time.Hour == 0;
			clock.IsMiddayHour = clock.Time.Hour == 12;
		}
	}
