			HsbProperty = DependencyProperty.Register("Hsb", typeof(Hsb), typeof(ColorPicker), new FrameworkPropertyMetadata(default(Hsb), FrameworkPropertyMetadataOptions.AffectsArrange | FrameworkPropertyMetadataOptions.BindsTwoWayByDefault, HsbPropertyChangedCallback));
