		protected override void OnPropertyChanged(DependencyPropertyChangedEventArgs e)
		{
			base.OnPropertyChanged(e);
			if (e.Property == Popup.ChildProperty && Child is ContentControl contentControl && contentControl.Template != ClassicContentTemplate)
			{
				contentControl.Template = ClassicContentTemplate;
			}
		}

		protected override void OnClosed(EventArgs e)
		{
			SetCurrentValue(OpenDirectionProperty, PopupDirection.None);
			base.OnClosed(e);
		}

		private CustomPopupPlacement[] ComboBoxCustomPopupPlacementCallback(Size popupSize, Size targetSize, Point offset)
		{
			if (CustomPopupPlacementCallbackOverride != null)
			{
				return CustomPopupPlacementCallbackOverride(popupSize, targetSize, offset);
			}
			List<DependencyObject> list = PlacementTarget.GetVisualAncestry().ToList();
			Panel parent = list.OfType<Panel>().First();
			VisiblePlacementWidth = TreeHelper.GetVisibleWidth((FrameworkElement)PlacementTarget, parent, FlowDirection);
			PositioningData positioningData = GetPositioningData(list, popupSize, targetSize);
			double num = DpiHelper.TransformToDeviceY(positioningData.MainVisual, DefaultVerticalOffset);
			double y;
			PopupDirection popupDirection;
			if (positioningData.LocationY + positioningData.PopupSize.Height > positioningData.ScreenHeight)
			{
				y = 0.0 - (num + positioningData.PopupSize.Height);
				popupDirection = PopupDirection.Up;
			}
			else
			{
				y = num + positioningData.TargetSize.Height;
				popupDirection = PopupDirection.Down;
			}
			SetCurrentValue(OpenDirectionProperty, popupDirection);
			return new CustomPopupPlacement[1]
			{
				new CustomPopupPlacement(new Point(positioningData.OffsetX, y), PopupPrimaryAxis.Horizontal)
			};
			PositioningData GetPositioningData(IEnumerable<DependencyObject?> visualAncestry, Size popupSize2, Size targetSize2)
			{
				Point point = PlacementTarget.PointToScreen(new Point(0.0, 0.0));
				Visual? visual = visualAncestry.OfType<Visual>().LastOrDefault() ?? throw new ArgumentException("visualAncestry must contains at least one Visual control inside.");
				Visual visual2 = visualAncestry.OfType<Visual>().FirstOrDefault() ?? throw new ArgumentException("visualAncestry must contains at least one Visual control inside.");
				Screen screen = Screen.FromPoint(point);
				int num2 = (int)screen.Bounds.Width;
				int num3 = (int)screen.Bounds.Height;
				int num4 = (int)(point.X - screen.Bounds.X) % num2;
				int num5 = (int)(point.Y - screen.Bounds.Y) % num3;
				double newUpY = DpiHelper.TransformToDeviceY(visual, UpVerticalOffset) * ScaleHelper.GetTotalTransformScaleY(visual2) - popupSize2.Height + targetSize2.Height;
				double newDownY = DpiHelper.TransformToDeviceY(visual, DownVerticalOffset) * ScaleHelper.GetTotalTransformScaleY(visual2);
				double num6 = DpiHelper.TransformToDeviceX(visual, RelativeHorizontalOffset) * ScaleHelper.GetTotalTransformScaleX(visual2);
				num6 = ((FlowDirection == FlowDirection.LeftToRight) ? Round(num6) : Math.Truncate(num6 - targetSize2.Width));
				return new PositioningData(visual, num6, newUpY, newDownY, popupSize2, targetSize2, num4, num5, num3, num2);
			}
		}

		private static double Round(double val)
		{
			return (val < 0.0) ? ((int)(val - 0.5)) : ((int)(val + 0.5));
		}
	}
