	public class CustomColorTheme : ResourceDictionary, IMaterialDesignThemeDictionary
	{
		private BaseTheme? _baseTheme;

		private Color? _primaryColor;

		private Color? _secondaryColor;

		private ColorAdjustment? _colorAdjustment;

		public BaseTheme? BaseTheme
		{
			get
			{
				return _baseTheme;
			}
			set
			{
				if (_baseTheme != value)
				{
					_baseTheme = value;
					SetTheme();
				}
			}
		}

		[TypeConverter(typeof(InheritSystemColorTypeConverter))]
		public Color? PrimaryColor
		{
			get
			{
				return _primaryColor;
			}
			set
			{
				if (_primaryColor != value)
				{
					_primaryColor = value;
					SetTheme();
				}
			}
		}

		[TypeConverter(typeof(InheritSystemColorTypeConverter))]
		public Color? SecondaryColor
		{
			get
			{
				return _secondaryColor;
			}
			set
			{
				if (_secondaryColor != value)
				{
					_secondaryColor = value;
					SetTheme();
				}
			}
		}

		public ColorAdjustment? ColorAdjustment
		{
			get
			{
				return _colorAdjustment;
			}
			set
			{
				if (_colorAdjustment != value)
				{
					_colorAdjustment = value;
					SetTheme();
				}
			}
		}

		private void SetTheme()
		{
			BaseTheme? baseTheme = BaseTheme;
			if (!baseTheme.HasValue)
			{
				return;
			}
			BaseTheme valueOrDefault = baseTheme.GetValueOrDefault();
			Color? primaryColor = PrimaryColor;
			if (primaryColor.HasValue)
			{
				Color valueOrDefault2 = primaryColor.GetValueOrDefault();
				primaryColor = SecondaryColor;
				if (primaryColor.HasValue)
				{
					Color valueOrDefault3 = primaryColor.GetValueOrDefault();
					Theme theme = Theme.Create(valueOrDefault, valueOrDefault2, valueOrDefault3);
					theme.ColorAdjustment = ColorAdjustment;
					ApplyTheme(theme);
				}
			}
		}

		protected virtual void ApplyTheme(Theme theme)
		{
			this.SetTheme(theme);
		}
	}
