		private static void ApplyMaterialDesignColumnStylesPropertyChangedCallback(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			DataGrid dataGrid = (DataGrid)d;
			dataGrid.Columns.CollectionChanged -= ColumnsCollectionChanged;
			if (!object.Equals(true, e.NewValue))
			{
				return;
			}
			dataGrid.Columns.CollectionChanged += ColumnsCollectionChanged;
			foreach (DataGridColumn column in dataGrid.Columns)
			{
				ApplyMaterialDesignColumnStyleForColumn(dataGrid, column);
			}
			void ColumnsCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e2)
			{
				IList? newItems = e2.NewItems;
				foreach (DataGridColumn item in ((newItems != null) ? newItems.OfType<DataGridColumn>() : null) ?? Enumerable.Empty<DataGridColumn>())
				{
					ApplyMaterialDesignColumnStyleForColumn(dataGrid, item);
				}
			}
		}

		private static void ApplyMaterialDesignColumnStyleForColumn(DataGrid dataGrid, DataGridColumn column)
		{
			Style objB = (Style)DataGridBoundColumn.ElementStyleProperty.GetMetadata(column.GetType()).DefaultValue;
			Style objB2 = (Style)DataGridBoundColumn.EditingElementStyleProperty.GetMetadata(column.GetType()).DefaultValue;
			bool flag;
			if (!(column is DataGridCheckBoxColumn dataGridCheckBoxColumn))
			{
				if (!(column is System.Windows.Controls.DataGridTextColumn dataGridTextColumn))
				{
					if (!(column is System.Windows.Controls.DataGridComboBoxColumn dataGridComboBoxColumn))
					{
						return;
					}
					flag = object.Equals(dataGridComboBoxColumn.ElementStyle, objB);
					bool flag2 = object.Equals(dataGridComboBoxColumn.EditingElementStyle, objB2);
					if (flag)
					{
						Style autoGeneratedComboBoxStyle = GetAutoGeneratedComboBoxStyle(dataGrid);
						if (autoGeneratedComboBoxStyle != null)
						{
							dataGridComboBoxColumn.ElementStyle = autoGeneratedComboBoxStyle;
						}
					}
					if (flag2)
					{
						Style autoGeneratedEditingComboBoxStyle = GetAutoGeneratedEditingComboBoxStyle(dataGrid);
						if (autoGeneratedEditingComboBoxStyle != null)
						{
							dataGridComboBoxColumn.EditingElementStyle = autoGeneratedEditingComboBoxStyle;
						}
					}
					return;
				}
				flag = object.Equals(dataGridTextColumn.ElementStyle, objB);
				bool flag3 = object.Equals(dataGridTextColumn.EditingElementStyle, objB2);
				if (flag)
				{
					Style autoGeneratedTextStyle = GetAutoGeneratedTextStyle(dataGrid);
					if (autoGeneratedTextStyle != null)
					{
						dataGridTextColumn.ElementStyle = autoGeneratedTextStyle;
					}
				}
				if (flag3)
				{
					Style autoGeneratedEditingTextStyle = GetAutoGeneratedEditingTextStyle(dataGrid);
					if (autoGeneratedEditingTextStyle != null)
					{
						dataGridTextColumn.EditingElementStyle = autoGeneratedEditingTextStyle;
					}
				}
				return;
			}
			flag = object.Equals(dataGridCheckBoxColumn.ElementStyle, objB);
			bool flag4 = object.Equals(dataGridCheckBoxColumn.EditingElementStyle, objB2);
			if (flag)
			{
				Style autoGeneratedCheckBoxStyle = GetAutoGeneratedCheckBoxStyle(dataGrid);
				if (autoGeneratedCheckBoxStyle != null)
				{
					dataGridCheckBoxColumn.ElementStyle = autoGeneratedCheckBoxStyle;
				}
			}
			if (flag4)
			{
				Style autoGeneratedEditingCheckBoxStyle = GetAutoGeneratedEditingCheckBoxStyle(dataGrid);
				if (autoGeneratedEditingCheckBoxStyle != null)
				{
					dataGridCheckBoxColumn.EditingElementStyle = autoGeneratedEditingCheckBoxStyle;
				}
			}
		}

