		private static void EnableEditBoxAssistPropertyChangedCallback(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			DataGrid dataGrid = (DataGrid)d;
			if ((bool)e.NewValue)
			{
				dataGrid.AddHandler(UIElement.MouseLeftButtonDownEvent, new RoutedEventHandler(OnMouseLeftButtonDown), handledEventsToo: true);
				dataGrid.PreviewKeyDown += EditOnSpacebarPress;
			}
			else
			{
				dataGrid.RemoveHandler(UIElement.MouseLeftButtonDownEvent, new RoutedEventHandler(OnMouseLeftButtonDown));
				dataGrid.PreviewKeyDown -= EditOnSpacebarPress;
			}
		}

		private static void OnMouseLeftButtonDown(object sender, RoutedEventArgs e)
		{
			AllowDirectEditWithoutFocus(sender, (MouseButtonEventArgs)e);
		}

