		private static void EditOnSpacebarPress(object sender, KeyEventArgs e)
		{
			DataGrid dataGrid = (DataGrid)sender;
			if (e.Key == Key.Space && e.OriginalSource is DataGridCell { IsReadOnly: false } dataGridCell && (dataGridCell.Column is DataGridComboBoxColumn || dataGridCell.Column is System.Windows.Controls.DataGridTextColumn))
			{
				dataGrid.BeginEdit();
				e.Handled = true;
			}
		}

		private static void AllowDirectEditWithoutFocus(object sender, MouseButtonEventArgs mouseArgs)
		{
			DataGridCell dataGridCell = ((DependencyObject)mouseArgs.OriginalSource).GetVisualAncestry().OfType<DataGridCell>().FirstOrDefault();
			if (dataGridCell == null || dataGridCell.IsReadOnly || !(dataGridCell.Content is UIElement uIElement))
			{
				return;
			}
			DataGrid dataGrid = (DataGrid)sender;
			if (dataGridCell.Column.GetType() == typeof(DataGridTemplateColumn) || dataGridCell.IsEditing || dataGridCell.GetVisualAncestry().OfType<DataGrid>().FirstOrDefault() != dataGrid)
			{
				return;
			}
			dataGrid.CurrentCell = new DataGridCellInfo(dataGridCell);
			dataGrid.BeginEdit();
			object content = dataGridCell.Content;
			if (!(content is TextBoxBase textBoxBase))
			{
				if (!(content is ToggleButton toggleButton))
				{
					if (content is ComboBox comboBox)
					{
						comboBox.IsDropDownOpen = true;
					}
					return;
				}
				Point position = mouseArgs.GetPosition(uIElement);
				if (new Rect(uIElement.RenderSize).Contains(position))
				{
					MouseButtonEventArgs e = new MouseButtonEventArgs(mouseArgs.MouseDevice, mouseArgs.Timestamp, mouseArgs.ChangedButton)
					{
						RoutedEvent = Mouse.MouseDownEvent,
						Source = dataGrid
					};
					toggleButton.RaiseEvent(e);
				}
			}
			else
			{
				MouseButtonEventArgs e2 = new MouseButtonEventArgs(mouseArgs.MouseDevice, mouseArgs.Timestamp, mouseArgs.ChangedButton)
				{
					RoutedEvent = Mouse.MouseDownEvent,
					Source = mouseArgs.Source
				};
				textBoxBase.RaiseEvent(e2);
			}
		}
	}
	public class DataGridComboBoxColumn : System.Windows.Controls.DataGridComboBoxColumn
	{
		public BindingBase? ItemsSourceBinding { get; set; }

		public bool? IsEditable { get; set; }

		public new static Style DefaultElementStyle
		{
			get
			{
				ComboBox comboBox = new ComboBox();
				ComponentResourceKey resourceKey = new ComponentResourceKey(typeof(ComboBox), "MaterialDataGridComboBoxColumnStyle");
				return (Style)comboBox.TryFindResource(resourceKey);
			}
		}

		public new static Style DefaultEditingElementStyle
		{
			get
			{
				ComboBox comboBox = new ComboBox();
				ComponentResourceKey resourceKey = new ComponentResourceKey(typeof(ComboBox), "MaterialDataGridComboBoxColumnEditingStyle");
				return (Style)comboBox.TryFindResource(resourceKey);
			}
		}

		static DataGridComboBoxColumn()
		{
			System.Windows.Controls.DataGridComboBoxColumn.ElementStyleProperty.OverrideMetadata(typeof(DataGridComboBoxColumn), new FrameworkPropertyMetadata(DefaultElementStyle));
			System.Windows.Controls.DataGridComboBoxColumn.EditingElementStyleProperty.OverrideMetadata(typeof(DataGridComboBoxColumn), new FrameworkPropertyMetadata(DefaultEditingElementStyle));
		}

		protected override FrameworkElement GenerateElement(DataGridCell cell, object dataItem)
		{
			FrameworkElement frameworkElement = base.GenerateElement(cell, cell);
			if (ItemsSourceBinding != null)
			{
				frameworkElement.SetBinding(ItemsControl.ItemsSourceProperty, ItemsSourceBinding);
			}
			ApplyStyle(isEditing: false, defaultToElementStyle: false, frameworkElement);
			return frameworkElement;
		}

		protected override FrameworkElement GenerateEditingElement(DataGridCell cell, object dataItem)
		{
			ComboBox comboBox = (ComboBox)base.GenerateElement(cell, cell);
			bool? isEditable = IsEditable;
			if (isEditable.HasValue)
			{
				bool valueOrDefault = isEditable == true;
				comboBox.IsEditable = valueOrDefault;
			}
			BindingBase itemsSourceBinding = ItemsSourceBinding;
			if (itemsSourceBinding != null)
			{
				comboBox.SetBinding(ItemsControl.ItemsSourceProperty, itemsSourceBinding);
			}
			ApplyStyle(isEditing: true, defaultToElementStyle: false, comboBox);
			return comboBox;
		}

		private void ApplyStyle(bool isEditing, bool defaultToElementStyle, FrameworkElement element)
		{
			Style style = PickStyle(isEditing, defaultToElementStyle);
			if (style != null)
			{
				element.Style = style;
			}
		}

		private Style? PickStyle(bool isEditing, bool defaultToElementStyle)
		{
			Style style = (isEditing ? EditingElementStyle : ElementStyle);
			if ((isEditing & defaultToElementStyle) && style == null)
			{
				style = ElementStyle;
			}
			return style;
		}

		protected override void CancelCellEdit(FrameworkElement? editingElement, object? uneditedValue)
		{
			if (editingElement is ComboBox comboBox)
			{
				comboBox.SetCurrentValue(ComboBox.IsDropDownOpenProperty, false);
			}
			base.CancelCellEdit(editingElement, uneditedValue);
		}

		protected override bool CommitCellEdit(FrameworkElement? editingElement)
		{
			if (editingElement is ComboBox comboBox)
			{
				comboBox.SetCurrentValue(ComboBox.IsDropDownOpenProperty, false);
			}
			return base.CommitCellEdit(editingElement);
		}
	}
