	internal static class DateTimeEx
	{
		internal static DateTimeFormatInfo GetDateFormat(this CultureInfo culture)
		{
			if (culture == null)
			{
				throw new ArgumentNullException("culture");
			}
			if (culture.Calendar is GregorianCalendar || culture.Calendar is PersianCalendar)
			{
				return culture.DateTimeFormat;
			}
			GregorianCalendar gregorianCalendar = null;
			foreach (GregorianCalendar item in culture.OptionalCalendars.OfType<GregorianCalendar>())
			{
				if (gregorianCalendar == null)
				{
					gregorianCalendar = item;
				}
				if (item.CalendarType == GregorianCalendarTypes.Localized)
				{
					gregorianCalendar = item;
					break;
				}
			}
			DateTimeFormatInfo dateTimeFormat;
			if (gregorianCalendar == null)
			{
				dateTimeFormat = ((CultureInfo)CultureInfo.InvariantCulture.Clone()).DateTimeFormat;
				dateTimeFormat.Calendar = new GregorianCalendar();
			}
			else
			{
				dateTimeFormat = ((CultureInfo)culture.Clone()).DateTimeFormat;
				dateTimeFormat.Calendar = gregorianCalendar;
			}
			return dateTimeFormat;
		}
	}
