		internal void AssertTargetableContent()
		{
			if (BindingOperations.GetBindingExpression(this, DialogContentProperty) != null)
			{
				throw new InvalidOperationException("Content cannot be passed to a dialog via the OpenDialog if DialogContent already has a binding.");
			}
		}

		internal void InternalClose(object? parameter)
		{
			DialogSession dialogSession = CurrentSession ?? throw new InvalidOperationException("DialogHost does not have a current session");
			dialogSession.CloseParameter = parameter;
			dialogSession.IsEnded = true;
			DialogClosingEventArgs e = new DialogClosingEventArgs(dialogSession, DialogClosingEvent);
			OnDialogClosing(e);
			_attachedDialogClosingEventHandler?.Invoke(this, e);
			DialogClosingCallback?.Invoke(this, e);
			_asyncShowClosingEventHandler?.Invoke(this, e);
			if (e.IsCancelled)
			{
				dialogSession.IsEnded = false;
			}
			else
			{
				SetCurrentValue(IsOpenProperty, false);
			}
		}

		internal UIElement? FocusPopup()
		{
			UIElement uIElement = _popup?.Child ?? _popupContentControl;
			if (uIElement == null)
			{
				return null;
			}
			if (PresentationSource.FromVisual(uIElement) is HwndSource hwndSource)
			{
				SetFocus(hwndSource.Handle);
			}
			CommandManager.InvalidateRequerySuggested();
			UIElement uIElement2 = uIElement.VisualDepthFirstTraversal().OfType<UIElement>().FirstOrDefault((UIElement ui) => ui.Focusable);
			if (uIElement2 == null)
			{
				return null;
			}
			if (uIElement2.IsVisible)
			{
				MoveFocus(uIElement2);
			}
			else
			{
				uIElement2.IsVisibleChanged += FocusableOnIsVisibleChanged;
			}
			return uIElement;
			static void FocusableOnIsVisibleChanged(object sender, DependencyPropertyChangedEventArgs e)
			{
				if (sender is UIElement uIElement3)
				{
					MoveFocus(uIElement3);
					uIElement3.IsVisibleChanged -= FocusableOnIsVisibleChanged;
				}
			}
			static void MoveFocus(UIElement focusable)
			{
				focusable.Dispatcher.BeginInvoke((Action)(() =>
				{
					if (focusable.Focus())
					{
						focusable.MoveFocus(new TraversalRequest(FocusNavigationDirection.First));
					}
				}), DispatcherPriority.Background);
			}
		}

		protected override void OnPreviewMouseDown(MouseButtonEventArgs e)
		{
			Window window = Window.GetWindow(this);
			if (window != null && !window.IsActive && window.OwnedWindows.OfType<Window>().All((Window x) => !x.IsActive))
			{
				window.Activate();
			}
			base.OnPreviewMouseDown(e);
		}

