			}
		}

		private void OpenDialogHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (executedRoutedEventArgs.Handled)
			{
				return;
			}
			if (executedRoutedEventArgs.OriginalSource is DependencyObject element)
			{
				_attachedDialogOpenedEventHandler = GetDialogOpenedAttached(element);
				_attachedDialogClosingEventHandler = GetDialogClosingAttached(element);
				_attachedDialogClosedEventHandler = GetDialogClosedAttached(element);
			}
			if (executedRoutedEventArgs.Parameter != null)
			{
				AssertTargetableContent();
				if (_popupContentControl != null)
				{
					ContentControl popupContentControl = _popupContentControl;
					popupContentControl.DataContext = OpenDialogCommandDataContextSource switch
					{
						DialogHostOpenDialogCommandDataContextSource.SenderElement => (executedRoutedEventArgs.OriginalSource as FrameworkElement)?.DataContext, 
						DialogHostOpenDialogCommandDataContextSource.DialogHostInstance => DataContext, 
						DialogHostOpenDialogCommandDataContextSource.None => null, 
						_ => throw new ArgumentOutOfRangeException(), 
					};
				}
				DialogContent = executedRoutedEventArgs.Parameter;
			}
			SetCurrentValue(IsOpenProperty, true);
			executedRoutedEventArgs.Handled = true;
		}

		private void CloseDialogCanExecute(object sender, CanExecuteRoutedEventArgs canExecuteRoutedEventArgs)
		{
			canExecuteRoutedEventArgs.CanExecute = CurrentSession != null;
		}

		private void CloseDialogHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (!executedRoutedEventArgs.Handled)
			{
				InternalClose(executedRoutedEventArgs.Parameter);
				executedRoutedEventArgs.Handled = true;
			}
		}

		private string GetStateName()
		{
			if (!IsOpen)
			{
				return "Closed";
			}
			return "Open";
		}

		private void OnUnloaded(object sender, RoutedEventArgs routedEventArgs)
		{
			foreach (WeakReference<DialogHost> item in LoadedInstances.ToList())
			{
				if (!item.TryGetTarget(out var target) || target == this)
				{
					LoadedInstances.Remove(item);
					break;
				}
			}
		}

		private void OnLoaded(object sender, RoutedEventArgs routedEventArgs)
		{
			foreach (WeakReference<DialogHost> item in LoadedInstances.ToList())
			{
				if (item.TryGetTarget(out var target) && target == this)
				{
					return;
				}
			}
			LoadedInstances.Add(new WeakReference<DialogHost>(this));
			if (IsOpen)
			{
				Popup popup = _popup;
				if (popup != null && !popup.IsOpen)
				{
					popup.IsOpen = true;
					(popup as PopupEx)?.RefreshPosition();
				}
			}
		}

