	public class DialogSession
	{
		private readonly DialogHost _owner;

		public bool IsEnded { get; internal set; }

		internal object? CloseParameter { get; set; }

		public object? Content => _owner.DialogContent;

		internal DialogSession(DialogHost owner)
		{
			_owner = owner ?? throw new ArgumentNullException("owner");
		}

		public void UpdateContent(object? content)
		{
			_owner.AssertTargetableContent();
			_owner.DialogContent = content;
			_owner.Dispatcher.BeginInvoke(DispatcherPriority.Background, (Action)(() =>
			{
				_owner.FocusPopup();
			}));
		}

		public void Close()
		{
			if (IsEnded)
			{
				throw new InvalidOperationException("Dialog session has ended.");
			}
			_owner.InternalClose(null);
		}

		public void Close(object? parameter)
		{
			if (IsEnded)
			{
				throw new InvalidOperationException("Dialog session has ended.");
			}
			_owner.InternalClose(parameter);
		}
	}
	internal static class DpiHelper
	{
		private static readonly int DpiX;

		private static readonly int DpiY;

		private const double StandardDpiX = 96.0;

		private const double StandardDpiY = 96.0;

		static DpiHelper()
		{
			PropertyInfo propertyInfo = typeof(SystemParameters).GetProperty("DpiX", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new InvalidOperationException("Could not find DpiX property on SystemParameters");
			PropertyInfo? propertyInfo2 = typeof(SystemParameters).GetProperty("Dpi", BindingFlags.Static | BindingFlags.NonPublic) ?? throw new InvalidOperationException("Could not find Dpi property on SystemParameters");
			DpiX = (int)propertyInfo.GetValue(null, null);
			DpiY = (int)propertyInfo2.GetValue(null, null);
		}

		public static double TransformToDeviceY(Visual visual, double y)
		{
			PresentationSource presentationSource = PresentationSource.FromVisual(visual);
			if (presentationSource?.CompositionTarget != null)
			{
				return y * presentationSource.CompositionTarget.TransformToDevice.M22;
			}
			return TransformToDeviceY(y);
		}

		public static double TransformFromDeviceY(Visual visual, double y)
		{
			PresentationSource presentationSource = PresentationSource.FromVisual(visual);
			if (presentationSource?.CompositionTarget != null)
			{
				return y / presentationSource.CompositionTarget.TransformToDevice.M22;
			}
			return TransformFromDeviceY(y);
		}

		public static double TransformToDeviceX(Visual visual, double x)
		{
			PresentationSource presentationSource = PresentationSource.FromVisual(visual);
			if (presentationSource?.CompositionTarget != null)
			{
				return x * presentationSource.CompositionTarget.TransformToDevice.M11;
			}
			return TransformToDeviceX(x);
		}

		public static double TransformFromDeviceX(Visual visual, double x)
		{
			PresentationSource presentationSource = PresentationSource.FromVisual(visual);
			if (presentationSource?.CompositionTarget != null)
			{
				return x / presentationSource.CompositionTarget.TransformToDevice.M11;
			}
			return TransformFromDeviceX(x);
		}

		public static double TransformToDeviceY(double y)
		{
			return y * (double)DpiY / 96.0;
		}

		public static double TransformFromDeviceY(double y)
		{
			return y / (double)DpiY * 96.0;
		}

		public static double TransformToDeviceX(double x)
		{
			return x * (double)DpiX / 96.0;
		}

		public static double TransformFromDeviceX(double x)
		{
			return x / (double)DpiX * 96.0;
		}
	}
