		private static void OnBlurPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			((DrawerHost)d).HandleBackgroundBlur();
		}

		protected void OnDrawerOpened(DrawerOpenedEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		protected void OnDrawerClosing(DrawerClosingEventArgs eventArgs)
		{
			RaiseEvent(eventArgs);
		}

		public override void OnApplyTemplate()
		{
			if (_templateContentCoverElement != null)
			{
				_templateContentCoverElement.PreviewMouseLeftButtonUp += TemplateContentCoverElementOnPreviewMouseLeftButtonUp;
			}
			WireDrawer(_leftDrawerElement, unwire: true);
			WireDrawer(_topDrawerElement, unwire: true);
			WireDrawer(_rightDrawerElement, unwire: true);
			WireDrawer(_bottomDrawerElement, unwire: true);
			base.OnApplyTemplate();
			_templateContentCoverElement = GetTemplateChild("PART_ContentCover") as FrameworkElement;
			if (_templateContentCoverElement != null)
			{
				_templateContentCoverElement.PreviewMouseLeftButtonUp += TemplateContentCoverElementOnPreviewMouseLeftButtonUp;
			}
			_leftDrawerElement = WireDrawer(GetTemplateChild("PART_LeftDrawer") as FrameworkElement, unwire: false);
			_topDrawerElement = WireDrawer(GetTemplateChild("PART_TopDrawer") as FrameworkElement, unwire: false);
			_rightDrawerElement = WireDrawer(GetTemplateChild("PART_RightDrawer") as FrameworkElement, unwire: false);
			_bottomDrawerElement = WireDrawer(GetTemplateChild("PART_BottomDrawer") as FrameworkElement, unwire: false);
			UpdateVisualStates(false);
		}

		private FrameworkElement? WireDrawer(FrameworkElement? drawerElement, bool unwire)
		{
			if (drawerElement == null)
			{
				return null;
			}
			if (unwire)
			{
				drawerElement.GotFocus -= DrawerElement_GotFocus;
				drawerElement.MouseDown -= DrawerElement_MouseDown;
				return drawerElement;
			}
			drawerElement.GotFocus += DrawerElement_GotFocus;
			drawerElement.MouseDown += DrawerElement_MouseDown;
			return drawerElement;
		}

		private void DrawerElement_MouseDown(object sender, MouseButtonEventArgs e)
		{
			ReactToFocus(sender);
		}

		private void DrawerElement_GotFocus(object sender, RoutedEventArgs e)
		{
			ReactToFocus(sender);
		}

		private void ReactToFocus(object sender)
		{
			if (sender == _leftDrawerElement)
			{
				PrepareZIndexes(LeftDrawerZIndexPropertyKey);
			}
			else if (sender == _topDrawerElement)
			{
				PrepareZIndexes(TopDrawerZIndexPropertyKey);
			}
			else if (sender == _rightDrawerElement)
			{
				PrepareZIndexes(RightDrawerZIndexPropertyKey);
			}
			else if (sender == _bottomDrawerElement)
			{
				PrepareZIndexes(BottomDrawerZIndexPropertyKey);
			}
		}

		private void TemplateContentCoverElementOnPreviewMouseLeftButtonUp(object sender, MouseButtonEventArgs mouseButtonEventArgs)
		{
			if (LeftDrawerCloseOnClickAway)
			{
				SetCurrentValue(IsLeftDrawerOpenProperty, false);
			}
			if (RightDrawerCloseOnClickAway)
			{
				SetCurrentValue(IsRightDrawerOpenProperty, false);
			}
			if (TopDrawerCloseOnClickAway)
			{
				SetCurrentValue(IsTopDrawerOpenProperty, false);
			}
			if (BottomDrawerCloseOnClickAway)
			{
				SetCurrentValue(IsBottomDrawerOpenProperty, false);
			}
		}

		private void UpdateVisualStates(bool? useTransitions = null)
		{
			bool flag = IsAnyDrawerOpen();
			VisualStateManager.GoToState(this, (!flag) ? "AllClosed" : "AnyOpen", useTransitions ?? (!TransitionAssist.GetDisableTransitions(this)));
			VisualStateManager.GoToState(this, IsLeftDrawerOpen ? "LeftDrawerOpen" : "LeftDrawerClosed", useTransitions ?? (!TransitionAssist.GetDisableTransitions(this)));
			VisualStateManager.GoToState(this, IsTopDrawerOpen ? "TopDrawerOpen" : "TopDrawerClosed", useTransitions ?? (!TransitionAssist.GetDisableTransitions(this)));
			VisualStateManager.GoToState(this, IsRightDrawerOpen ? "RightDrawerOpen" : "RightDrawerClosed", useTransitions ?? (!TransitionAssist.GetDisableTransitions(this)));
			VisualStateManager.GoToState(this, IsBottomDrawerOpen ? "BottomDrawerOpen" : "BottomDrawerClosed", useTransitions ?? (!TransitionAssist.GetDisableTransitions(this)));
		}

		private static void IsTopDrawerOpenPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			IsDrawerOpenPropertyChanged(dependencyObject, dependencyPropertyChangedEventArgs, Dock.Top);
		}

		private static void IsLeftDrawerOpenPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			IsDrawerOpenPropertyChanged(dependencyObject, dependencyPropertyChangedEventArgs, Dock.Left);
		}

		private static void IsRightDrawerOpenPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			IsDrawerOpenPropertyChanged(dependencyObject, dependencyPropertyChangedEventArgs, Dock.Right);
		}

		private static void IsBottomDrawerOpenPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			IsDrawerOpenPropertyChanged(dependencyObject, dependencyPropertyChangedEventArgs, Dock.Bottom);
		}

		private static void IsDrawerOpenPropertyChanged(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs, Dock dock)
		{
			DrawerHost drawerHost = (DrawerHost)dependencyObject;
			bool flag = (bool)dependencyPropertyChangedEventArgs.NewValue;
			if (!flag)
			{
				DrawerClosingEventArgs e = new DrawerClosingEventArgs(dock, DrawerClosingEvent);
				drawerHost.OnDrawerClosing(e);
				if (e.IsCancelled)
				{
					drawerHost.SetCurrentValue(dependencyPropertyChangedEventArgs.Property, dependencyPropertyChangedEventArgs.OldValue);
					return;
				}
			}
			if (!drawerHost._lockZIndexes & flag)
			{
				drawerHost.PrepareZIndexes(drawerHost._zIndexPropertyLookup[dependencyPropertyChangedEventArgs.Property]);
			}
			drawerHost.UpdateVisualStates();
			drawerHost.HandleBackgroundBlur(flag);
			if (flag)
			{
				RaiseDrawerOpened(drawerHost, dock);
			}
		}

		private void HandleBackgroundBlur(bool? isOpened = null)
		{
			bool valueOrDefault = isOpened == true;
			if (!isOpened.HasValue)
			{
				valueOrDefault = IsAnyDrawerOpen();
				isOpened = valueOrDefault;
			}
			if (Content is UIElement uIElement)
			{
				if (ApplyBlurBackground && isOpened.Value)
				{
					uIElement.Effect = new BlurEffect
					{
						Radius = BlurRadius
					};
				}
				else
				{
					uIElement.Effect = null;
				}
			}
		}

		private bool IsAnyDrawerOpen()
		{
			if (!IsLeftDrawerOpen && !IsTopDrawerOpen && !IsRightDrawerOpen)
			{
				return IsBottomDrawerOpen;
			}
			return true;
		}

		private static void RaiseDrawerOpened(DrawerHost drawerHost, Dock dock)
		{
			DrawerOpenedEventArgs eventArgs = new DrawerOpenedEventArgs(dock, DrawerOpenedEvent);
			drawerHost.OnDrawerOpened(eventArgs);
		}

		private void PrepareZIndexes(DependencyPropertyKey zIndexDependencyPropertyKey)
		{
			foreach (var item in new DependencyPropertyKey[1] { zIndexDependencyPropertyKey }.Concat(from dpk in _zIndexPropertyLookup.Values.Except(new DependencyPropertyKey[1] { zIndexDependencyPropertyKey })
				orderby (int)GetValue(dpk.DependencyProperty) descending
				select dpk).Reverse().Select((DependencyPropertyKey dpk, int idx) => new { dpk, idx }))
			{
				SetValue(item.dpk, item.idx);
			}
		}

		private void CloseDrawerHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (executedRoutedEventArgs.Handled)
			{
				return;
			}
			if (executedRoutedEventArgs.Parameter is Dock dock)
			{
				DrawerClosingEventArgs e = new DrawerClosingEventArgs(dock, DrawerClosingEvent);
				OnDrawerClosing(e);
				if (e.IsCancelled)
				{
					return;
				}
			}
			SetOpenFlag(executedRoutedEventArgs, value: false);
			executedRoutedEventArgs.Handled = true;
		}

		private void OpenDrawerHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (!executedRoutedEventArgs.Handled)
			{
				SetOpenFlag(executedRoutedEventArgs, value: true);
				executedRoutedEventArgs.Handled = true;
			}
		}

		private void SetOpenFlag(ExecutedRoutedEventArgs executedRoutedEventArgs, bool value)
		{
			object parameter = executedRoutedEventArgs.Parameter;
			if (parameter is Dock)
			{
				switch ((Dock)parameter)
				{
				case Dock.Left:
					SetCurrentValue(IsLeftDrawerOpenProperty, value);
					break;
				case Dock.Top:
					SetCurrentValue(IsTopDrawerOpenProperty, value);
					break;
				case Dock.Right:
					SetCurrentValue(IsRightDrawerOpenProperty, value);
					break;
				case Dock.Bottom:
					SetCurrentValue(IsBottomDrawerOpenProperty, value);
					break;
				default:
					throw new ArgumentOutOfRangeException();
				}
				return;
			}
			try
			{
				_lockZIndexes = true;
				SetCurrentValue(IsLeftDrawerOpenProperty, value);
				SetCurrentValue(IsTopDrawerOpenProperty, value);
				SetCurrentValue(IsRightDrawerOpenProperty, value);
				SetCurrentValue(IsBottomDrawerOpenProperty, value);
			}
			finally
			{
				_lockZIndexes = false;
			}
		}
	}
