		{
			Flipper flipper = (Flipper)d;
			RoutedPropertyChangedEventArgs<bool> e2 = new RoutedPropertyChangedEventArgs<bool>((bool)e.OldValue, (bool)e.NewValue)
			{
				RoutedEvent = IsFlippedChangedEvent
			};
			flipper.RaiseEvent(e2);
