			FrontContentStringFormatProperty = DependencyProperty.Register("FrontContentStringFormat", typeof(string), typeof(FlipperClassic), new PropertyMetadata((object)null));
			BackContentProperty = DependencyProperty.Register("BackContent", typeof(object), typeof(FlipperClassic), new PropertyMetadata((object)null));
