			BackContentTemplateSelectorProperty = DependencyProperty.Register("BackContentTemplateSelector", typeof(DataTemplateSelector), typeof(FlipperClassic), new PropertyMetadata((object)null));
			BackContentStringFormatProperty = DependencyProperty.Register("BackContentStringFormat", typeof(string), typeof(FlipperClassic), new PropertyMetadata((object)null));
			IsFlippedProperty = DependencyProperty.Register("IsFlipped", typeof(bool), typeof(FlipperClassic), new PropertyMetadata(false, IsFlippedPropertyChangedCallback));
			IsFlippedChangedEvent = EventManager.RegisterRoutedEvent("IsFlipped", RoutingStrategy.Bubble, typeof(RoutedPropertyChangedEventHandler<bool>), typeof(FlipperClassic));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(FlipperClassic), new FrameworkPropertyMetadata(typeof(FlipperClassic)));
		}

		public FlipperClassic()
		{
			CommandBindings.Add(new CommandBinding(FlipCommand, FlipHandler));
		}

		private static void IsFlippedPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			FlipperClassic flipperClassic = (FlipperClassic)dependencyObject;
			flipperClassic.UpdateVisualStates(useTransitions: true);
			flipperClassic.RemeasureDuringFlip();
			OnIsFlippedChanged(flipperClassic, dependencyPropertyChangedEventArgs);
		}

		private static void OnIsFlippedChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			FlipperClassic flipperClassic = (FlipperClassic)d;
			RoutedPropertyChangedEventArgs<bool> e2 = new RoutedPropertyChangedEventArgs<bool>((bool)e.OldValue, (bool)e.NewValue)
			{
				RoutedEvent = IsFlippedChangedEvent
			};
			flipperClassic.RaiseEvent(e2);
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			UpdateVisualStates(useTransitions: false);
			_plane3D = GetTemplateChild("PART_Plane3D") as Plane3D;
		}

		private void RemeasureDuringFlip()
		{
			TimeSpan interval = new TimeSpan(0, 0, 0, 0, 66);
			int refreshCount = 0;
			Plane3D plane3D = _plane3D;
			if (plane3D == null)
			{
				return;
			}
			DispatcherTimer dt = null;
			dt = new DispatcherTimer(interval, DispatcherPriority.Normal, (object? sender, EventArgs args) =>
			{
				plane3D.InvalidateMeasure();
				if (refreshCount++ == 6)
				{
					dt?.Stop();
				}
			}, Dispatcher);
			dt.Start();
		}

		private void UpdateVisualStates(bool useTransitions)
		{
			VisualStateManager.GoToState(this, IsFlipped ? "Flipped" : "Unflipped", useTransitions);
		}

		private void FlipHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			SetCurrentValue(IsFlippedProperty, !IsFlipped);
		}
	}
