		private static readonly List<HintProxyBuilder> Builders;

		static HintProxyFabric()
		{
			Builders = new List<HintProxyBuilder>();
			Builders.Add(new HintProxyBuilder((Control? c) => c is ComboBox, (Control c) => new ComboBoxHintProxy((ComboBox)c)));
			Builders.Add(new HintProxyBuilder((Control? c) => c is TextBox, (Control c) => new TextBoxHintProxy((TextBox)c)));
			Builders.Add(new HintProxyBuilder((Control? c) => c is RichTextBox, (Control c) => new RichTextBoxHintProxy((RichTextBox)c)));
			Builders.Add(new HintProxyBuilder((Control? c) => c is PasswordBox, (Control c) => new PasswordBoxHintProxy((PasswordBox)c)));
		}

		public static void RegisterBuilder(Func<Control?, bool> canBuild, Func<Control, IHintProxy> build)
		{
			Builders.Add(new HintProxyBuilder(canBuild, build));
		}

		public static IHintProxy? Get(Control? control)
		{
			if (control == null)
			{
				return null;
			}
			return Builders.FirstOrDefault((HintProxyBuilder v) => v.CanBuild(control))?.Build(control);
		}
	}
