	internal sealed class InheritSystemColorTypeConverter : TypeConverter
	{
		private const string Inherit = "Inherit";

		private ColorConverter ColorConverter { get; } = new ColorConverter();

		public override bool CanConvertFrom(ITypeDescriptorContext? context, Type sourceType)
		{
			if (!(sourceType == typeof(string)) && !ColorConverter.CanConvertFrom(context, sourceType))
			{
				return base.CanConvertFrom(context, sourceType);
			}
			return true;
		}

		public override bool CanConvertTo(ITypeDescriptorContext? context, [NotNullWhen(true)] Type? destinationType)
		{
			if (!ColorConverter.CanConvertTo(context, destinationType))
			{
				return base.CanConvertTo(context, destinationType);
			}
			return true;
		}

		public override object ConvertFrom(ITypeDescriptorContext? td, CultureInfo? ci, object? value)
		{
			if (value == null)
			{
				throw GetConvertFromException(value);
			}
			string text = (value as string) ?? throw new ArgumentNullException("value");
			if (string.Equals(text, "Inherit", StringComparison.OrdinalIgnoreCase))
			{
				return Theme.GetSystemAccentColor().GetValueOrDefault();
			}
			return ColorConverter.ConvertFrom(td, ci, text);
		}

		public override object ConvertTo(ITypeDescriptorContext? context, CultureInfo? culture, object? value, Type destinationType)
		{
			if (value is Color color && color != default(Color))
			{
				Color value2 = color;
				Color? systemAccentColor = Theme.GetSystemAccentColor();
				if (value2 == systemAccentColor)
				{
					return "Inherit";
				}
			}
			return ColorConverter.ConvertTo(context, culture, value, destinationType);
		}
	}
