	public static class ListBoxAssist
	{
		public static readonly DependencyProperty IsToggleProperty;

		public static readonly DependencyProperty CanUserToggleSelectedItemProperty;

		static ListBoxAssist()
		{
			IsToggleProperty = DependencyProperty.RegisterAttached("IsToggle", typeof(bool), typeof(ListBoxAssist), new FrameworkPropertyMetadata(false));
			CanUserToggleSelectedItemProperty = DependencyProperty.RegisterAttached("CanUserToggleSelectedItem", typeof(bool), typeof(ListBoxAssist), new FrameworkPropertyMetadata(false));
			EventManager.RegisterClassHandler(typeof(ListBox), UIElement.PreviewMouseLeftButtonDownEvent, new MouseButtonEventHandler(ListBoxMouseButtonEvent));
		}

		private static void ListBoxMouseButtonEvent(object sender, MouseButtonEventArgs mouseButtonEventArgs)
		{
			UIElement uIElement = (UIElement)sender;
			if (!GetIsToggle(uIElement))
			{
				return;
			}
			Point position = mouseButtonEventArgs.GetPosition(uIElement);
			HitTestResult hitTestResult = VisualTreeHelper.HitTest(uIElement, position);
			if (hitTestResult == null)
			{
				return;
			}
			ListBoxItem listBoxItem = null;
			Ripple ripple = null;
			foreach (DependencyObject item in hitTestResult.VisualHit.GetVisualAncestry().TakeWhile((DependencyObject _) => listBoxItem == null))
			{
				listBoxItem = item as ListBoxItem;
				if (ripple == null)
				{
					ripple = item as Ripple;
				}
			}
			if (listBoxItem != null && listBoxItem.IsEnabled)
			{
				listBoxItem.SetCurrentValue(ListBoxItem.IsSelectedProperty, !GetCanUserToggleSelectedItem(uIElement) || !listBoxItem.IsSelected);
				mouseButtonEventArgs.Handled = true;
				listBoxItem.Focus();
				if (ripple != null && listBoxItem.IsSelected)
				{
					ripple.RaiseEvent(new MouseButtonEventArgs(mouseButtonEventArgs.MouseDevice, mouseButtonEventArgs.Timestamp, mouseButtonEventArgs.ChangedButton)
					{
						RoutedEvent = UIElement.PreviewMouseLeftButtonDownEvent,
						Source = ripple
					});
				}
			}
		}

		public static void SetIsToggle(DependencyObject element, bool value)
		{
			element.SetValue(IsToggleProperty, value);
		}

		public static bool GetIsToggle(DependencyObject element)
		{
			return (bool)element.GetValue(IsToggleProperty);
		}

		public static void SetCanUserToggleSelectedItem(DependencyObject element, bool value)
		{
			element.SetValue(CanUserToggleSelectedItemProperty, value);
		}

		public static bool GetCanUserToggleSelectedItem(DependencyObject element)
		{
			return (bool)element.GetValue(CanUserToggleSelectedItemProperty);
		}
	}
