	[TemplateVisualState(GroupName = "Direction", Name = "None")]
	[TemplateVisualState(GroupName = "Direction", Name = "Ascending")]
	[TemplateVisualState(GroupName = "Direction", Name = "Descending")]
	public class ListSortDirectionIndicator : Control
	{
		public const string DirectionGroupName = "Direction";

		public const string NoneStateName = "None";

		public const string AscendingStateName = "Ascending";

		public const string DescendingStateName = "Descending";

		public static readonly DependencyProperty ListSortDirectionProperty;

		private static readonly DependencyPropertyKey IsNeutralPropertyKey;

		public static readonly DependencyProperty IsNeutralProperty;

		public ListSortDirection? ListSortDirection
		{
			get
			{
				return (ListSortDirection?)GetValue(ListSortDirectionProperty);
			}
			set
			{
				SetValue(ListSortDirectionProperty, value);
			}
		}

		public bool IsNeutral
		{
			get
			{
				return (bool)GetValue(IsNeutralProperty);
			}
			private set
			{
				SetValue(IsNeutralPropertyKey, value);
			}
		}

		static ListSortDirectionIndicator()
		{
			ListSortDirectionProperty = DependencyProperty.Register("ListSortDirection", typeof(ListSortDirection?), typeof(ListSortDirectionIndicator), new PropertyMetadata(null, ListSortDirectionPropertyChangedCallback));
			IsNeutralPropertyKey = DependencyProperty.RegisterReadOnly("IsNeutral", typeof(bool), typeof(ListSortDirectionIndicator), new PropertyMetadata(true));
			IsNeutralProperty = IsNeutralPropertyKey.DependencyProperty;
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(ListSortDirectionIndicator), new FrameworkPropertyMetadata(typeof(ListSortDirectionIndicator)));
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			GotoVisualState(useTransitions: true, ListSortDirection);
		}

		private static void ListSortDirectionPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			ListSortDirectionIndicator listSortDirectionIndicator = (ListSortDirectionIndicator)dependencyObject;
			listSortDirectionIndicator.GotoVisualState(useTransitions: true, listSortDirectionIndicator.ListSortDirection);
			listSortDirectionIndicator.IsNeutral = !listSortDirectionIndicator.ListSortDirection.HasValue;
		}

		private void GotoVisualState(bool useTransitions, ListSortDirection? direction)
		{
			string stateName;
			if (direction.HasValue)
			{
				stateName = ((direction.Value == System.ComponentModel.ListSortDirection.Ascending) ? "Ascending" : "Descending");
			}
			else
			{
				stateName = "None";
			}
			VisualStateManager.GoToState(this, stateName, useTransitions);
		}
	}
