		public static readonly DependencyProperty IsDayInFirstComponentProperty;

		public DateTime DisplayDate
		{
			get
			{
				return (DateTime)GetValue(DisplayDateProperty);
			}
			set
			{
				SetValue(DisplayDateProperty, value);
			}
		}

