			}
			private set
			{
				SetValue(ComponentThreeContentPropertyKey, value);
			}
		}

		public bool IsDayInFirstComponent
		{
			get
			{
				return (bool)GetValue(IsDayInFirstComponentProperty);
			}
			private set
			{
				SetValue(IsDayInFirstComponentPropertyKey, value);
			}
		}

		static MaterialDateDisplay()
		{
			DisplayDateProperty = DependencyProperty.Register("DisplayDate", typeof(DateTime), typeof(MaterialDateDisplay), new PropertyMetadata(default(DateTime), DisplayDatePropertyChangedCallback, DisplayDateCoerceValue));
			ComponentOneContentPropertyKey = DependencyProperty.RegisterReadOnly("ComponentOneContent", typeof(string), typeof(MaterialDateDisplay), new PropertyMetadata((object)null));
			ComponentOneContentProperty = ComponentOneContentPropertyKey.DependencyProperty;
			ComponentTwoContentPropertyKey = DependencyProperty.RegisterReadOnly("ComponentTwoContent", typeof(string), typeof(MaterialDateDisplay), new PropertyMetadata((object)null));
			ComponentTwoContentProperty = ComponentTwoContentPropertyKey.DependencyProperty;
			ComponentThreeContentPropertyKey = DependencyProperty.RegisterReadOnly("ComponentThreeContent", typeof(string), typeof(MaterialDateDisplay), new PropertyMetadata((object)null));
			ComponentThreeContentProperty = ComponentThreeContentPropertyKey.DependencyProperty;
			IsDayInFirstComponentPropertyKey = DependencyProperty.RegisterReadOnly("IsDayInFirstComponent", typeof(bool), typeof(MaterialDateDisplay), new PropertyMetadata(false));
			IsDayInFirstComponentProperty = IsDayInFirstComponentPropertyKey.DependencyProperty;
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(MaterialDateDisplay), new FrameworkPropertyMetadata(typeof(MaterialDateDisplay)));
		}

		public MaterialDateDisplay()
		{
			SetCurrentValue(DisplayDateProperty, DateTime.Today);
		}

		private static object DisplayDateCoerceValue(DependencyObject d, object baseValue)
		{
			if (d is FrameworkElement frameworkElement)
			{
				CultureInfo specificCulture = frameworkElement.Language.GetSpecificCulture();
				if (specificCulture != null && baseValue is DateTime dateTime)
				{
					if (dateTime < specificCulture.Calendar.MinSupportedDateTime)
					{
						return specificCulture.Calendar.MinSupportedDateTime;
					}
					if (dateTime > specificCulture.Calendar.MaxSupportedDateTime)
					{
						return specificCulture.Calendar.MaxSupportedDateTime;
					}
				}
			}
			return baseValue;
		}

		private static void DisplayDatePropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			((MaterialDateDisplay)dependencyObject).UpdateComponents();
		}

		private void UpdateComponents()
		{
			CultureInfo specificCulture = Language.GetSpecificCulture();
			DateTimeFormatInfo dateFormat = specificCulture.GetDateFormat();
			DateTime minSupportedDateTime = dateFormat.Calendar.MinSupportedDateTime;
			DateTime maxSupportedDateTime = dateFormat.Calendar.MaxSupportedDateTime;
			if (DisplayDate < minSupportedDateTime)
			{
				SetDisplayDateOfCalendar(minSupportedDateTime);
				return;
			}
			if (DisplayDate > maxSupportedDateTime)
			{
				SetDisplayDateOfCalendar(maxSupportedDateTime);
				return;
			}
			CalendarFormatInfo calendarFormatInfo = CalendarFormatInfo.FromCultureInfo(specificCulture);
			DateTime displayDate = DisplayDate;
			ComponentOneContent = FormatDate(calendarFormatInfo.ComponentOnePattern, displayDate, specificCulture);
			ComponentTwoContent = FormatDate(calendarFormatInfo.ComponentTwoPattern, displayDate, specificCulture);
			ComponentThreeContent = FormatDate(calendarFormatInfo.ComponentThreePattern, displayDate, specificCulture);
		}

		private static string FormatDate(string format, DateTime displayDate, CultureInfo culture)
		{
			if (!string.IsNullOrEmpty(format))
			{
				return displayDate.ToString(format, culture).ToTitleCase(culture);
			}
			return string.Empty;
		}

		private void SetDisplayDateOfCalendar(DateTime displayDate)
		{
			System.Windows.Controls.Calendar calendar = this.GetVisualAncestry().OfType<System.Windows.Controls.Calendar>().FirstOrDefault();
			if (calendar != null)
			{
				calendar.DisplayDate = displayDate;
			}
		}
	}
