	public class PackIcon : Control
	{
		private static readonly Lazy<IDictionary<PackIconKind, string>> _dataIndex;

		public static readonly DependencyProperty KindProperty;

		private static readonly DependencyPropertyKey DataPropertyKey;

		public static readonly DependencyProperty DataProperty;

		public PackIconKind Kind
		{
			get
			{
				return (PackIconKind)GetValue(KindProperty);
			}
			set
			{
				SetValue(KindProperty, value);
			}
		}

		[TypeConverter(typeof(GeometryConverter))]
		public string? Data
		{
			get
			{
				return (string)GetValue(DataProperty);
			}
			private set
			{
				SetValue(DataPropertyKey, value);
			}
		}

		static PackIcon()
		{
			_dataIndex = new Lazy<IDictionary<PackIconKind, string>>(PackIconDataFactory.Create);
			KindProperty = DependencyProperty.Register("Kind", typeof(PackIconKind), typeof(PackIcon), new PropertyMetadata(PackIconKind.Abacus, KindPropertyChangedCallback));
			DataPropertyKey = DependencyProperty.RegisterReadOnly("Data", typeof(string), typeof(PackIcon), new PropertyMetadata(""));
			DataProperty = DataPropertyKey.DependencyProperty;
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(PackIcon), new FrameworkPropertyMetadata(typeof(PackIcon)));
		}

		private static void KindPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			((PackIcon)dependencyObject).UpdateData();
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			UpdateData();
		}

		private void UpdateData()
		{
			string value = null;
			_dataIndex.Value?.TryGetValue(Kind, out value);
			Data = value;
		}
	}
