	public class Palette
	{
		public Swatch PrimarySwatch { get; }

		public Swatch SecondarySwatch { get; }

		public int PrimaryLightHueIndex { get; }

		public int PrimaryMidHueIndex { get; }

		public int PrimaryDarkHueIndex { get; }

		public int SecondaryHueIndex { get; }

		public Palette(Swatch primarySwatch, Swatch secondarySwatch, int primaryLightHueIndex, int primaryMidHueIndex, int primaryDarkHueIndex, int secondaryHueIndex)
		{
			PrimarySwatch = primarySwatch;
			SecondarySwatch = secondarySwatch;
			PrimaryLightHueIndex = primaryLightHueIndex;
			PrimaryMidHueIndex = primaryMidHueIndex;
			PrimaryDarkHueIndex = primaryDarkHueIndex;
			SecondaryHueIndex = secondaryHueIndex;
		}
	}
	public class PaletteHelper
	{
		public virtual Theme GetTheme()
		{
			if (Application.Current == null)
			{
				throw new InvalidOperationException("Cannot get theme outside of a WPF application. Use ResourceDictionaryExtensions.GetTheme on the appropriate resource dictionary instead.");
			}
			return GetResourceDictionary().GetTheme();
		}

		public virtual void SetTheme(Theme theme)
		{
			if (theme == null)
			{
				throw new ArgumentNullException("theme");
			}
			if (Application.Current == null)
			{
				throw new InvalidOperationException("Cannot set theme outside of a WPF application. Use ResourceDictionaryExtensions.SetTheme on the appropriate resource dictionary instead.");
			}
			GetResourceDictionary().SetTheme(theme);
			RecreateThemeDictionaries();
		}

		public virtual IThemeManager? GetThemeManager()
		{
			if (Application.Current == null)
			{
				throw new InvalidOperationException("Cannot get ThemeManager outside of a WPF application. Use ResourceDictionaryExtensions.GetThemeManager on the appropriate resource dictionary instead.");
			}
			return GetResourceDictionary().GetThemeManager();
		}

		private static ResourceDictionary GetResourceDictionary()
		{
			return Application.Current.Resources.MergedDictionaries.FirstOrDefault((ResourceDictionary x) => x is IMaterialDesignThemeDictionary) ?? Application.Current.Resources;
		}

		private static void RecreateThemeDictionaries()
		{
			ResourceDictionary resources = Application.Current.Resources;
			bool flag = default;
			for (int i = 0; i < resources.MergedDictionaries.Count; i++)
			{
				ResourceDictionary resourceDictionary = resources.MergedDictionaries[i];
				object obj = resourceDictionary["MaterialDesign.Resources.RecreateOnThemeChange"];
				int num;
				if (obj is bool)
				{
					flag = (bool)obj;
					num = 1;
				}
				else
				{
					num = 0;
				}
				if (((uint)num & (flag ? 1u : 0u)) != 0)
				{
					resources.MergedDictionaries.RemoveAt(i);
					resources.MergedDictionaries.Insert(i, new ResourceDictionary
					{
						Source = resourceDictionary.Source
					});
				}
			}
		}
	}
	public static class PasswordBoxAssist
	{
		public static readonly DependencyProperty PasswordMaskedIconProperty = DependencyProperty.RegisterAttached("PasswordMaskedIcon", typeof(PackIconKind), typeof(PasswordBoxAssist), new FrameworkPropertyMetadata(PackIconKind.EyeOff, FrameworkPropertyMetadataOptions.Inherits));

		public static readonly DependencyProperty PasswordRevealedIconProperty = DependencyProperty.RegisterAttached("PasswordRevealedIcon", typeof(PackIconKind), typeof(PasswordBoxAssist), new FrameworkPropertyMetadata(PackIconKind.Eye, FrameworkPropertyMetadataOptions.Inherits));

		public static readonly DependencyProperty IsPasswordRevealedProperty = DependencyProperty.RegisterAttached("IsPasswordRevealed", typeof(bool), typeof(PasswordBoxAssist), new FrameworkPropertyMetadata(false, FrameworkPropertyMetadataOptions.Inherits));

		public static readonly DependencyProperty IsRevealButtonTabStopProperty = DependencyProperty.RegisterAttached("IsRevealButtonTabStop", typeof(bool), typeof(PasswordBoxAssist), new PropertyMetadata(true));

		public static readonly DependencyProperty PasswordProperty = DependencyProperty.RegisterAttached("Password", typeof(string), typeof(PasswordBoxAssist), new FrameworkPropertyMetadata(null, HandlePasswordChanged)
		{
			BindsTwoWayByDefault = true,
			DefaultUpdateSourceTrigger = UpdateSourceTrigger.LostFocus
		});

		private static readonly DependencyProperty IsChangingProperty = DependencyProperty.RegisterAttached("IsChanging", typeof(bool), typeof(PasswordBoxAssist), new UIPropertyMetadata(false));

		internal static readonly DependencyProperty SuppressBindingGuardProperty = DependencyProperty.RegisterAttached("SuppressBindingGuard", typeof(bool), typeof(PasswordBoxAssist), new PropertyMetadata(false));

		public static void SetPasswordMaskedIcon(DependencyObject element, PackIconKind value)
		{
			element.SetValue(PasswordMaskedIconProperty, value);
		}

		public static PackIconKind GetPasswordMaskedIcon(DependencyObject element)
		{
			return (PackIconKind)element.GetValue(PasswordMaskedIconProperty);
		}

		public static void SetPasswordRevealedIcon(DependencyObject element, PackIconKind value)
		{
			element.SetValue(PasswordRevealedIconProperty, value);
		}

		public static PackIconKind GetPasswordRevealedIcon(DependencyObject element)
		{
			return (PackIconKind)element.GetValue(PasswordRevealedIconProperty);
		}

		public static void SetIsPasswordRevealed(DependencyObject element, bool value)
		{
			element.SetValue(IsPasswordRevealedProperty, value);
		}

		public static bool GetIsPasswordRevealed(DependencyObject element)
		{
			return (bool)element.GetValue(IsPasswordRevealedProperty);
		}

		public static void SetIsRevealButtonTabStop(DependencyObject element, bool value)
		{
			element.SetValue(IsRevealButtonTabStopProperty, value);
		}

		public static bool GetIsRevealButtonTabStop(DependencyObject element)
		{
			return (bool)element.GetValue(IsRevealButtonTabStopProperty);
		}

		public static void SetPassword(DependencyObject element, string value)
		{
			element.SetValue(PasswordProperty, value);
		}

		public static string GetPassword(DependencyObject element)
		{
			return (string)element.GetValue(PasswordProperty);
		}

		private static void SetIsChanging(UIElement element, bool value)
		{
			element.SetValue(IsChangingProperty, value);
		}

		private static bool GetIsChanging(UIElement element)
		{
			return (bool)element.GetValue(IsChangingProperty);
		}

		internal static void SetSuppressBindingGuard(DependencyObject element, bool value)
		{
			element.SetValue(SuppressBindingGuardProperty, value);
		}

		internal static bool GetSuppressBindingGuard(DependencyObject element)
		{
			return (bool)element.GetValue(SuppressBindingGuardProperty);
		}

		private static void HandlePasswordChanged(DependencyObject sender, DependencyPropertyChangedEventArgs e)
		{
			if (sender is PasswordBox passwordBox && (GetSuppressBindingGuard(passwordBox) || BindingOperations.GetBindingBase(passwordBox, PasswordProperty) != null))
			{
				passwordBox.PasswordChanged -= PasswordBoxPasswordChanged;
				if (!GetIsChanging(passwordBox))
				{
					passwordBox.Password = (string)e.NewValue;
				}
				passwordBox.PasswordChanged += PasswordBoxPasswordChanged;
			}
		}

		private static void PasswordBoxPasswordChanged(object sender, RoutedEventArgs e)
		{
			if (sender is PasswordBox passwordBox)
			{
				SetIsChanging(passwordBox, value: true);
				SetPassword(passwordBox, passwordBox.Password);
				SetIsChanging(passwordBox, value: false);
			}
		}
	}
	[ContentProperty("Child")]
	public class Plane3D : FrameworkElement
	{
		private class LayoutInvalidationCatcher : Decorator
		{
			protected override Size MeasureOverride(Size constraint)
			{
				if (Parent is Plane3D plane3D)
				{
					plane3D.InvalidateMeasure();
				}
				return base.MeasureOverride(constraint);
			}

			protected override Size ArrangeOverride(Size arrangeSize)
			{
				if (Parent is Plane3D plane3D)
				{
					plane3D.InvalidateArrange();
				}
				return base.ArrangeOverride(arrangeSize);
			}
		}

		private FrameworkElement? _logicalChild;

		private FrameworkElement? _visualChild;

		private FrameworkElement? _originalChild;

		private readonly QuaternionRotation3D _quaternionRotation = new QuaternionRotation3D();

		private readonly RotateTransform3D _rotationTransform = new RotateTransform3D();

		private Viewport3D? _viewport3D;

		private readonly ScaleTransform3D _scaleTransform = new ScaleTransform3D();

		private static readonly Point3D[] Mesh = new Point3D[4]
		{
			new Point3D(0.0, 0.0, 0.0),
