		{
			new Point(0.0, 1.0),
			new Point(0.0, 0.0),
			new Point(1.0, 0.0),
			new Point(1.0, 1.0)
		};

		private static readonly int[] Indices = new int[6] { 0, 2, 1, 0, 3, 2 };

