		private static readonly Vector3D YAxis = new Vector3D(0.0, 1.0, 0.0);

		private static readonly Vector3D ZAxis = new Vector3D(0.0, 0.0, 1.0);

		public static readonly DependencyProperty RotationXProperty = DependencyProperty.Register("RotationX", typeof(double), typeof(Plane3D), new UIPropertyMetadata(0.0, (DependencyObject d, DependencyPropertyChangedEventArgs args) =>
		{
