		public override void OnApplyTemplate()
		{
			if (_toggleButton != null)
			{
				_toggleButton.PreviewMouseLeftButtonUp -= ToggleButtonOnPreviewMouseLeftButtonUp;
			}
			base.OnApplyTemplate();
			_popup = GetTemplateChild("PART_Popup") as PopupEx;
			_popupContentControl = GetTemplateChild("PART_PopupContentControl") as ContentControl;
			_toggleButton = GetTemplateChild("PART_Toggle") as ToggleButton;
			_popup?.CommandBindings.Add(new CommandBinding(ClosePopupCommand, ClosePopupHandler));
			if (_toggleButton != null)
			{
				_toggleButton.PreviewMouseLeftButtonUp += ToggleButtonOnPreviewMouseLeftButtonUp;
			}
			VisualStateManager.GoToState(this, IsPopupOpen ? "IsOpen" : "IsClosed", useTransitions: false);
		}

		protected override void OnIsKeyboardFocusWithinChanged(DependencyPropertyChangedEventArgs e)
		{
			base.OnIsKeyboardFocusWithinChanged(e);
			if (IsPopupOpen && !IsKeyboardFocusWithin && !StaysOpen)
			{
				Close();
			}
		}

		protected override void OnMouseEnter(MouseEventArgs e)
		{
			if (IsEnabled && IsLoaded && (PopupMode == PopupBoxPopupMode.MouseOverEager || PopupMode == PopupBoxPopupMode.MouseOver))
			{
				if (_popupContentControl != null && PresentationSource.FromVisual(_popupContentControl) != null)
				{
					Point point = _popupContentControl.PointToScreen(default);
					point.Offset(0.0 - _popupContentControl.Margin.Left, 0.0 - _popupContentControl.Margin.Top);
					Point point2 = PointToScreen(_popupPointFromLastRequest);
					if (Math.Abs(point.X - point2.X) > ActualWidth / 3.0 || Math.Abs(point.Y - point2.Y) > ActualHeight / 3.0)
					{
						return;
					}
				}
				SetCurrentValue(IsPopupOpenProperty, true);
			}
			base.OnMouseEnter(e);
		}

		private void ClosePopupHandler(object? sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			IsPopupOpen = false;
		}

		private void OnLayoutUpdated(object? sender, EventArgs eventArgs)
		{
			if (_popupContentControl != null && _popup != null && (PopupMode == PopupBoxPopupMode.MouseOver || PopupMode == PopupBoxPopupMode.MouseOverEager) && _popupContentControl.TranslatePoint(default, this) != _lastRelativePosition)
			{
				_popup.RefreshPosition();
				_lastRelativePosition = _popupContentControl.TranslatePoint(default, this);
			}
		}

		protected override void OnMouseLeave(MouseEventArgs e)
		{
			if (PopupMode == PopupBoxPopupMode.MouseOverEager || PopupMode == PopupBoxPopupMode.MouseOver)
			{
				Close();
			}
			base.OnMouseLeave(e);
		}

		protected void Close()
		{
			if (IsPopupOpen)
			{
				SetCurrentValue(IsPopupOpenProperty, false);
			}
		}

		private CustomPopupPlacement[] GetPopupPlacement(Size popupSize, Size targetSize, Point _)
		{
			double popupHorizontalOffset = PopupHorizontalOffset;
			double popupVerticalOffset = PopupVerticalOffset;
			Size size = new Size(DpiHelper.TransformFromDeviceX(this, popupSize.Width), DpiHelper.TransformFromDeviceY(this, popupSize.Height));
			Size size2 = new Size(DpiHelper.TransformFromDeviceX(this, targetSize.Width), DpiHelper.TransformFromDeviceY(this, targetSize.Height));
			double x;
			double y;
			switch (PlacementMode)
			{
			case PopupBoxPlacementMode.BottomAndAlignLeftEdges:
				x = 0.0 + popupHorizontalOffset - UseOffsetIfRtl(size.Width);
				y = size2.Height + popupVerticalOffset;
				break;
			case PopupBoxPlacementMode.BottomAndAlignRightEdges:
				x = 0.0 - size.Width + size2.Width + popupHorizontalOffset + UseOffsetIfRtl(size.Width - size2.Width * 2.0);
				y = size2.Height + popupVerticalOffset;
				break;
			case PopupBoxPlacementMode.BottomAndAlignCentres:
