		private static void OnLostMouseCapture(object? sender, MouseEventArgs e)
		{
			if (!(sender is PopupBox popupBox) || object.Equals(Mouse.Captured, popupBox))
			{
				return;
			}
			if (object.Equals(e.OriginalSource, popupBox))
			{
				if ((Mouse.Captured == null || popupBox._popup == null) && !(Mouse.Captured as DependencyObject).IsDescendantOf(popupBox._popup))
				{
					popupBox.Close();
				}
			}
			else if ((Mouse.Captured as DependencyObject).GetVisualAncestry().Contains(popupBox._popup?.Child))
			{
				if (popupBox.IsPopupOpen && Mouse.Captured == null && GetCapture() == IntPtr.Zero)
				{
					Mouse.Capture(popupBox, CaptureMode.SubTree);
					e.Handled = true;
				}
			}
			else if (popupBox.StaysOpen && popupBox.IsPopupOpen)
			{
				if (GetCapture() == IntPtr.Zero)
				{
					Mouse.Capture(popupBox, CaptureMode.SubTree);
					e.Handled = true;
				}
			}
			else
			{
				popupBox.Close();
			}
		}

		private static void OnMouseButtonDown(object sender, MouseButtonEventArgs e)
		{
			PopupBox popupBox = (PopupBox)sender;
			if (!popupBox.IsKeyboardFocusWithin)
			{
				popupBox.Focus();
			}
			e.Handled = true;
			if (Mouse.Captured == popupBox && e.OriginalSource == popupBox)
			{
				popupBox.Close();
			}
		}

		protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e)
		{
			if (IsPopupOpen && !StaysOpen)
			{
				Close();
				e.Handled = true;
			}
			else
			{
				base.OnMouseLeftButtonUp(e);
			}
		}

		private void ToggleButtonOnPreviewMouseLeftButtonUp(object? sender, MouseButtonEventArgs mouseButtonEventArgs)
		{
			if (PopupMode == PopupBoxPopupMode.Click || !IsPopupOpen)
			{
				return;
			}
			if (ToggleCheckedContent != null)
			{
				OnToggleCheckedContentClick();
				if (ToggleCheckedContentCommand != null && ToggleCheckedContentCommand.CanExecute(ToggleCheckedContentCommandParameter))
				{
					ToggleCheckedContentCommand.Execute(ToggleCheckedContentCommandParameter);
				}
			}
			Close();
			Mouse.Capture(null);
			mouseButtonEventArgs.Handled = true;
		}

