		public static void SetObsoleteBrushes(this ResourceDictionary resourceDictionary, Theme theme)
		{
			if (resourceDictionary == null)
			{
				throw new ArgumentNullException("resourceDictionary");
			}
			if (theme == null)
			{
				throw new ArgumentNullException("theme");
			}
			foreach (object key in resourceDictionary.Keys)
			{
				if (resourceDictionary[key] is MaterialDesignColors.StaticResourceExtension staticResourceExtension)
				{
					resourceDictionary[key] = new MaterialDesignColors.StaticResourceExtension(staticResourceExtension.ResourceKey);
				}
			}
		}

		public static Theme GetTheme(this ResourceDictionary resourceDictionary)
		{
			if (resourceDictionary == null)
			{
				throw new ArgumentNullException("resourceDictionary");
			}
			if (resourceDictionary["MaterialDesignThemes.CurrentThemeKey"] is Theme result)
			{
				return result;
			}
			Theme theme = new Theme();
			theme.PrimaryLight = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Primary.Light"), GetColor(resourceDictionary, "MaterialDesign.Brush.Primary.Light.Foreground"));
			theme.PrimaryMid = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Primary"), GetColor(resourceDictionary, "MaterialDesign.Brush.Primary.Foreground"));
			theme.PrimaryDark = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Primary.Dark"), GetColor(resourceDictionary, "MaterialDesign.Brush.Primary.Dark.Foreground"));
			theme.SecondaryLight = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary.Light"), GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary.Light.Foreground"));
			theme.SecondaryMid = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary"), GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary.Foreground"));
			theme.SecondaryDark = new ColorPair(GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary.Dark"), GetColor(resourceDictionary, "MaterialDesign.Brush.Secondary.Dark.Foreground"));
			Theme theme2 = theme;
			LoadThemeColors(resourceDictionary, theme2);
			return theme2;
		}

