		private static Color GetColor(ResourceDictionary resourceDictionary, params string[] keys)
		{
			foreach (string key in keys)
			{
				if (TryGetColor(resourceDictionary, key, out var color))
				{
					return color;
				}
			}
			throw new InvalidOperationException("Could not locate required resource with key(s) '" + string.Join(", ", keys) + "'");
		}

		private static bool TryGetColor(ResourceDictionary resourceDictionary, string key, out Color color)
		{
			if (resourceDictionary[key] is SolidColorBrush solidColorBrush)
			{
				color = solidColorBrush.Color;
				return true;
			}
			color = default;
			return false;
		}

		public static IThemeManager? GetThemeManager(this ResourceDictionary resourceDictionary)
		{
			if (resourceDictionary == null)
			{
				throw new ArgumentNullException("resourceDictionary");
			}
			return resourceDictionary["MaterialDesignThemes.ThemeManagerKey"] as IThemeManager;
		}

		internal static void SetSolidColorBrush(this ResourceDictionary sourceDictionary, string name, Color value)
		{
			if (sourceDictionary == null)
			{
				throw new ArgumentNullException("sourceDictionary");
			}
			if (name == null)
			{
				throw new ArgumentNullException("name");
			}
			if (sourceDictionary[name] is SolidColorBrush solidColorBrush)
			{
				if (solidColorBrush.Color == value)
				{
					return;
				}
				if (!solidColorBrush.IsFrozen)
				{
					ColorAnimation animation = new ColorAnimation
					{
						From = solidColorBrush.Color,
						To = value,
						Duration = new Duration(TimeSpan.FromMilliseconds(300L))
					};
					solidColorBrush.BeginAnimation(SolidColorBrush.ColorProperty, animation);
					return;
				}
			}
			SolidColorBrush solidColorBrush2 = new SolidColorBrush(value);
			solidColorBrush2.Freeze();
			sourceDictionary[name] = solidColorBrush2;
		}

		private static void AdjustColors(Color background, ColorAdjustment colorAdjustment, ref Color light, ref Color mid, ref Color dark)
		{
			double offset;
			switch (colorAdjustment.Contrast)
			{
			case Contrast.Low:
				if (background.IsLightColor())
				{
					dark = dark.EnsureContrastRatio(background, colorAdjustment.DesiredContrastRatio, out offset);
					if (Math.Abs(offset) > 0.0)
					{
						mid = mid.ShiftLightness(offset);
						light = light.ShiftLightness(offset);
					}
				}
				else
				{
					light = light.EnsureContrastRatio(background, colorAdjustment.DesiredContrastRatio, out offset);
					if (Math.Abs(offset) > 0.0)
					{
						mid = mid.ShiftLightness(offset);
						dark = dark.ShiftLightness(offset);
					}
				}
				break;
			case Contrast.Medium:
				mid = mid.EnsureContrastRatio(background, colorAdjustment.DesiredContrastRatio, out offset);
				if (Math.Abs(offset) > 0.0)
				{
					dark = dark.ShiftLightness(offset);
					light = light.ShiftLightness(offset);
				}
				break;
			case Contrast.High:
				if (background.IsLightColor())
				{
					light = light.EnsureContrastRatio(background, colorAdjustment.DesiredContrastRatio, out offset);
					if (Math.Abs(offset) > 0.0)
					{
						mid = mid.ShiftLightness(offset);
						dark = dark.ShiftLightness(offset);
					}
				}
				else
				{
					dark = dark.EnsureContrastRatio(background, colorAdjustment.DesiredContrastRatio, out offset);
					if (Math.Abs(offset) > 0.0)
					{
						light = light.ShiftLightness(offset);
						mid = mid.ShiftLightness(offset);
					}
				}
				break;
			}
		}
	}
	[TemplateVisualState(GroupName = "CommonStates", Name = "Normal")]
	[TemplateVisualState(GroupName = "CommonStates", Name = "MousePressed")]
	[TemplateVisualState(GroupName = "CommonStates", Name = "MouseOut")]
	public class Ripple : ContentControl
	{
		public const string TemplateStateNormal = "Normal";

		public const string TemplateStateMousePressed = "MousePressed";

		public const string TemplateStateMouseOut = "MouseOut";

		private static readonly HashSet<Ripple> PressedInstances;

		public static readonly DependencyProperty FeedbackProperty;

		private static readonly DependencyPropertyKey RippleSizePropertyKey;

		public static readonly DependencyProperty RippleSizeProperty;

		private static readonly DependencyPropertyKey RippleXPropertyKey;

		public static readonly DependencyProperty RippleXProperty;

		private static readonly DependencyPropertyKey RippleYPropertyKey;

		public static readonly DependencyProperty RippleYProperty;

		public static readonly DependencyProperty RecognizesAccessKeyProperty;

		public Brush? Feedback
		{
			get
			{
				return (Brush)GetValue(FeedbackProperty);
			}
			set
			{
				SetValue(FeedbackProperty, value);
			}
		}

		public double RippleSize
		{
			get
			{
				return (double)GetValue(RippleSizeProperty);
			}
			private set
			{
				SetValue(RippleSizePropertyKey, value);
			}
		}

		public double RippleX
		{
