			FeedbackProperty = DependencyProperty.Register("Feedback", typeof(Brush), typeof(Ripple), new PropertyMetadata((object)null));
			RippleSizePropertyKey = DependencyProperty.RegisterReadOnly("RippleSize", typeof(double), typeof(Ripple), new PropertyMetadata(0.0));
			RippleSizeProperty = RippleSizePropertyKey.DependencyProperty;
			RippleXPropertyKey = DependencyProperty.RegisterReadOnly("RippleX", typeof(double), typeof(Ripple), new PropertyMetadata(0.0));
			RippleXProperty = RippleXPropertyKey.DependencyProperty;
			RippleYPropertyKey = DependencyProperty.RegisterReadOnly("RippleY", typeof(double), typeof(Ripple), new PropertyMetadata(0.0));
			RippleYProperty = RippleYPropertyKey.DependencyProperty;
			RecognizesAccessKeyProperty = DependencyProperty.Register("RecognizesAccessKey", typeof(bool), typeof(Ripple), new PropertyMetadata(false));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(Ripple), new FrameworkPropertyMetadata(typeof(Ripple)));
			EventManager.RegisterClassHandler(typeof(ContentControl), Mouse.PreviewMouseUpEvent, new MouseButtonEventHandler(MouseButtonEventHandler), handledEventsToo: true);
			EventManager.RegisterClassHandler(typeof(ContentControl), Mouse.MouseMoveEvent, new MouseEventHandler(MouseMoveEventHandler), handledEventsToo: true);
			EventManager.RegisterClassHandler(typeof(Popup), Mouse.PreviewMouseUpEvent, new MouseButtonEventHandler(MouseButtonEventHandler), handledEventsToo: true);
			EventManager.RegisterClassHandler(typeof(Popup), Mouse.MouseMoveEvent, new MouseEventHandler(MouseMoveEventHandler), handledEventsToo: true);
		}

