		private static void MouseButtonEventHandler(object sender, MouseButtonEventArgs e)
		{
			foreach (Ripple pressedInstance in PressedInstances)
			{
				if (pressedInstance.Template.FindName("ScaleTransform", pressedInstance) is ScaleTransform { ScaleX: var scaleX })
				{
					TimeSpan timeSpan = TimeSpan.FromMilliseconds(300.0 * (1.0 - scaleX));
					if (pressedInstance.Template.FindName("MousePressedToNormalScaleXKeyFrame", pressedInstance) is EasingDoubleKeyFrame easingDoubleKeyFrame)
					{
						easingDoubleKeyFrame.KeyTime = KeyTime.FromTimeSpan(timeSpan);
					}
					if (pressedInstance.Template.FindName("MousePressedToNormalScaleYKeyFrame", pressedInstance) is EasingDoubleKeyFrame easingDoubleKeyFrame2)
					{
						easingDoubleKeyFrame2.KeyTime = KeyTime.FromTimeSpan(timeSpan);
					}
				}
				VisualStateManager.GoToState(pressedInstance, "Normal", useTransitions: true);
			}
			PressedInstances.Clear();
		}

		private static void MouseMoveEventHandler(object sender, MouseEventArgs e)
		{
			DispatcherExtensions.Invoke(Dispatcher.CurrentDispatcher, () =>
			{
				foreach (Ripple item in PressedInstances.ToList())
				{
					Point position = Mouse.GetPosition(item);
					if (position.X < 0.0 || position.Y < 0.0 || position.X >= item.ActualWidth || position.Y >= item.ActualHeight)
					{
						VisualStateManager.GoToState(item, "MouseOut", useTransitions: true);
						PressedInstances.Remove(item);
					}
				}
			});
		}

		protected override void OnPreviewMouseLeftButtonDown(MouseButtonEventArgs e)
		{
			if (RippleAssist.GetIsCentered(this))
			{
				if (Content is FrameworkElement frameworkElement)
				{
					Point point = frameworkElement.TransformToAncestor(this).Transform(new Point(0.0, 0.0));
					if (FlowDirection == FlowDirection.RightToLeft)
					{
						RippleX = point.X - frameworkElement.ActualWidth / 2.0 - RippleSize / 2.0;
					}
					else
					{
						RippleX = point.X + frameworkElement.ActualWidth / 2.0 - RippleSize / 2.0;
					}
					RippleY = point.Y + frameworkElement.ActualHeight / 2.0 - RippleSize / 2.0;
				}
				else
				{
					RippleX = ActualWidth / 2.0 - RippleSize / 2.0;
					RippleY = ActualHeight / 2.0 - RippleSize / 2.0;
				}
			}
			else
			{
				Point position = e.GetPosition(this);
				RippleX = position.X - RippleSize / 2.0;
				RippleY = position.Y - RippleSize / 2.0;
			}
			if (!RippleAssist.GetIsDisabled(this))
			{
				VisualStateManager.GoToState(this, "Normal", useTransitions: false);
				VisualStateManager.GoToState(this, "MousePressed", useTransitions: true);
				PressedInstances.Add(this);
			}
			base.OnPreviewMouseLeftButtonDown(e);
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			VisualStateManager.GoToState(this, "Normal", useTransitions: false);
		}

		private void OnSizeChanged(object sender, SizeChangedEventArgs sizeChangedEventArgs)
		{
			FrameworkElement frameworkElement = Content as FrameworkElement;
			double x;
			double x2;
			if (RippleAssist.GetIsCentered(this) && frameworkElement != null)
			{
				x = frameworkElement.ActualWidth;
				x2 = frameworkElement.ActualHeight;
			}
			else
			{
				x = sizeChangedEventArgs.NewSize.Width;
				x2 = sizeChangedEventArgs.NewSize.Height;
			}
			double num = Math.Sqrt(Math.Pow(x, 2.0) + Math.Pow(x2, 2.0));
			RippleSize = 2.0 * num * RippleAssist.GetRippleSizeMultiplier(this);
		}
	}
