	internal static class ScaleHelper
	{
		internal static double GetTotalTransformScaleX(Visual visual)
		{
			double num = 1.0;
			DependencyObject dependencyObject = visual;
			do
			{
				if (dependencyObject is Visual)
				{
					visual = (Visual)dependencyObject;
					Transform transform = VisualTreeHelper.GetTransform(visual);
					if (transform != null && transform.Value.M12 == 0.0 && transform.Value.OffsetX == 0.0)
					{
						num *= transform.Value.M11;
					}
				}
				dependencyObject = VisualTreeHelper.GetParent(dependencyObject);
			}
			while (dependencyObject != null);
			return num;
		}

		internal static double GetTotalTransformScaleY(Visual visual)
		{
			double num = 1.0;
			DependencyObject dependencyObject = visual;
			do
			{
				if (dependencyObject is Visual)
				{
					visual = (Visual)dependencyObject;
					Transform transform = VisualTreeHelper.GetTransform(visual);
					if (transform != null && transform.Value.M21 == 0.0 && transform.Value.OffsetY == 0.0)
					{
						num *= transform.Value.M22;
					}
				}
				dependencyObject = VisualTreeHelper.GetParent(dependencyObject);
			}
			while (dependencyObject != null);
			return num;
		}
	}
