		private static void DarkenPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			if (!((dependencyObject as UIElement)?.Effect is DropShadowEffect dropShadowEffect))
			{
				return;
			}
			double? to;
			if ((bool)dependencyPropertyChangedEventArgs.NewValue)
			{
				dropShadowEffect.BeginAnimation(DropShadowEffect.OpacityProperty, null);
				SetLocalInfo(dependencyObject, new ShadowLocalInfo(dropShadowEffect.Opacity));
				to = 1.0;
			}
			else
			{
				ShadowLocalInfo localInfo = GetLocalInfo(dependencyObject);
				if (localInfo == null)
				{
					return;
				}
				to = localInfo.StandardOpacity;
			}
			TimeSpan shadowAnimationDuration = GetShadowAnimationDuration(dependencyObject);
			DoubleAnimation animation = new DoubleAnimation
			{
				To = to,
				Duration = new Duration(shadowAnimationDuration),
				FillBehavior = FillBehavior.HoldEnd,
				EasingFunction = new CubicEase(),
				AccelerationRatio = 0.4,
				DecelerationRatio = 0.2
			};
			dropShadowEffect.BeginAnimation(DropShadowEffect.OpacityProperty, animation);
		}

