		private static void HintProxyPropertyChangedCallback(DependencyObject? dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			if (dependencyObject is SmartHint smartHint)
			{
				if (dependencyPropertyChangedEventArgs.OldValue is IHintProxy hintProxy)
				{
					hintProxy.IsVisibleChanged -= smartHint.OnHintProxyIsVisibleChanged;
					hintProxy.ContentChanged -= smartHint.OnHintProxyContentChanged;
					hintProxy.Loaded -= smartHint.OnHintProxyContentChanged;
					hintProxy.FocusedChanged -= smartHint.OnHintProxyFocusedChanged;
					hintProxy.Dispose();
				}
				if (dependencyPropertyChangedEventArgs.NewValue is IHintProxy hintProxy2)
				{
					hintProxy2.IsVisibleChanged += smartHint.OnHintProxyIsVisibleChanged;
					hintProxy2.ContentChanged += smartHint.OnHintProxyContentChanged;
					hintProxy2.Loaded += smartHint.OnHintProxyContentChanged;
					hintProxy2.FocusedChanged += smartHint.OnHintProxyFocusedChanged;
					smartHint.RefreshState(useTransitions: false);
				}
			}
		}

		protected virtual void OnHintProxyFocusedChanged(object? sender, EventArgs e)
		{
			IHintProxy hintProxy = HintProxy;
			if (hintProxy != null)
			{
				if (hintProxy.IsLoaded)
				{
					RefreshState(useTransitions: true);
				}
				else
				{
					hintProxy.Loaded += HintProxySetStateOnLoaded;
				}
			}
		}

		protected virtual void OnHintProxyContentChanged(object? sender, EventArgs e)
		{
			IsContentNullOrEmpty = HintProxy?.IsEmpty() ?? false;
			IHintProxy hintProxy = HintProxy;
			if (hintProxy != null)
			{
				if (hintProxy.IsLoaded)
				{
					RefreshState(useTransitions: true);
				}
				else
				{
					hintProxy.Loaded += HintProxySetStateOnLoaded;
				}
			}
		}

		private void HintProxySetStateOnLoaded(object? sender, EventArgs e)
		{
			RefreshState(useTransitions: false);
			IHintProxy hintProxy = HintProxy;
			if (hintProxy != null)
			{
				hintProxy.Loaded -= HintProxySetStateOnLoaded;
			}
		}

		protected virtual void OnHintProxyIsVisibleChanged(object? sender, EventArgs e)
		{
			RefreshState(useTransitions: false);
		}

		private void RefreshState(bool useTransitions)
		{
			IHintProxy proxy = HintProxy;
			if (proxy != null && proxy.IsVisible)
			{
				IsContentNullOrEmpty = proxy.IsEmpty();
				Action action = () =>
				{
					string empty = string.Empty;
					bool flag = proxy.IsEmpty();
					bool flag2 = HintHost?.IsKeyboardFocusWithin ?? proxy.IsFocused();
					empty = ((!UseFloating) ? ((!flag) ? "HintFloatingPosition" : "HintRestingPosition") : ((!flag | flag2) ? "HintFloatingPosition" : "HintRestingPosition"));
					IsHintInFloatingPosition = empty == "HintFloatingPosition";
					VisualStateManager.GoToState(this, empty, useTransitions);
				};
				if (DesignerProperties.GetIsInDesignMode(this))
				{
					action();
				}
				else
				{
					Dispatcher.BeginInvoke(action);
				}
			}
		}
	}
