		}

		private static bool MessageQueueValidateValueCallback(object value)
		{
			if (value == null || ((SnackbarMessageQueue)value).Dispatcher == Dispatcher.CurrentDispatcher)
			{
				return true;
			}
			throw new ArgumentException("SnackbarMessageQueue must be created by the same thread.", "value");
		}

		private static void OnIsActiveChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			Snackbar obj = d as Snackbar;
			RoutedPropertyChangedEventArgs<bool> e2 = new RoutedPropertyChangedEventArgs<bool>((bool)e.OldValue, (bool)e.NewValue)
			{
				RoutedEvent = IsActiveChangedEvent
			};
			obj?.RaiseEvent(e2);
		}

		private static void OnDeactivateStoryboardCompleted(IInputElement snackbar, SnackbarMessage message)
		{
			SnackbarMessageEventArgs e = new SnackbarMessageEventArgs(DeactivateStoryboardCompletedEvent, message);
			snackbar.RaiseEvent(e);
		}

		public override void OnApplyTemplate()
		{
			ActivateStoryboardDuration = GetStoryboardResourceDuration("ActivateStoryboard");
			DeactivateStoryboardDuration = GetStoryboardResourceDuration("DeactivateStoryboard");
			base.OnApplyTemplate();
		}

		private TimeSpan GetStoryboardResourceDuration(string resourceName)
		{
			Storyboard storyboard = (Template.Resources.Contains(resourceName) ? ((Storyboard)Template.Resources[resourceName]) : null);
			if (storyboard == null || !storyboard.Duration.HasTimeSpan)
			{
				return ((Func<TimeSpan>)(() => TimeSpan.Zero))();
			}
			return storyboard.Duration.TimeSpan;
		}

		private static void IsActivePropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			OnIsActiveChanged(dependencyObject, dependencyPropertyChangedEventArgs);
			if (!(bool)dependencyPropertyChangedEventArgs.NewValue)
			{
				Snackbar snackbar = (Snackbar)dependencyObject;
				if (snackbar.Message != null)
				{
					DispatcherTimer dispatcherTimer = new DispatcherTimer();
					dispatcherTimer.Tag = new Tuple<Snackbar, SnackbarMessage>(snackbar, snackbar.Message);
					dispatcherTimer.Interval = snackbar.DeactivateStoryboardDuration;
					dispatcherTimer.Tick += DeactivateStoryboardDispatcherTimerOnTick;
					dispatcherTimer.Start();
				}
			}
		}

		private static void DeactivateStoryboardDispatcherTimerOnTick(object? sender, EventArgs eventArgs)
		{
			if (sender is DispatcherTimer dispatcherTimer)
			{
				dispatcherTimer.Stop();
				dispatcherTimer.Tick -= DeactivateStoryboardDispatcherTimerOnTick;
				Tuple<Snackbar, SnackbarMessage> tuple = (Tuple<Snackbar, SnackbarMessage>)dispatcherTimer.Tag;
				OnDeactivateStoryboardCompleted(tuple.Item1, tuple.Item2);
			}
		}
	}
