	public class SnackbarMessageQueue : ISnackbarMessageQueue, IDisposable
	{
		private class MouseNotOverManagedWaitHandle : IDisposable
		{
			private readonly UIElement _uiElement;

			private readonly ManualResetEvent _waitHandle;

			private readonly ManualResetEvent _disposedWaitHandle = new ManualResetEvent(initialState: false);

			private bool _isDisposed;

			private readonly object _waitHandleGate = new object();

			public EventWaitHandle WaitHandle => _waitHandle;

			public MouseNotOverManagedWaitHandle(UIElement uiElement)
			{
				_uiElement = uiElement ?? throw new ArgumentNullException("uiElement");
				_waitHandle = new ManualResetEvent(!uiElement.IsMouseOver);
				uiElement.MouseEnter += UiElementOnMouseEnter;
				uiElement.MouseLeave += UiElementOnMouseLeave;
			}

			private void UiElementOnMouseEnter(object sender, MouseEventArgs mouseEventArgs)
			{
				_waitHandle.Reset();
			}

			private async void UiElementOnMouseLeave(object sender, MouseEventArgs mouseEventArgs)
			{
				await Task.Run(() =>
				{
					try
					{
						_disposedWaitHandle.WaitOne(TimeSpan.FromSeconds(2L));
					}
					catch (ObjectDisposedException)
					{
					}
				});
				if (((UIElement)sender).IsMouseOver)
				{
					return;
				}
				lock (_waitHandleGate)
				{
					if (!_isDisposed)
					{
						_waitHandle.Set();
					}
				}
			}

			public void Dispose()
			{
				if (!_isDisposed)
				{
					_uiElement.MouseEnter -= UiElementOnMouseEnter;
					_uiElement.MouseLeave -= UiElementOnMouseLeave;
					lock (_waitHandleGate)
					{
						_waitHandle.Dispose();
						_isDisposed = true;
					}
					_disposedWaitHandle.Set();
					_disposedWaitHandle.Dispose();
				}
			}
		}

		private readonly Dispatcher _dispatcher;

		private readonly TimeSpan _messageDuration;

		private readonly HashSet<Snackbar> _pairedSnackbars = new HashSet<Snackbar>();

		private readonly LinkedList<SnackbarMessageQueueItem> _snackbarMessages = new LinkedList<SnackbarMessageQueueItem>();

		private readonly object _snackbarMessagesLock = new object();

		private readonly ManualResetEvent _disposedEvent = new ManualResetEvent(initialState: false);

		private readonly ManualResetEvent _pausedEvent = new ManualResetEvent(initialState: false);

		private readonly SemaphoreSlim _showMessageSemaphore = new SemaphoreSlim(1, 1);

		private int _pauseCounter;

		private bool _isDisposed;

		private ManualResetEvent? _closeSnackbarEvent;

		public IReadOnlyList<SnackbarMessageQueueItem> QueuedMessages
		{
			get
			{
				lock (_snackbarMessagesLock)
				{
					return _snackbarMessages.ToList();
				}
			}
		}

		internal Dispatcher Dispatcher => _dispatcher;

		public bool DiscardDuplicates { get; set; }

		public SnackbarMessageQueue()
			: this(TimeSpan.FromSeconds(3L))
		{
		}

		public SnackbarMessageQueue(TimeSpan messageDuration)
			: this(messageDuration, System.Windows.Threading.Dispatcher.FromThread(Thread.CurrentThread) ?? throw new InvalidOperationException("SnackbarMessageQueue must be created in a dispatcher thread"))
		{
		}

		public SnackbarMessageQueue(TimeSpan messageDuration, Dispatcher dispatcher)
		{
			_messageDuration = messageDuration;
			_dispatcher = dispatcher ?? throw new ArgumentNullException("dispatcher");
		}

		internal Action Pair(Snackbar snackbar)
		{
			if (snackbar == null)
			{
				throw new ArgumentNullException("snackbar");
			}
			_pairedSnackbars.Add(snackbar);
			return () =>
			{
				_pairedSnackbars.Remove(snackbar);
			};
		}

		internal Action Pause()
		{
			if (_isDisposed)
			{
				return () =>
				{
				};
			}
			if (Interlocked.Increment(ref _pauseCounter) == 1)
			{
				_pausedEvent.Set();
			}
			return () =>
			{
				if (Interlocked.Decrement(ref _pauseCounter) == 0)
				{
					_pausedEvent.Reset();
				}
			};
		}

		public void Enqueue(object content)
		{
			Enqueue(content, neverConsiderToBeDuplicate: false);
		}

		public void Enqueue(object content, bool neverConsiderToBeDuplicate)
		{
			Enqueue(content, null, null, null, promote: false, neverConsiderToBeDuplicate);
		}

		public void Enqueue(object content, object? actionContent, Action? actionHandler)
		{
			Enqueue(content, actionContent, actionHandler, promote: false);
		}

		public void Enqueue(object content, object? actionContent, Action? actionHandler, bool promote)
		{
			Enqueue(content, actionContent, (bool _) =>
			{
				actionHandler?.Invoke();
			}, actionArgument: false, promote, neverConsiderToBeDuplicate: false);
		}

		public void Enqueue<TArgument>(object content, object? actionContent, Action<TArgument?>? actionHandler, TArgument? actionArgument)
		{
			Enqueue(content, actionContent, actionHandler, actionArgument, promote: false, neverConsiderToBeDuplicate: false);
		}

		public void Enqueue<TArgument>(object content, object? actionContent, Action<TArgument?>? actionHandler, TArgument? actionArgument, bool promote)
		{
			Enqueue(content, actionContent, actionHandler, actionArgument, promote, neverConsiderToBeDuplicate: false);
		}

		public void Enqueue<TArgument>(object content, object? actionContent, Action<TArgument?>? actionHandler, TArgument? actionArgument, bool promote, bool neverConsiderToBeDuplicate, TimeSpan? durationOverride = null)
		{
			if (content == null)
			{
				throw new ArgumentNullException("content");
			}
			if ((actionContent == null) ^ (actionHandler == null))
			{
				throw new ArgumentNullException((actionContent != null) ? "actionContent" : "actionHandler", "All action arguments must be provided if any are provided.");
			}
			Action<object> actionHandler2 = ((actionHandler != null) ? ((Action<object>)((object? argument) =>
			{
				actionHandler((TArgument)argument);
			})) : null);
			Enqueue(content, actionContent, actionHandler2, actionArgument, promote, neverConsiderToBeDuplicate, durationOverride);
		}

		public void Enqueue(object content, object? actionContent, Action<object?>? actionHandler, object? actionArgument, bool promote, bool neverConsiderToBeDuplicate, TimeSpan? durationOverride = null)
		{
			if (content == null)
			{
				throw new ArgumentNullException("content");
			}
			if ((actionContent == null) ^ (actionHandler == null))
			{
				throw new ArgumentNullException((actionContent != null) ? "actionContent" : "actionHandler", "All action arguments must be provided if any are provided.");
			}
			SnackbarMessageQueueItem item = new SnackbarMessageQueueItem(content, durationOverride ?? _messageDuration, actionContent, actionHandler, actionArgument, promote, neverConsiderToBeDuplicate);
			InsertItem(item);
		}

		private void InsertItem(SnackbarMessageQueueItem item)
		{
			lock (_snackbarMessagesLock)
			{
				bool flag = false;
				for (LinkedListNode<SnackbarMessageQueueItem> linkedListNode = _snackbarMessages.First; linkedListNode != null; linkedListNode = linkedListNode.Next)
				{
					if (DiscardDuplicates && item.IsDuplicate(linkedListNode.Value))
					{
						return;
					}
					if (item.IsPromoted && !linkedListNode.Value.IsPromoted)
					{
						_snackbarMessages.AddBefore(linkedListNode, item);
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					_snackbarMessages.AddLast(item);
				}
			}
			_dispatcher.InvokeAsync((Func<Task>)ShowNextAsync);
		}

		public void Clear()
		{
			lock (_snackbarMessagesLock)
			{
				_snackbarMessages.Clear();
				_closeSnackbarEvent?.Set();
			}
		}

		private void StartDuration(TimeSpan minimumDuration, EventWaitHandle durationPassedWaitHandle)
		{
			if (durationPassedWaitHandle == null)
			{
				throw new ArgumentNullException("durationPassedWaitHandle");
			}
			DateTime completionTime = DateTime.Now.Add(minimumDuration);
			TimeSpan granularity = TimeSpan.FromMilliseconds(200L);
			Task.Run(() =>
			{
				while (true)
				{
					if (DateTime.Now >= completionTime)
					{
						durationPassedWaitHandle.Set();
						break;
					}
					if (_disposedEvent.WaitOne(granularity) || durationPassedWaitHandle.WaitOne(TimeSpan.Zero))
					{
						break;
					}
					if (_pausedEvent.WaitOne(TimeSpan.Zero))
					{
						completionTime = completionTime.Add(granularity);
					}
				}
			});
		}

		private async Task ShowNextAsync()
		{
			await _showMessageSemaphore.WaitAsync().ConfigureAwait(continueOnCapturedContext: true);
			try
			{
				Snackbar snackbar;
				while (true)
				{
					if (_isDisposed || _dispatcher.HasShutdownStarted)
					{
						return;
					}
					snackbar = FindSnackbar();
					if (snackbar != null)
					{
						break;
					}
					Trace.TraceWarning("A snackbar message is waiting, but no snackbar instances are assigned to the message queue.");
					await Task.Delay(TimeSpan.FromSeconds(1L)).ConfigureAwait(continueOnCapturedContext: true);
				}
				LinkedListNode<SnackbarMessageQueueItem> messageNode;
				lock (_snackbarMessagesLock)
				{
					messageNode = _snackbarMessages.First;
					if (messageNode == null)
					{
						return;
					}
					_closeSnackbarEvent = new ManualResetEvent(initialState: false);
				}
				await ShowAsync(snackbar, messageNode.Value, _closeSnackbarEvent).ConfigureAwait(continueOnCapturedContext: false);
				lock (_snackbarMessagesLock)
				{
					if (messageNode.List == _snackbarMessages)
					{
						_snackbarMessages.Remove(messageNode);
					}
					_closeSnackbarEvent.Dispose();
					_closeSnackbarEvent = null;
				}
			}
			finally
			{
				_showMessageSemaphore.Release();
			}
			Snackbar? FindSnackbar()
			{
				return _pairedSnackbars.FirstOrDefault((Snackbar sb) =>
				{
					if (!sb.IsLoaded || sb.Visibility != Visibility.Visible)
					{
						return false;
					}
					Window window = Window.GetWindow(sb);
					return window == null || window.WindowState != WindowState.Minimized;
				});
			}
		}

		private async Task ShowAsync(Snackbar snackbar, SnackbarMessageQueueItem messageQueueItem, ManualResetEvent actionClickWaitHandle)
		{
			Tuple<SnackbarMessage, MouseNotOverManagedWaitHandle> tuple = CreateAndShowMessage(snackbar, messageQueueItem, actionClickWaitHandle);
			SnackbarMessage snackbarMessage = tuple.Item1;
			MouseNotOverManagedWaitHandle mouseNotOverManagedWaitHandle = tuple.Item2;
			ManualResetEvent durationPassedWaitHandle = new ManualResetEvent(initialState: false);
			StartDuration(messageQueueItem.Duration.Add(snackbar.ActivateStoryboardDuration), durationPassedWaitHandle);
			await WaitForCompletionAsync(mouseNotOverManagedWaitHandle, durationPassedWaitHandle, actionClickWaitHandle);
			snackbar.SetCurrentValue(Snackbar.IsActiveProperty, false);
			await Task.Delay(snackbar.DeactivateStoryboardDuration);
			snackbarMessage.Resources = SnackbarMessage.defaultResources;
			snackbar.SetCurrentValue(Snackbar.MessageProperty, null);
			mouseNotOverManagedWaitHandle.Dispose();
			durationPassedWaitHandle.Dispose();
		}

		private static Tuple<SnackbarMessage, MouseNotOverManagedWaitHandle> CreateAndShowMessage(UIElement snackbar, SnackbarMessageQueueItem messageQueueItem, EventWaitHandle actionClickWaitHandle)
		{
			int clickCount = 0;
			SnackbarMessage snackbarMessage = new SnackbarMessage
			{
				Content = messageQueueItem.Content,
				ActionContent = messageQueueItem.ActionContent
			};
			snackbarMessage.ActionClick += (object sender, RoutedEventArgs args) =>
			{
				if (++clickCount == 1)
				{
					DoActionCallback(messageQueueItem);
				}
				if (!actionClickWaitHandle.SafeWaitHandle.IsInvalid && !actionClickWaitHandle.SafeWaitHandle.IsClosed)
				{
					actionClickWaitHandle.Set();
				}
			};
			snackbar.SetCurrentValue(Snackbar.MessageProperty, snackbarMessage);
			snackbar.SetCurrentValue(Snackbar.IsActiveProperty, true);
			return Tuple.Create(snackbarMessage, new MouseNotOverManagedWaitHandle(snackbar));
		}

		private static async Task WaitForCompletionAsync(MouseNotOverManagedWaitHandle mouseNotOverManagedWaitHandle, EventWaitHandle durationPassedWaitHandle, EventWaitHandle actionClickWaitHandle)
		{
			Task durationTask = Task.Run(() =>
			{
				WaitHandle.WaitAll(new WaitHandle[2] { mouseNotOverManagedWaitHandle.WaitHandle, durationPassedWaitHandle });
			});
			Task<bool> actionClickTask = Task.Run((Func<bool>)actionClickWaitHandle.WaitOne);
			await Task.WhenAny(durationTask, actionClickTask);
			mouseNotOverManagedWaitHandle.WaitHandle.Set();
			durationPassedWaitHandle.Set();
			actionClickWaitHandle.Set();
			InlineArray2<Task> buffer = default;
			buffer[0] = durationTask;
			buffer[1] = actionClickTask;
			await Task.WhenAll(buffer);
		}

		private static void DoActionCallback(SnackbarMessageQueueItem messageQueueItem)
		{
			try
			{
				messageQueueItem.ActionHandler?.Invoke(messageQueueItem.ActionArgument);
			}
			catch (Exception ex)
			{
				Trace.WriteLine("Error during SnackbarMessageQueue message action callback, exception will be rethrown.");
				Trace.WriteLine(ex.Message + " (" + ex.GetType().FullName + ")");
				Trace.WriteLine(ex.StackTrace);
				throw;
			}
		}

		public void Dispose()
		{
			_isDisposed = true;
			_disposedEvent.Set();
			_disposedEvent.Dispose();
			_pausedEvent.Dispose();
		}
	}
	public class SnackbarMessageQueueItem
	{
		public object Content { get; }

		public TimeSpan Duration { get; }

		public object? ActionContent { get; }

		public Action<object?>? ActionHandler { get; }

		public object? ActionArgument { get; }

		public bool IsPromoted { get; }

		public bool AlwaysShow { get; }

		public SnackbarMessageQueueItem(object content, TimeSpan duration, object? actionContent = null, Action<object?>? actionHandler = null, object? actionArgument = null, bool isPromoted = false, bool alwaysShow = false)
		{
			Content = content;
			Duration = duration;
			ActionContent = actionContent;
			ActionHandler = actionHandler;
			ActionArgument = actionArgument;
			IsPromoted = isPromoted;
			AlwaysShow = alwaysShow;
		}

		public override bool Equals(object? obj)
		{
			if (!(obj is SnackbarMessageQueueItem snackbarMessageQueueItem))
			{
				return false;
			}
			if (EqualityComparer<object>.Default.Equals(Content, snackbarMessageQueueItem.Content))
			{
				return EqualityComparer<object>.Default.Equals(ActionContent, snackbarMessageQueueItem.ActionContent);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (Content.GetHashCode() * 397) ^ (ActionContent?.GetHashCode() ?? 0);
		}

		public bool IsDuplicate(SnackbarMessageQueueItem value)
		{
			if (value == null)
			{
				throw new ArgumentNullException("value");
			}
			if (AlwaysShow)
			{
				return false;
			}
			return Equals(value);
		}
	}
