		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			_popupBox = GetTemplateChild("PART_PopupBox") as PopupBox;
			_rightButton = GetTemplateChild("PART_RightButton") as Button;
			if (_rightButton != null)
			{
				WeakEventManager<Button, RoutedEventArgs>.RemoveHandler(_rightButton, "Click", OpenPopupBox);
				WeakEventManager<Button, RoutedEventArgs>.AddHandler(_rightButton, "Click", OpenPopupBox);
			}
			if (_popupBox != null)
			{
				_popupBox.RemoveHandler(ButtonBase.ClickEvent, new RoutedEventHandler(PopupContentClickedHandler));
				_popupBox.AddHandler(ButtonBase.ClickEvent, new RoutedEventHandler(PopupContentClickedHandler));
			}
			void OpenPopupBox(object? sender, RoutedEventArgs e)
			{
				if (_popupBox != null)
				{
					_popupBox.IsPopupOpen = true;
					e.Handled = true;
				}
			}
			static void PopupContentClickedHandler(object sender, RoutedEventArgs e)
			{
				e.Handled = true;
			}
		}
