	internal static class StringExtensions
	{
		public static string ToTitleCase(this string text, CultureInfo culture, string separator = " ")
		{
			TextInfo textInfo = culture.TextInfo;
			string[] source = textInfo.ToLower(text).Split(new string[1] { separator }, StringSplitOptions.None);
			return string.Join(separator, source.Select((string v) => textInfo.ToTitleCase(v)));
		}
	}
