		public static BaseTheme? GetSystemTheme()
		{
			try
			{
				object value = Registry.GetValue("HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize", "AppsUseLightTheme", null);
				if (value == null)
				{
					return null;
				}
				return Convert.ToBoolean(value) ? BaseTheme.Light : BaseTheme.Dark;
			}
			catch (Exception)
			{
				return null;
			}
		}

		public static Color? GetSystemAccentColor()
		{
			Color? result = null;
			try
			{
				object value = Registry.GetValue("HKEY_CURRENT_USER\\Software\\Microsoft\\Windows\\DWM", "ColorizationColor", null);
				if (value == null)
				{
					return null;
				}
				uint num = (uint)(int)value;
				if (num != 0)
				{
					byte[] bytes = BitConverter.GetBytes(num);
					result = Color.FromArgb(bytes[3], bytes[2], bytes[1], bytes[0]);
				}
				return result;
			}
			catch (Exception ex)
			{
				Trace.TraceError(ex.ToString());
				return result;
			}
		}

		public static Theme Create(BaseTheme baseTheme, Color primary, Color secondary)
		{
			Theme theme = new Theme();
			theme.SetBaseTheme(baseTheme);
			theme.SetPrimaryColor(primary);
			theme.SetSecondaryColor(secondary);
			return theme;
		}

		internal ColorReference Resolve(ColorReference colorReference)
		{
			return colorReference.ThemeReference switch
			{
				ThemeColorReference.SecondaryLight => new ColorReference(colorReference.ThemeReference, SecondaryLight.Color), 
				ThemeColorReference.SecondaryMid => new ColorReference(colorReference.ThemeReference, SecondaryMid.Color), 
				ThemeColorReference.SecondaryDark => new ColorReference(colorReference.ThemeReference, SecondaryDark.Color), 
				ThemeColorReference.PrimaryLight => new ColorReference(colorReference.ThemeReference, PrimaryLight.Color), 
				ThemeColorReference.PrimaryMid => new ColorReference(colorReference.ThemeReference, PrimaryMid.Color), 
				ThemeColorReference.PrimaryDark => new ColorReference(colorReference.ThemeReference, PrimaryDark.Color), 
				_ => colorReference, 
			};
		}

		public Theme()
		{
			Badgeds = new Badged(this);
			Buttons = new Button(this);
			SnackBars = new SnackBar(this);
			Cards = new Card(this);
			CheckBoxes = new CheckBox(this);
			Chips = new Chip(this);
			ColorZones = new ColorZone(this);
			ComboBoxes = new ComboBox(this);
			DataGrids = new DataGrid(this);
			TextBoxes = new TextBox(this);
			PasswordBoxes = new PasswordBox(this);
			GridSplitters = new GridSplitter(this);
			Headers = new Header(this);
			ListBoxItems = new ListBoxItem(this);
			ListViews = new ListView(this);
			RadioButtons = new RadioButton(this);
			ScrollBars = new ScrollBar(this);
			Separators = new Separator(this);
			StatusBars = new StatusBar(this);
			TabControls = new TabControl(this);
			ToolBars = new ToolBar(this);
			ToggleButtons = new ToggleButton(this);
			ToolTips = new ToolTip(this);
		}
	}
	public static class ThemeAssist
	{
		internal static readonly DependencyProperty TriggerBrushProperty = DependencyProperty.RegisterAttached("TriggerBrush", typeof(Brush), typeof(ThemeAssist), new PropertyMetadata(null));

		public static readonly DependencyProperty ThemeProperty = DependencyProperty.RegisterAttached("Theme", typeof(BaseTheme), typeof(ThemeAssist), new PropertyMetadata(BaseTheme.Inherit, OnThemeChanged));

		internal static Brush GetTriggerColor(DependencyObject obj)
		{
			return (Brush)obj.GetValue(TriggerBrushProperty);
		}

		internal static void SetTriggerBrush(DependencyObject obj, Brush value)
		{
			obj.SetValue(TriggerBrushProperty, value);
		}

		public static BaseTheme GetTheme(DependencyObject obj)
		{
			return (BaseTheme)obj.GetValue(ThemeProperty);
		}

		public static void SetTheme(DependencyObject obj, BaseTheme value)
		{
			obj.SetValue(ThemeProperty, value);
		}

		public static void ChangeTheme(ResourceDictionary resourceDictionary, BaseTheme newTheme)
		{
			if (resourceDictionary == null)
			{
				throw new ArgumentNullException("resourceDictionary");
			}
			string resourceDictionarySource = GetResourceDictionarySource(BaseTheme.Light);
			string resourceDictionarySource2 = GetResourceDictionarySource(BaseTheme.Dark);
			foreach (ResourceDictionary item in resourceDictionary.MergedDictionaries.ToList())
			{
				if (string.Equals(item.Source?.ToString(), resourceDictionarySource, StringComparison.OrdinalIgnoreCase))
				{
					resourceDictionary.MergedDictionaries.Remove(item);
				}
				else if (string.Equals(item.Source?.ToString(), resourceDictionarySource2, StringComparison.OrdinalIgnoreCase))
				{
					resourceDictionary.MergedDictionaries.Remove(item);
				}
			}
			string resourceDictionarySource3 = GetResourceDictionarySource(newTheme);
			if (resourceDictionarySource3 != null)
			{
				resourceDictionary.MergedDictionaries.Add(new ResourceDictionary
				{
					Source = new Uri(resourceDictionarySource3)
				});
			}
		}

		private static void OnThemeChanged(DependencyObject @do, DependencyPropertyChangedEventArgs e)
		{
			if (@do is FrameworkElement frameworkElement && e.NewValue is BaseTheme newTheme)
			{
				ChangeTheme(frameworkElement.Resources, newTheme);
			}
		}

		private static string? GetResourceDictionarySource(BaseTheme theme)
		{
			return theme switch
			{
				BaseTheme.Light => "pack://application:,,,/MaterialDesignThemes.Wpf;component/Themes/MaterialDesignTheme.Light.xaml", 
				BaseTheme.Dark => "pack://application:,,,/MaterialDesignThemes.Wpf;component/Themes/MaterialDesignTheme.Dark.xaml", 
				_ => null, 
			};
		}
	}
