	public static class ThemeExtensions
	{
		internal static ColorPair ToPairedColor(this Hue hue)
		{
			return new ColorPair(hue.Color, hue.Foreground);
		}

		internal static void SetPalette(this Theme theme, Palette palette)
		{
			List<Hue> list = palette.PrimarySwatch.PrimaryHues.ToList();
			Hue hue = list[palette.PrimaryLightHueIndex];
			Hue hue2 = list[palette.PrimaryMidHueIndex];
			Hue hue3 = list[palette.PrimaryDarkHueIndex];
			theme.PrimaryLight = hue.ToPairedColor();
			theme.PrimaryMid = hue2.ToPairedColor();
			theme.PrimaryDark = hue3.ToPairedColor();
		}

		public static BaseTheme GetBaseTheme(this Theme theme)
		{
			if (theme == null)
			{
				throw new ArgumentNullException("theme");
			}
			if (!(theme.Background.Color?.ContrastingForegroundColor() == Colors.White))
			{
				return BaseTheme.Light;
			}
			return BaseTheme.Dark;
		}

		public static void SetBaseTheme(this Theme theme, BaseTheme baseTheme)
		{
			switch (baseTheme)
			{
			case BaseTheme.Light:
				theme.SetLightTheme();
				return;
			case BaseTheme.Dark:
				theme.SetDarkTheme();
				return;
			}
			BaseTheme? systemTheme = Theme.GetSystemTheme();
			if (systemTheme.HasValue && systemTheme == BaseTheme.Dark)
			{
				theme.SetDarkTheme();
			}
			else
			{
				theme.SetLightTheme();
			}
		}

