		public event RoutedPropertyChangedEventHandler<DateTime?> SelectedTimeChanged
		{
			add
			{
				AddHandler(SelectedTimeChangedEvent, value);
			}
			remove
			{
				RemoveHandler(SelectedTimeChangedEvent, value);
			}
		}

		static TimePicker()
		{
			TextProperty = DependencyProperty.Register("Text", typeof(string), typeof(TimePicker), new FrameworkPropertyMetadata(null, FrameworkPropertyMetadataOptions.BindsTwoWayByDefault, TextPropertyChangedCallback));
			SelectedTimeProperty = DependencyProperty.Register("SelectedTime", typeof(DateTime?), typeof(TimePicker), new FrameworkPropertyMetadata(null, FrameworkPropertyMetadataOptions.BindsTwoWayByDefault, SelectedTimePropertyChangedCallback));
			SelectedTimeChangedEvent = EventManager.RegisterRoutedEvent("SelectedTime", RoutingStrategy.Bubble, typeof(RoutedPropertyChangedEventHandler<DateTime?>), typeof(TimePicker));
			SelectedTimeFormatProperty = DependencyProperty.Register("SelectedTimeFormat", typeof(DatePickerFormat), typeof(TimePicker), new PropertyMetadata(DatePickerFormat.Short));
			IsDropDownOpenProperty = DependencyProperty.Register("IsDropDownOpen", typeof(bool), typeof(TimePicker), new FrameworkPropertyMetadata(false, FrameworkPropertyMetadataOptions.BindsTwoWayByDefault, OnIsDropDownOpenChanged, OnCoerceIsDropDownOpen));
			Is24HoursProperty = DependencyProperty.Register("Is24Hours", typeof(bool), typeof(TimePicker), new PropertyMetadata(false, Is24HoursChanged));
			IsHeaderVisibleProperty = DependencyProperty.Register("IsHeaderVisible", typeof(bool), typeof(TimePicker), new PropertyMetadata(false));
			ClockButtonVisibilityProperty = DependencyProperty.Register("ClockButtonVisibility", typeof(Visibility), typeof(TimePicker), new PropertyMetadata(Visibility.Visible));
			ClockStyleProperty = DependencyProperty.Register("ClockStyle", typeof(Style), typeof(TimePicker), new PropertyMetadata((object)null));
			ClockHostContentControlStyleProperty = DependencyProperty.Register("ClockHostContentControlStyle", typeof(Style), typeof(TimePicker), new PropertyMetadata((object)null));
			IsInvalidTextAllowedProperty = DependencyProperty.Register("IsInvalidTextAllowed", typeof(bool), typeof(TimePicker), new PropertyMetadata(false));
			WithSecondsProperty = DependencyProperty.Register("WithSeconds", typeof(bool), typeof(TimePicker), new PropertyMetadata(false, WithSecondsPropertyChanged));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(TimePicker), new FrameworkPropertyMetadata(typeof(TimePicker)));
			EventManager.RegisterClassHandler(typeof(TimePicker), UIElement.GotFocusEvent, new RoutedEventHandler(OnGotFocus));
		}

		private static void OnGotFocus(object sender, RoutedEventArgs e)
		{
			TimePicker timePicker = (TimePicker)sender;
			if (!e.Handled && timePicker._textBox != null)
			{
				if (e.OriginalSource == timePicker)
				{
					timePicker._textBox.Focus();
					e.Handled = true;
				}
				else if (e.OriginalSource == timePicker._textBox)
				{
					timePicker._textBox.SelectAll();
					e.Handled = true;
				}
			}
		}

		public TimePicker()
		{
			_clock = new Clock
			{
				DisplayAutomation = ClockDisplayAutomation.ToMinutesOnly
			};
			_clockHostContentControl = new ContentControl
			{
				Content = _clock
			};
			InitializeClock();
		}

		private static void TextPropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			TimePicker timePicker = (TimePicker)dependencyObject;
			if (!timePicker._isManuallyMutatingText)
			{
				timePicker.SetSelectedTime();
			}
			if (timePicker._textBox != null)
			{
				timePicker.UpdateTextBoxText((dependencyPropertyChangedEventArgs.NewValue as string) ?? "");
			}
		}

		private static void SelectedTimePropertyChangedCallback(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs dependencyPropertyChangedEventArgs)
		{
			TimePicker timePicker = (TimePicker)dependencyObject;
			timePicker._isManuallyMutatingText = true;
			timePicker.SetCurrentValue(TextProperty, timePicker.DateTimeToString(timePicker.SelectedTime));
			timePicker._isManuallyMutatingText = false;
			timePicker._lastValidTime = timePicker.SelectedTime;
			OnSelectedTimeChanged(timePicker, dependencyPropertyChangedEventArgs);
		}

		private static void OnSelectedTimeChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			TimePicker timePicker = (TimePicker)d;
			RoutedPropertyChangedEventArgs<DateTime?> e2 = new RoutedPropertyChangedEventArgs<DateTime?>((DateTime?)e.OldValue, (DateTime?)e.NewValue)
			{
				RoutedEvent = SelectedTimeChangedEvent
			};
			timePicker.RaiseEvent(e2);
		}

		private static void Is24HoursChanged(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs e)
		{
			TimePicker timePicker = (TimePicker)dependencyObject;
			timePicker._isManuallyMutatingText = true;
			timePicker.SetCurrentValue(TextProperty, timePicker.DateTimeToString(timePicker.SelectedTime));
			timePicker._isManuallyMutatingText = false;
		}

		private static object OnCoerceIsDropDownOpen(DependencyObject d, object baseValue)
		{
			if (!((TimePicker)d).IsEnabled)
			{
				return false;
			}
			return baseValue;
		}

		private static void OnIsDropDownOpenChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			TimePicker timePicker = (TimePicker)d;
			bool flag = (bool)e.NewValue;
			if (timePicker._popup == null || timePicker._popup.IsOpen == flag)
			{
				return;
			}
			timePicker._popup.IsOpen = flag;
			if (flag)
			{
				timePicker.Dispatcher?.BeginInvoke(DispatcherPriority.Input, (Action)(() =>
				{
					timePicker._clock.Focus();
				}));
			}
		}

		private static void WithSecondsPropertyChanged(DependencyObject sender, DependencyPropertyChangedEventArgs e)
		{
			if (sender is TimePicker { _clock: var clock } timePicker)
			{
				clock.DisplayAutomation = (timePicker.WithSeconds ? ClockDisplayAutomation.ToSeconds : ClockDisplayAutomation.ToMinutesOnly);
			}
		}

		public override void OnApplyTemplate()
		{
			if (_popup != null)
			{
				_popup.RemoveHandler(UIElement.PreviewMouseLeftButtonDownEvent, new MouseButtonEventHandler(PopupOnPreviewMouseLeftButtonDown));
				_popup.Opened -= PopupOnOpened;
				_popup.Closed -= PopupOnClosed;
				_popup.Child = null;
			}
			if (_dropDownButton != null)
			{
				_dropDownButton.Click -= DropDownButtonOnClick;
			}
			if (_textBox != null)
			{
				_textBox.RemoveHandler(UIElement.KeyDownEvent, new KeyEventHandler(TextBoxOnKeyDown));
				_textBox.RemoveHandler(TextBoxBase.TextChangedEvent, new TextChangedEventHandler(TextBoxOnTextChanged));
				_textBox.AddHandler(UIElement.LostFocusEvent, new RoutedEventHandler(TextBoxOnLostFocus));
			}
			_textBox = GetTemplateChild("PART_TextBox") as TextBox;
			if (_textBox != null)
			{
				_textBox.AddHandler(UIElement.KeyDownEvent, new KeyEventHandler(TextBoxOnKeyDown));
				_textBox.AddHandler(TextBoxBase.TextChangedEvent, new TextChangedEventHandler(TextBoxOnTextChanged));
				_textBox.AddHandler(UIElement.LostFocusEvent, new RoutedEventHandler(TextBoxOnLostFocus));
				_textBox.Text = Text;
			}
			_popup = GetTemplateChild("PART_Popup") as Popup;
			if (_popup != null)
			{
				_popup.AddHandler(UIElement.PreviewMouseLeftButtonDownEvent, new MouseButtonEventHandler(PopupOnPreviewMouseLeftButtonDown));
				_popup.Opened += PopupOnOpened;
				_popup.Closed += PopupOnClosed;
				_popup.Child = _clockHostContentControl;
				if (IsDropDownOpen)
				{
					_popup.IsOpen = true;
				}
			}
			_dropDownButton = GetTemplateChild("PART_Button") as Button;
			if (_dropDownButton != null)
			{
				_dropDownButton.Click += DropDownButtonOnClick;
			}
			base.OnApplyTemplate();
		}

		internal void Clear()
		{
			_textBox?.Clear();
		}

		private void TextBoxOnLostFocus(object sender, RoutedEventArgs routedEventArgs)
		{
			string text = _textBox?.Text;
			DateTime time;
			if (string.IsNullOrEmpty(text))
			{
				SetCurrentValue(SelectedTimeProperty, null);
			}
			else if (IsTimeValid(text, out time))
			{
				SetSelectedTime(in time);
				UpdateTextBoxTextIfNeeded(text);
			}
			else
			{
				SetInvalidTime();
			}
		}

		private void SetInvalidTime()
		{
			if (IsInvalidTextAllowed)
			{
				return;
			}
			TextBox textBox = _textBox;
			if (textBox != null)
			{
				if (_lastValidTime.HasValue)
				{
					textBox.Text = DateTimeToString(_lastValidTime.Value, DatePickerFormat.Short);
					return;
				}
				SetCurrentValue(SelectedTimeProperty, null);
				textBox.Text = "";
			}
		}

		private void TextBoxOnKeyDown(object sender, KeyEventArgs keyEventArgs)
		{
			keyEventArgs.Handled = ProcessKey(keyEventArgs) || keyEventArgs.Handled;
		}

		private bool ProcessKey(KeyEventArgs keyEventArgs)
		{
			switch (keyEventArgs.Key)
			{
			case Key.System:
				if (keyEventArgs.SystemKey == Key.Down && Keyboard.Modifiers.HasFlag(ModifierKeys.Alt))
				{
					TogglePopup();
					return true;
				}
				break;
			case Key.Return:
				SetSelectedTime();
				return true;
			}
			return false;
		}

		private void TextBoxOnTextChanged(object sender, TextChangedEventArgs textChangedEventArgs)
		{
			TextBox textBox = _textBox;
			if (textBox != null)
			{
				Popup? popup = _popup;
				if ((popup != null && popup.IsOpen) || IsInvalidTextAllowed)
				{
					_isManuallyMutatingText = true;
					SetCurrentValue(TextProperty, textBox.Text);
					_isManuallyMutatingText = false;
				}
			}
			Popup? popup2 = _popup;
			if (popup2 != null && !popup2.IsOpen)
			{
				SetSelectedTime(beCautious: true);
			}
		}

		private void UpdateTextBoxText(string? text)
		{
			TextBox textBox = _textBox;
			if (textBox != null)
			{
				int caretIndex = textBox.CaretIndex;
				textBox.Text = text;
				textBox.CaretIndex = caretIndex;
			}
		}

		private void UpdateTextBoxTextIfNeeded(string lastText)
		{
			if (_textBox?.Text == lastText)
			{
				string text = DateTimeToString(SelectedTime);
				if (text != lastText)
				{
					UpdateTextBoxText(text);
				}
			}
		}

		private void SetSelectedTime(in DateTime time)
		{
			SetCurrentValue(SelectedTimeProperty, (SelectedTime?.Date ?? DateTime.Today).Add(time.TimeOfDay));
		}

		private void SetSelectedTime(bool beCautious = false)
		{
			string currentText = _textBox?.Text;
			if (!string.IsNullOrEmpty(currentText))
			{
				ParseTime(currentText, (DateTime t) =>
				{
					if (!beCautious || DateTimeToString(t) == currentText)
					{
						SetSelectedTime(in t);
					}
					if (!beCautious)
					{
						UpdateTextBoxTextIfNeeded(currentText);
					}
				});
			}
			else
			{
				SetCurrentValue(SelectedTimeProperty, null);
			}
		}

		private void ParseTime(string s, Action<DateTime> successContinuation)
		{
			if (IsTimeValid(s, out var time))
			{
				successContinuation(time);
			}
		}

		private bool IsTimeValid(string s, out DateTime time)
		{
			CultureInfo specificCulture = Language.GetSpecificCulture();
			return DateTime.TryParse(s, specificCulture, DateTimeStyles.AllowWhiteSpaces | DateTimeStyles.NoCurrentDateDefault | DateTimeStyles.AssumeLocal, out time);
		}

		private string? DateTimeToString(DateTime? d)
		{
			if (!d.HasValue)
			{
				return null;
			}
			return DateTimeToString(d.Value);
		}

		private string DateTimeToString(DateTime d)
		{
			return DateTimeToString(d, SelectedTimeFormat);
		}

		private string DateTimeToString(DateTime datetime, DatePickerFormat format)
		{
			CultureInfo specificCulture = Language.GetSpecificCulture();
			DateTimeFormatInfo dateFormat = specificCulture.GetDateFormat();
			string value = (Is24Hours ? "H" : "h");
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(value);
			if (format == DatePickerFormat.Long)
			{
				stringBuilder.Append(value);
			}
			stringBuilder.Append(dateFormat.TimeSeparator);
			stringBuilder.Append("mm");
			if (WithSeconds)
			{
				stringBuilder.Append(dateFormat.TimeSeparator);
				stringBuilder.Append("ss");
			}
			if (!Is24Hours && (!string.IsNullOrEmpty(dateFormat.AMDesignator) || !string.IsNullOrEmpty(dateFormat.PMDesignator)))
			{
				stringBuilder.Append(" tt");
			}
			return datetime.ToString(stringBuilder.ToString(), specificCulture);
		}

		private void PopupOnPreviewMouseLeftButtonDown(object sender, MouseButtonEventArgs mouseButtonEventArgs)
		{
			if (sender is Popup { StaysOpen: false } && _dropDownButton?.InputHitTest(mouseButtonEventArgs.GetPosition(_dropDownButton)) != null)
			{
				_disablePopupReopen = true;
			}
		}

		private void PopupOnClosed(object? sender, EventArgs eventArgs)
		{
			if (IsDropDownOpen)
			{
				SetCurrentValue(IsDropDownOpenProperty, false);
			}
			if (_clock.IsKeyboardFocusWithin)
			{
				MoveFocus(new TraversalRequest(FocusNavigationDirection.First));
			}
		}

		private void PopupOnOpened(object? sender, EventArgs eventArgs)
		{
			if (!IsDropDownOpen)
			{
				SetCurrentValue(IsDropDownOpenProperty, true);
			}
			if (_clock != null)
			{
				_clock.DisplayMode = ClockDisplayMode.Hours;
				_clock.MoveFocus(new TraversalRequest(FocusNavigationDirection.First));
			}
		}

		private void InitializeClock()
		{
			_clock.AddHandler(Clock.ClockChoiceMadeEvent, new ClockChoiceMadeEventHandler(ClockChoiceMadeHandler));
			_clock.SetBinding(Control.ForegroundProperty, GetBinding(Control.ForegroundProperty));
			_clock.SetBinding(FrameworkElement.StyleProperty, GetBinding(ClockStyleProperty));
			_clock.SetBinding(Clock.TimeProperty, GetBinding(SelectedTimeProperty, new NullableDateTimeToCurrentDateConverter()));
			_clock.SetBinding(Clock.Is24HoursProperty, GetBinding(Is24HoursProperty));
			_clockHostContentControl.SetBinding(FrameworkElement.StyleProperty, GetBinding(ClockHostContentControlStyleProperty));
		}

		private void ClockChoiceMadeHandler(object sender, ClockChoiceMadeEventArgs clockChoiceMadeEventArgs)
		{
			if ((WithSeconds && clockChoiceMadeEventArgs.Mode == ClockDisplayMode.Seconds) || (!WithSeconds && clockChoiceMadeEventArgs.Mode == ClockDisplayMode.Minutes))
			{
				TogglePopup();
				if (!SelectedTime.HasValue)
				{
					SelectedTime = _clock.Time;
				}
			}
		}

		private void DropDownButtonOnClick(object sender, RoutedEventArgs routedEventArgs)
		{
			TogglePopup();
		}

		private void TogglePopup()
		{
			if (IsDropDownOpen)
			{
				SetCurrentValue(IsDropDownOpenProperty, false);
				return;
			}
			if (_disablePopupReopen)
			{
				_disablePopupReopen = false;
				return;
			}
			SetSelectedTime();
			SetCurrentValue(IsDropDownOpenProperty, true);
		}

		private BindingBase GetBinding(DependencyProperty property, IValueConverter? converter = null)
		{
			return new Binding(property.Name)
			{
				Source = this,
				Converter = converter
			};
		}
	}
