	internal static class TreeHelper
	{
		public static double GetVisibleWidth(FrameworkElement element, FrameworkElement parent, FlowDirection flowDirection)
		{
			if (element == null)
			{
				throw new ArgumentNullException("element");
			}
			if (parent == null)
			{
				throw new ArgumentNullException("parent");
			}
			Point point = element.TransformToAncestor(parent).Transform(new Point(0.0, 0.0));
			if (flowDirection != parent.FlowDirection)
			{
				point.X -= element.ActualWidth;
			}
			int num = (int)Math.Floor(element.ActualWidth);
			if (IsAncestorTill(parent.InputHitTest(new Point(point.X + (double)num, point.Y)) as FrameworkElement, element, parent))
			{
				return num;
			}
			int num2 = (int)Math.Floor(element.ActualWidth);
			int num3 = 0;
			while (num3 < num2)
			{
				num = (num2 + num3) / 2;
				if (IsAncestorTill(parent.InputHitTest(new Point(point.X + (double)num, point.Y)) as FrameworkElement, element, parent))
				{
					if (!IsAncestorTill(parent.InputHitTest(new Point(point.X + (double)num + 1.0, point.Y)) as FrameworkElement, element, parent))
					{
						return num;
					}
					num3 = num;
				}
				else
				{
					num2 = num;
				}
			}
			return element.ActualWidth;
		}

		private static bool IsAncestorTill(FrameworkElement? element, object ancestor, object container)
		{
			if (element == null)
			{
				return false;
			}
			FrameworkElement frameworkElement = element;
			do
			{
				if (frameworkElement == ancestor)
				{
					return true;
				}
				if (frameworkElement == container)
				{
					return false;
				}
			}
			while ((frameworkElement = (frameworkElement.Parent ?? VisualTreeHelper.GetParent(frameworkElement)) as FrameworkElement) != null);
			return false;
		}

		public static Visual? FindMainTreeVisual(Visual? visual)
		{
			DependencyObject dependencyObject = null;
			for (DependencyObject dependencyObject2 = visual; dependencyObject2 != null; dependencyObject2 = VisualTreeHelper.GetParent(dependencyObject2))
			{
				dependencyObject = dependencyObject2;
			}
			return dependencyObject as Visual;
		}

		public static T? FindChild<T>(this DependencyObject parent, string childName) where T : DependencyObject
		{
			if (parent == null)
			{
				return null;
			}
			T val = null;
			int childrenCount = VisualTreeHelper.GetChildrenCount(parent);
			for (int i = 0; i < childrenCount; i++)
			{
				DependencyObject child = VisualTreeHelper.GetChild(parent, i);
				if (!(child is T))
				{
					val = child.FindChild<T>(childName);
					if (val != null)
					{
						break;
					}
					continue;
				}
				if (!string.IsNullOrEmpty(childName))
				{
					if (child is FrameworkElement frameworkElement && frameworkElement.Name == childName)
					{
						val = (T)child;
						break;
					}
					continue;
				}
				val = (T)child;
				break;
			}
			return val;
		}
	}
