		private static object? CoerceItemsSource(DependencyObject d, object? baseValue)
		{
			if (d is TreeListView treeListView)
			{
				return treeListView.InternalItemsSource = new TreeListViewItemsCollection(baseValue);
			}
			return baseValue;
		}

		protected override DependencyObject GetContainerForItemOverride()
		{
			return new TreeListViewItem(this);
		}

		protected override bool IsItemItsOwnContainerOverride(object? item)
		{
			return item is TreeListViewItem;
		}

		protected override void ClearContainerForItemOverride(DependencyObject element, object item)
		{
			if (element is TreeListViewItem treeListViewItem)
			{
				treeListViewItem.ClearTreeListViewItem(item, this);
			}
			base.ClearContainerForItemOverride(element, item);
		}

		internal void ItemExpandedChanged(TreeListViewItem item)
		{
			TreeListViewItemsCollection internalItemsSource = InternalItemsSource;
			if (internalItemsSource == null)
			{
				return;
			}
			int num = ItemContainerGenerator.IndexFromContainer(item);
			if (num < 0)
			{
				return;
			}
			bool isExpanded = item.IsExpanded;
			if (internalItemsSource.GetIsExpanded(num) == isExpanded)
			{
				return;
			}
			internalItemsSource.SetIsExpanded(num, isExpanded);
			if (isExpanded)
			{
				List<object> list = item.GetChildren().ToList();
				int level = internalItemsSource.GetLevel(num);
				for (int i = 0; i < list.Count; i++)
				{
					internalItemsSource.InsertWithLevel(i + num + 1, list[i], level + 1);
				}
			}
			else
			{
				internalItemsSource.RemoveChildrenOfOffsetAdjustedItem(num);
			}
		}

		internal void ItemsChildrenChanged(TreeListViewItem item, NotifyCollectionChangedEventArgs e)
		{
			if (!item.IsExpanded)
			{
				return;
			}
			TreeListViewItemsCollection internalItemsSource = InternalItemsSource;
			if (internalItemsSource == null)
			{
				return;
			}
			int num = ItemContainerGenerator.IndexFromContainer(item);
			if (num < 0)
			{
				return;
			}
			int level = internalItemsSource.GetLevel(num);
			num++;
			switch (e.Action)
			{
			case NotifyCollectionChangedAction.Add:
			{
				int num2 = num + GetChildrenAndGrandChildrenCountOfPriorSiblings(internalItemsSource, num, e.NewStartingIndex);
				for (int l = 0; l < e.NewItems?.Count; l++)
				{
					internalItemsSource.InsertWithLevel(e.NewStartingIndex + l + num2, e.NewItems[l], level + 1);
				}
				break;
			}
			case NotifyCollectionChangedAction.Remove:
			{
				int num2 = num + GetChildrenAndGrandChildrenCountOfPriorSiblings(internalItemsSource, num, e.OldStartingIndex);
				for (int k = 0; k < e.OldItems?.Count; k++)
				{
					internalItemsSource.RemoveOffsetAdjustedItem(e.OldStartingIndex + num2);
				}
				break;
			}
			case NotifyCollectionChangedAction.Replace:
			{
				int num2 = num + GetChildrenAndGrandChildrenCountOfPriorSiblings(internalItemsSource, num, e.OldStartingIndex);
				for (int j = 0; j < e.NewItems?.Count; j++)
				{
					internalItemsSource.ReplaceOffsetAdjustedItem(e.OldStartingIndex + j + num2, e.NewItems[j]);
				}
				break;
			}
			case NotifyCollectionChangedAction.Move:
			{
				int oldIndex = num + e.OldStartingIndex + GetChildrenAndGrandChildrenCountOfPriorSiblings(internalItemsSource, num, e.OldStartingIndex);
				int num3 = 0;
				if (e.OldStartingIndex < e.NewStartingIndex)
				{
					num3 = 1;
				}
				int newIndex = num + e.NewStartingIndex + GetChildrenAndGrandChildrenCountOfPriorSiblings(internalItemsSource, num, e.NewStartingIndex + num3);
				internalItemsSource.Move(oldIndex, newIndex);
				break;
			}
			case NotifyCollectionChangedAction.Reset:
			{
				num--;
				int level2 = internalItemsSource.GetLevel(num);
				List<object> list = item.GetChildren().ToList();
				internalItemsSource.RemoveChildrenOfOffsetAdjustedItem(num);
				num++;
				for (int i = 0; i < list.Count; i++)
				{
					internalItemsSource.InsertWithLevel(i + num, list[i], level2 + 1);
				}
				break;
			}
			}
			static int GetChildrenAndGrandChildrenCountOfPriorSiblings(TreeListViewItemsCollection collection, int startingIndex, int expectedPriorSiblingCount)
			{
				int num4 = 0;
				int num5 = 0;
				int num6 = 0;
				int num7 = collection.GetLevel(startingIndex - 1) + 1;
				while (num6 <= expectedPriorSiblingCount && startingIndex + num5 < collection.Count)
				{
					int level3 = collection.GetLevel(startingIndex + num5);
					if (level3 < num7)
					{
						break;
					}
					if (level3 == num7)
					{
						num6++;
					}
					else
					{
						num4++;
					}
					num5++;
				}
				return num4;
			}
		}

		public object? GetParent(object? item)
		{
			TreeListViewItemsCollection internalItemsSource = InternalItemsSource;
			if (internalItemsSource != null)
			{
				DependencyObject dependencyObject = ItemContainerGenerator.ContainerFromItem(item);
				if (dependencyObject != null)
				{
					int num = ItemContainerGenerator.IndexFromContainer(dependencyObject);
					if (num >= 0)
					{
						return internalItemsSource.GetParent(num);
					}
				}
			}
			return null;
		}

		private List<object?> GetExpandedChildrenAndGrandChildren(object? dataItem)
		{
			List<object> list = new List<object>();
			if (dataItem == null || !(ItemContainerGenerator.ContainerFromItem(dataItem) is TreeListViewItem { IsExpanded: not false } treeListViewItem))
			{
				return list;
			}
			list.Add(dataItem);
			foreach (object child in treeListViewItem.GetChildren())
			{
				list.AddRange(GetExpandedChildrenAndGrandChildren(child));
			}
			return list;
		}

		internal void MoveSelectionToParent(TreeListViewItem item)
		{
			if (!IsKeyboardFocused && !IsKeyboardFocusWithin)
			{
				return;
			}
			TreeListViewItemsCollection internalItemsSource = InternalItemsSource;
			if (internalItemsSource == null)
			{
				return;
			}
			int num = ItemContainerGenerator.IndexFromContainer(item);
			if (num < 0)
			{
				return;
			}
			int level = internalItemsSource.GetLevel(num);
			for (int num2 = num; num2 > 0; num2--)
			{
				if (internalItemsSource.GetLevel(num2) == level - 1)
				{
					SetSelectedItems(new object[1] { internalItemsSource[num2] });
					if (ItemContainerGenerator.ContainerFromIndex(num2) is TreeListViewItem treeListViewItem)
					{
						treeListViewItem.Focus();
					}
					break;
				}
			}
		}

		protected override void OnPropertyChanged(DependencyPropertyChangedEventArgs e)
		{
			base.OnPropertyChanged(e);
			if (e.Property == ListView.ViewProperty && View is GridView gridView)
			{
				AddToggleButtonToFirstColumn(gridView);
			}
		}

		private void AddToggleButtonToFirstColumn(GridView gridView)
		{
			if (gridView.Columns.Count > 0)
			{
				GridViewColumn gridViewColumn = gridView.Columns[0];
				gridViewColumn.CellTemplate = CreateToggleButtonTemplate(gridViewColumn.CellTemplate);
			}
		}

		private DataTemplate CreateToggleButtonTemplate(DataTemplate originalTemplate)
		{
			DataTemplate dataTemplate = new DataTemplate();
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(StackPanel));
			frameworkElementFactory.SetValue(StackPanel.OrientationProperty, Orientation.Horizontal);
			MultiBinding multiBinding = new MultiBinding
			{
				Converter = TreeListViewIndentConverter.Instance
			};
			multiBinding.Bindings.Add(new Binding(LevelIndentSizeProperty.Name)
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(TreeListView), 1)
			});
			multiBinding.Bindings.Add(new Binding(TreeListViewItem.LevelProperty.Name)
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(TreeListViewItem), 1)
			});
			frameworkElementFactory.SetBinding(FrameworkElement.MarginProperty, multiBinding);
			FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(ToggleButton));
			frameworkElementFactory2.SetValue(FrameworkElement.StyleProperty, FindResource("MaterialDesignTreeListViewToggleButtonStyle"));
			frameworkElementFactory2.SetBinding(ToggleButton.IsCheckedProperty, new Binding(TreeListViewItem.IsExpandedProperty.Name)
			{
				RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(TreeListViewItem), 1)
			});
			frameworkElementFactory.AppendChild(frameworkElementFactory2);
			if (originalTemplate != null)
			{
				FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(ContentPresenter));
				frameworkElementFactory3.SetValue(FrameworkElement.MarginProperty, new Thickness(8.0, 0.0, 0.0, 0.0));
				frameworkElementFactory3.SetValue(ContentPresenter.ContentTemplateProperty, originalTemplate);
				frameworkElementFactory.AppendChild(frameworkElementFactory3);
			}
			dataTemplate.VisualTree = frameworkElementFactory;
			return dataTemplate;
		}
	}
