			{
				CollectionChangedEventManager.RemoveHandler(source, CollectionChanged_CollectionChanged);
			}
			if (e.NewValue is INotifyCollectionChanged source2)
			{
				CollectionChangedEventManager.AddHandler(source2, CollectionChanged_CollectionChanged);
			}
			OnChildrenChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset));
		}

		private void CollectionChanged_CollectionChanged(object? sender, NotifyCollectionChangedEventArgs e)
