		internal void PrepareTreeListViewItem(object? item, TreeListView treeListView, int level, bool isExpanded)
		{
			Level = level;
			TreeListView = treeListView;
			Dispatcher.BeginInvoke((Action)(() =>
			{
				if (GetTemplate() is HierarchicalDataTemplate { ItemsSource: { } itemsSource })
				{
					SetBinding(ChildrenProperty, itemsSource);
				}
				IsExpanded = isExpanded;
			}));
			DataTemplate? GetTemplate()
			{
				DataTemplate? dataTemplate = ContentTemplate;
				if (dataTemplate == null)
				{
					dataTemplate = ContentTemplateSelector?.SelectTemplate(item, this);
					if (dataTemplate == null)
					{
						TreeListViewContentPresenter? contentPresenter = ContentPresenter;
						if (contentPresenter == null)
						{
							return null;
						}
						dataTemplate = contentPresenter.Template;
					}
				}
				return dataTemplate;
			}
		}

		public override void OnApplyTemplate()
		{
			base.OnApplyTemplate();
			ContentPresenter = GetTemplateChild("PART_ContentPresenter") as TreeListViewContentPresenter;
			TreeListViewContentPresenter contentPresenter = ContentPresenter;
			if (contentPresenter != null)
			{
				WeakEventManager<TreeListViewContentPresenter, EventArgs>.AddHandler(contentPresenter, "TemplateChanged", OnTemplateChanged);
			}
			void OnTemplateChanged(object? sender, EventArgs e)
			{
				int level = 0;
				bool isExpanded = false;
				int num = TreeListView.ItemContainerGenerator.IndexFromContainer(this);
				if (num >= 0)
				{
					TreeListViewItemsCollection internalItemsSource = TreeListView.InternalItemsSource;
					if (internalItemsSource != null)
					{
						level = internalItemsSource.GetLevel(num);
						isExpanded = internalItemsSource.GetIsExpanded(num);
					}
				}
				PrepareTreeListViewItem(Content, TreeListView, level, isExpanded);
			}
		}

		internal void ClearTreeListViewItem(object _, TreeListView __)
		{
			if (Children is INotifyCollectionChanged source)
			{
				CollectionChangedEventManager.RemoveHandler(source, CollectionChanged_CollectionChanged);
			}
			TreeListView = null;
		}

		private void UpdateHasChildren()
		{
			SetCurrentValue(HasItemsProperty, GetChildren().Any());
		}

		protected override void OnMouseDoubleClick(MouseButtonEventArgs e)
		{
			base.OnMouseDoubleClick(e);
			if (!e.Handled && !DisableExpandOnDoubleClick && e.ChangedButton == MouseButton.Left)
			{
				IsExpanded = !IsExpanded;
			}
		}

		protected override void OnKeyDown(KeyEventArgs e)
		{
			base.OnKeyDown(e);
			if (e.Handled)
			{
				return;
			}
			switch (e.Key)
			{
			case Key.Right:
				IsExpanded = true;
				e.Handled = true;
				break;
			case Key.Left:
				if (IsExpanded)
				{
					IsExpanded = false;
				}
				else
				{
					TreeListView?.MoveSelectionToParent(this);
				}
				e.Handled = true;
				break;
			}
		}
	}
