	public class UpDownBase<T> : UpDownBase where T : INumber<T>, IMinMaxValue<T>
	{
		private static readonly Type SelfType = typeof(UpDownBase<T>);

		public static readonly DependencyProperty MinimumProperty = DependencyProperty.Register("Minimum", typeof(T), SelfType, new PropertyMetadata(MinValue, OnMinimumChanged));

		public static readonly DependencyProperty MaximumProperty = DependencyProperty.Register("Maximum", typeof(T), SelfType, new PropertyMetadata(MaxValue, OnMaximumChanged, CoerceMaximum));

		public static readonly DependencyProperty ValueProperty = DependencyProperty.Register("Value", typeof(T), SelfType, new FrameworkPropertyMetadata(default(T), FrameworkPropertyMetadataOptions.BindsTwoWayByDefault, OnNumericValueChanged, CoerceNumericValue));

		public static readonly DependencyProperty ValueStepProperty = DependencyProperty.Register("ValueStep", typeof(T), SelfType, new PropertyMetadata(One));

		public static readonly DependencyProperty AllowChangeOnScrollProperty = DependencyProperty.Register("AllowChangeOnScroll", typeof(bool), SelfType, new PropertyMetadata(false));

		[Category("Behavior")]
		public static readonly RoutedEvent ValueChangedEvent = EventManager.RegisterRoutedEvent("ValueChanged", RoutingStrategy.Bubble, typeof(RoutedPropertyChangedEventHandler<T>), SelfType);

		private static T MinValue => T.MinValue;

		private static T MaxValue => T.MaxValue;

		private static T One => T.One;

		public virtual T Minimum
		{
			get
			{
				return (T)GetValue(MinimumProperty);
			}
			set
			{
				SetValue(MinimumProperty, value);
			}
		}

		public T Maximum
		{
			get
			{
				return (T)GetValue(MaximumProperty);
			}
			set
			{
				SetValue(MaximumProperty, value);
			}
		}

		public T Value
		{
			get
			{
				return (T)GetValue(ValueProperty);
			}
			set
			{
				SetValue(ValueProperty, value);
			}
		}

		public T ValueStep
		{
			get
			{
				return (T)GetValue(ValueStepProperty);
			}
			set
			{
				SetValue(ValueStepProperty, value);
			}
		}

		public bool AllowChangeOnScroll
		{
			get
			{
				return (bool)GetValue(AllowChangeOnScrollProperty);
			}
			set
			{
				SetValue(AllowChangeOnScrollProperty, value);
			}
		}

		public event RoutedPropertyChangedEventHandler<T> ValueChanged
		{
			add
			{
				AddHandler(ValueChangedEvent, value);
			}
			remove
			{
				RemoveHandler(ValueChangedEvent, value);
			}
		}

		private static UpDownBase<T> ToUpDownBase(DependencyObject dependencyObject)
		{
			return (UpDownBase<T>)dependencyObject;
		}

		private static T Max(T value1, T value2)
		{
			return T.Max(value1, value2);
		}

		private static T Clamp(T value, T min, T max)
		{
			return T.Clamp(value, min, max);
		}

		private static T Add(T value1, T value2)
		{
			return value1 + value2;
		}

		private static T Subtract(T value1, T value2)
		{
			return value1 - value2;
		}

		private static bool TryParse(string text, IFormatProvider? formatProvider, [MaybeNullWhen(false)] out T value)
		{
			return T.TryParse(text, formatProvider, out value);
		}

		private static int Compare(T value1, T value2)
		{
			return value1.CompareTo(value2);
		}

		private static void OnMinimumChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			UpDownBase<T> upDownBase = ToUpDownBase(d);
			upDownBase.CoerceValue(MaximumProperty);
			upDownBase.CoerceValue(ValueProperty);
		}

		private static void OnMaximumChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			ToUpDownBase(d).CoerceValue(ValueProperty);
		}

		private static object? CoerceMaximum(DependencyObject d, object? value)
		{
			if (value is T value2)
			{
				return Max(ToUpDownBase(d).Minimum, value2);
			}
			return value;
		}

		private static void OnNumericValueChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			UpDownBase<T> upDownBase = ToUpDownBase(d);
			RoutedPropertyChangedEventArgs<T> e2 = new RoutedPropertyChangedEventArgs<T>((T)e.OldValue, (T)e.NewValue)
			{
				RoutedEvent = ValueChangedEvent
			};
			upDownBase.RaiseEvent(e2);
			TextBox textBoxField = upDownBase._textBoxField;
			if (textBoxField != null)
			{
				textBoxField.Text = Convert.ToString(e.NewValue, CultureInfo.CurrentCulture);
			}
			upDownBase.UpdateDecreaseButtonEnabled();
			upDownBase.UpdateIncreaseButtonEnabled();
		}

		private void UpdateIncreaseButtonEnabled()
		{
			RepeatButton increaseButton = _increaseButton;
			if (increaseButton != null)
			{
				increaseButton.IsEnabled = Compare(Value, Maximum) < 0;
			}
		}

		private void UpdateDecreaseButtonEnabled()
		{
			RepeatButton decreaseButton = _decreaseButton;
			if (decreaseButton != null)
			{
				decreaseButton.IsEnabled = Compare(Value, Minimum) > 0;
			}
		}

		private static object? CoerceNumericValue(DependencyObject d, object? value)
		{
			if (value is T value2)
			{
				T val = ToUpDownBase(d).ClampValue(value2);
				return val;
			}
			return value;
		}

		public override void OnApplyTemplate()
		{
			if (_increaseButton != null)
			{
				_increaseButton.Click -= IncreaseButtonOnClick;
			}
			if (_decreaseButton != null)
			{
				_decreaseButton.Click -= DecreaseButtonOnClick;
			}
			if (_textBoxField != null)
			{
				_textBoxField.TextChanged -= OnTextBoxTextChanged;
				_textBoxField.LostFocus -= OnTextBoxLostFocus;
			}
			base.OnApplyTemplate();
			if (_increaseButton != null)
			{
				_increaseButton.Click += IncreaseButtonOnClick;
				UpdateIncreaseButtonEnabled();
			}
			if (_decreaseButton != null)
			{
				_decreaseButton.Click += DecreaseButtonOnClick;
				UpdateDecreaseButtonEnabled();
			}
			if (_textBoxField != null)
			{
				_textBoxField.TextChanged += OnTextBoxTextChanged;
				_textBoxField.LostFocus += OnTextBoxLostFocus;
				_textBoxField.Text = Convert.ToString(Value, CultureInfo.CurrentCulture);
			}
		}

		private void OnTextBoxLostFocus(object sender, EventArgs e)
		{
			TextBox textBoxField = _textBoxField;
			if (textBoxField != null)
			{
				textBoxField.Text = Convert.ToString(Value, CultureInfo.CurrentCulture);
			}
		}

		private void OnTextBoxTextChanged(object sender, EventArgs e)
		{
			TextBox textBoxField = _textBoxField;
			if (textBoxField != null && TryParse(textBoxField.Text, CultureInfo.CurrentCulture, out var value))
			{
				SetCurrentValue(ValueProperty, ClampValue(value));
			}
		}

		private void IncreaseButtonOnClick(object sender, RoutedEventArgs e)
		{
			OnIncrease();
		}

		private void DecreaseButtonOnClick(object sender, RoutedEventArgs e)
		{
			OnDecrease();
		}

		private void OnIncrease()
		{
			SetCurrentValue(ValueProperty, Clamp(Add(Value, ValueStep), Minimum, Maximum));
		}

		private void OnDecrease()
		{
			SetCurrentValue(ValueProperty, Clamp(Subtract(Value, ValueStep), Minimum, Maximum));
		}

		private T ClampValue(T value)
		{
			return Clamp(value, Minimum, Maximum);
		}

		protected override void OnPreviewKeyDown(KeyEventArgs e)
		{
			if (e.Key == Key.Up)
			{
				OnIncrease();
				e.Handled = true;
			}
			else if (e.Key == Key.Down)
			{
				OnDecrease();
				e.Handled = true;
			}
			base.OnPreviewKeyDown(e);
		}

		protected override void OnPreviewMouseWheel(MouseWheelEventArgs e)
		{
			if (IsKeyboardFocusWithin && AllowChangeOnScroll)
			{
				if (e.Delta > 0)
				{
					OnIncrease();
				}
				else if (e.Delta < 0)
				{
					OnDecrease();
				}
				e.Handled = true;
			}
			base.OnPreviewMouseWheel(e);
		}
	}
