			if (upDownBase.Focusable && e.OriginalSource == upDownBase)
			{
				TraversalRequest request = new TraversalRequest(Keyboard.Modifiers.HasFlag(ModifierKeys.Shift) ? FocusNavigationDirection.Previous : FocusNavigationDirection.Next);
				if (Keyboard.FocusedElement is UIElement uIElement)
				{
					uIElement.MoveFocus(request);
				}
				else
				{
					upDownBase.Focus();
				}
				e.Handled = true;
			}
		}

		public override void OnApplyTemplate()
		{
			_increaseButton = GetTemplateChild("PART_IncreaseButton") as RepeatButton;
			_decreaseButton = GetTemplateChild("PART_DecreaseButton") as RepeatButton;
			_textBoxField = GetTemplateChild("PART_TextBox") as TextBox;
			base.OnApplyTemplate();
		}

		public void SelectAll()
		{
			_textBoxField?.SelectAll();
		}
