	internal static class VisualTreeExtensions
	{
		public static IEnumerable<DependencyObject> VisualDepthFirstTraversal(this DependencyObject node)
		{
			if (node == null)
			{
				throw new ArgumentNullException("node");
			}
			yield return node;
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(node); i++)
			{
				DependencyObject child = VisualTreeHelper.GetChild(node, i);
				foreach (DependencyObject item in child.VisualDepthFirstTraversal())
				{
					yield return item;
				}
			}
		}

		public static IEnumerable<DependencyObject> VisualBreadthFirstTraversal(this DependencyObject node)
		{
			if (node == null)
			{
				throw new ArgumentNullException("node");
			}
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(node); i++)
			{
				yield return VisualTreeHelper.GetChild(node, i);
			}
			for (int i = 0; i < VisualTreeHelper.GetChildrenCount(node); i++)
			{
				DependencyObject child = VisualTreeHelper.GetChild(node, i);
				foreach (DependencyObject item in child.VisualDepthFirstTraversal())
				{
					yield return item;
				}
			}
		}

		public static bool IsAncestorOf(this DependencyObject parent, DependencyObject? node)
		{
			if (node != null)
			{
				return parent.VisualDepthFirstTraversal().Contains(node);
			}
			return false;
		}

		public static IEnumerable<DependencyObject> GetVisualAncestry(this DependencyObject? leaf)
		{
			while (leaf != null)
			{
				yield return leaf;
				leaf = ((leaf is Visual || leaf is Visual3D) ? VisualTreeHelper.GetParent(leaf) : LogicalTreeHelper.GetParent(leaf));
			}
		}

		public static IEnumerable<DependencyObject?> GetLogicalAncestry(this DependencyObject leaf)
		{
			while (leaf != null)
			{
				yield return leaf;
				leaf = LogicalTreeHelper.GetParent(leaf);
			}
		}

		public static bool IsDescendantOf(this DependencyObject? leaf, DependencyObject? ancestor)
		{
			DependencyObject dependencyObject = null;
			foreach (DependencyObject item in leaf.GetVisualAncestry())
			{
				if (object.Equals(item, ancestor))
				{
					return true;
				}
				dependencyObject = item;
			}
			if (dependencyObject == null)
			{
				return false;
			}
			return dependencyObject.GetLogicalAncestry().Contains(ancestor);
		}
	}
