	public class CircleWipe : ITransitionWipe
	{
		private KeyTime startKeyTime;

		private KeyTime midKeyTime;

		private KeyTime endKeyTime;

		public CircleWipe()
		{
			startKeyTime = KeyTime.FromTimeSpan(TimeSpan.Zero);
			midKeyTime = KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(200L));
			endKeyTime = KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(400L));
		}

		public void Wipe(TransitionerSlide fromSlide, TransitionerSlide toSlide, Point origin, IZIndexController zIndexController)
		{
			if (fromSlide == null)
			{
				throw new ArgumentNullException("fromSlide");
			}
			if (toSlide == null)
			{
				throw new ArgumentNullException("toSlide");
			}
			if (zIndexController == null)
			{
				throw new ArgumentNullException("zIndexController");
			}
			double num = Math.Max(1.0 - origin.X, 1.0 * origin.X);
			double num2 = Math.Max(1.0 - origin.Y, 1.0 * origin.Y);
			double num3 = Math.Sqrt(Math.Pow(toSlide.ActualWidth * num, 2.0) + Math.Pow(toSlide.ActualHeight * num2, 2.0));
			ScaleTransform scaleTransform = new ScaleTransform(0.0, 0.0);
			TranslateTransform value = new TranslateTransform(toSlide.ActualWidth * origin.X, toSlide.ActualHeight * origin.Y);
			TransformGroup transformGroup = new TransformGroup();
			transformGroup.Children.Add(scaleTransform);
			transformGroup.Children.Add(value);
			EllipseGeometry value2 = new EllipseGeometry
			{
				RadiusX = num3,
				RadiusY = num3,
				Transform = transformGroup
			};
			toSlide.SetCurrentValue(UIElement.ClipProperty, value2);
			zIndexController.Stack(toSlide, fromSlide);
			DoubleAnimationUsingKeyFrames animation = SetupOpacityAnimation(fromSlide);
			fromSlide.BeginAnimation(UIElement.OpacityProperty, animation);
			DoubleAnimationUsingKeyFrames animation2 = SetupScaleAnimation(fromSlide, toSlide);
			scaleTransform.BeginAnimation(ScaleTransform.ScaleXProperty, animation2);
			scaleTransform.BeginAnimation(ScaleTransform.ScaleYProperty, animation2);
		}

		private DoubleAnimationUsingKeyFrames SetupScaleAnimation(TransitionerSlide fromSlide, TransitionerSlide toSlide)
		{
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new EasingDoubleKeyFrame(0.0, startKeyTime));
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new EasingDoubleKeyFrame(1.0, endKeyTime));
			doubleAnimationUsingKeyFrames.Completed += (object? sender, EventArgs args) =>
			{
				toSlide.SetCurrentValue(UIElement.ClipProperty, null);
				fromSlide.BeginAnimation(UIElement.OpacityProperty, null);
			};
			return doubleAnimationUsingKeyFrames;
		}

		private DoubleAnimationUsingKeyFrames SetupOpacityAnimation(TransitionerSlide fromSlide)
		{
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = GenerateThreeStepAnimation();
			doubleAnimationUsingKeyFrames.Completed += (object? sender, EventArgs args) =>
			{
				fromSlide.BeginAnimation(UIElement.OpacityProperty, null);
			};
			return doubleAnimationUsingKeyFrames;
		}

		private DoubleAnimationUsingKeyFrames GenerateThreeStepAnimation()
		{
			return new DoubleAnimationUsingKeyFrames
			{
				KeyFrames = 
				{
					(DoubleKeyFrame)new EasingDoubleKeyFrame(1.0, startKeyTime),
					(DoubleKeyFrame)new EasingDoubleKeyFrame(1.0, midKeyTime),
					(DoubleKeyFrame)new EasingDoubleKeyFrame(0.0, endKeyTime)
				}
			};
		}
	}
	public class FadeWipe : ITransitionWipe
	{
		private readonly SineEase sineEase = new SineEase();

		private KeyTime startKeyTime;

		private KeyTime endKeyTime;

		private TimeSpan _duration = TimeSpan.FromMilliseconds(500L);

		public TimeSpan Duration
		{
			get
			{
				return _duration;
			}
			set
			{
				_duration = value;
				CalculateEndKeyTime();
			}
		}

		public FadeWipe()
		{
			startKeyTime = KeyTime.FromTimeSpan(TimeSpan.Zero);
			CalculateEndKeyTime();
		}

		public void Wipe(TransitionerSlide fromSlide, TransitionerSlide toSlide, Point origin, IZIndexController zIndexController)
		{
			if (fromSlide == null)
			{
				throw new ArgumentNullException("fromSlide");
			}
			if (toSlide == null)
			{
				throw new ArgumentNullException("toSlide");
			}
			if (zIndexController == null)
			{
				throw new ArgumentNullException("zIndexController");
			}
			double opacity = fromSlide.Opacity;
			fromSlide.BeginAnimation(UIElement.OpacityProperty, null);
			fromSlide.Opacity = opacity;
			double opacity2 = toSlide.Opacity;
			toSlide.BeginAnimation(UIElement.OpacityProperty, null);
			toSlide.Opacity = ((opacity2 != 1.0) ? opacity2 : 0.0);
			zIndexController.Stack(toSlide, fromSlide);
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = SetupOpacityAnimation(opacity, 0.0);
			DoubleAnimationUsingKeyFrames toAnimation = SetupOpacityAnimation(opacity2, 1.0);
			doubleAnimationUsingKeyFrames.Completed += (object? sender, EventArgs args) =>
			{
				fromSlide.BeginAnimation(UIElement.OpacityProperty, null);
				toSlide.BeginAnimation(UIElement.OpacityProperty, toAnimation);
			};
			fromSlide.BeginAnimation(UIElement.OpacityProperty, doubleAnimationUsingKeyFrames);
		}

		private DoubleAnimationUsingKeyFrames SetupOpacityAnimation(double from, double to)
		{
			return new DoubleAnimationUsingKeyFrames
			{
				KeyFrames = 
				{
					(DoubleKeyFrame)new LinearDoubleKeyFrame(from, startKeyTime),
					(DoubleKeyFrame)new EasingDoubleKeyFrame(to, endKeyTime, sineEase)
				}
			};
		}

		private void CalculateEndKeyTime()
		{
			endKeyTime = KeyTime.FromTimeSpan(TimeSpan.FromSeconds(Duration.TotalSeconds / 2.0));
		}
	}
	[MarkupExtensionReturnType(typeof(TimeSpan))]
	public class IndexedItemOffsetMultiplierExtension : MarkupExtension
	{
		[ConstructorArgument("unit")]
		public TimeSpan Unit { get; set; }

		public IndexedItemOffsetMultiplierExtension(TimeSpan unit)
		{
			Unit = unit;
		}

		public override object ProvideValue(IServiceProvider serviceProvider)
		{
			if (!(serviceProvider.GetService(typeof(IProvideValueTarget)) is IProvideValueTarget provideValueTarget))
			{
				return TimeSpan.Zero;
			}
			if (provideValueTarget.TargetObject != null && provideValueTarget.TargetObject.GetType().FullName == "System.Windows.SharedDp")
			{
				return this;
			}
			if (!(provideValueTarget?.TargetObject is DependencyObject dependencyObject))
			{
				return TimeSpan.Zero;
			}
			ItemsControl itemsControl = ItemsControl.ItemsControlFromItemContainer(dependencyObject);
			if (itemsControl == null)
			{
				DependencyObject dependencyObject2 = dependencyObject;
				while (dependencyObject2 != null && itemsControl == null)
				{
					dependencyObject2 = VisualTreeHelper.GetParent(dependencyObject2);
					itemsControl = ItemsControl.ItemsControlFromItemContainer(dependencyObject2);
				}
			}
			if (itemsControl == null)
			{
				return TimeSpan.Zero;
			}
			DependencyObject dependencyObject3 = (itemsControl.IsItemItsOwnContainer(dependencyObject) ? dependencyObject : itemsControl.ItemContainerGenerator.ContainerFromItem(dependencyObject));
			if (dependencyObject3 == null)
			{
				object obj = (dependencyObject as FrameworkElement)?.DataContext;
				if (obj != null)
				{
					dependencyObject3 = itemsControl.ItemContainerGenerator.ContainerFromItem(obj);
				}
			}
			if (dependencyObject3 == null)
			{
				return TimeSpan.Zero;
			}
			int num = itemsControl.ItemContainerGenerator.IndexFromContainer(dependencyObject3);
			if (num == -1)
			{
				num = itemsControl.Items.IndexOf(dependencyObject);
			}
			if (num == -1 && dependencyObject is FrameworkElement frameworkElement)
			{
				num = itemsControl.Items.IndexOf(frameworkElement.DataContext);
			}
			return (num > -1) ? new TimeSpan(Unit.Ticks * num) : TimeSpan.Zero;
		}
	}
