	public class SlideOutWipe : ITransitionWipe
	{
		private readonly SineEase _sineEase = new SineEase();

		private KeyTime startKeyTime;

		private KeyTime midKeyTime;

		private KeyTime endKeyTime;

		public SlideOutWipe()
		{
			startKeyTime = KeyTime.FromTimeSpan(TimeSpan.Zero);
			midKeyTime = KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(200L));
			endKeyTime = KeyTime.FromTimeSpan(TimeSpan.FromMilliseconds(400L));
		}

		public void Wipe(TransitionerSlide fromSlide, TransitionerSlide toSlide, Point origin, IZIndexController zIndexController)
		{
			if (fromSlide == null)
			{
				throw new ArgumentNullException("fromSlide");
			}
			if (toSlide == null)
			{
				throw new ArgumentNullException("toSlide");
			}
			if (zIndexController == null)
			{
				throw new ArgumentNullException("zIndexController");
			}
			ScaleTransform scaleTransform = new ScaleTransform(1.0, 1.0);
			fromSlide.RenderTransform = scaleTransform;
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new EasingDoubleKeyFrame(1.0, startKeyTime));
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new EasingDoubleKeyFrame(0.8, endKeyTime));
			doubleAnimationUsingKeyFrames.Completed += (object? sender, EventArgs args) =>
			{
				fromSlide.RenderTransform = null;
			};
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames2 = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames2.KeyFrames.Add(new EasingDoubleKeyFrame(1.0, startKeyTime));
			doubleAnimationUsingKeyFrames2.KeyFrames.Add(new EasingDoubleKeyFrame(0.0, endKeyTime));
			doubleAnimationUsingKeyFrames2.Completed += (object? sender, EventArgs args) =>
			{
				fromSlide.BeginAnimation(UIElement.OpacityProperty, null);
			};
			TranslateTransform translateTransform = (TranslateTransform)(toSlide.RenderTransform = new TranslateTransform(0.0, toSlide.ActualHeight));
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames3 = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames3.KeyFrames.Add(new LinearDoubleKeyFrame(toSlide.ActualHeight, startKeyTime));
			doubleAnimationUsingKeyFrames3.KeyFrames.Add(new EasingDoubleKeyFrame(toSlide.ActualHeight, midKeyTime)
			{
				EasingFunction = _sineEase
			});
			doubleAnimationUsingKeyFrames3.KeyFrames.Add(new EasingDoubleKeyFrame(0.0, endKeyTime)
			{
				EasingFunction = _sineEase
			});
			translateTransform.BeginAnimation(TranslateTransform.YProperty, doubleAnimationUsingKeyFrames3);
			scaleTransform.BeginAnimation(ScaleTransform.ScaleXProperty, doubleAnimationUsingKeyFrames);
			scaleTransform.BeginAnimation(ScaleTransform.ScaleYProperty, doubleAnimationUsingKeyFrames);
			fromSlide.BeginAnimation(UIElement.OpacityProperty, doubleAnimationUsingKeyFrames2);
			zIndexController.Stack(toSlide, fromSlide);
		}
	}
	public class SlideWipe : ITransitionWipe
	{
		private readonly SineEase _sineEase = new SineEase();

		public SlideDirection Direction { get; set; }

		public TimeSpan Duration { get; set; } = TimeSpan.FromSeconds(0.5);

		public void Wipe(TransitionerSlide fromSlide, TransitionerSlide toSlide, Point origin, IZIndexController zIndexController)
		{
			if (fromSlide == null)
			{
				throw new ArgumentNullException("fromSlide");
			}
			if (toSlide == null)
			{
				throw new ArgumentNullException("toSlide");
			}
			if (zIndexController == null)
			{
				throw new ArgumentNullException("zIndexController");
			}
			KeyTime keyTime = KeyTime.FromTimeSpan(TimeSpan.Zero);
			KeyTime keyTime2 = KeyTime.FromTimeSpan(Duration);
			double num = 0.0;
			double fromEndX = 0.0;
			double num2 = 0.0;
			double toEndX = 0.0;
			double num3 = 0.0;
			double fromEndY = 0.0;
			double num4 = 0.0;
			double toEndY = 0.0;
			if (Direction == SlideDirection.Left)
			{
				fromEndX = 0.0 - fromSlide.ActualWidth;
				num2 = toSlide.ActualWidth;
			}
			else if (Direction == SlideDirection.Right)
			{
				fromEndX = fromSlide.ActualWidth;
				num2 = 0.0 - toSlide.ActualWidth;
			}
			else if (Direction == SlideDirection.Up)
			{
				fromEndY = 0.0 - fromSlide.ActualHeight;
				num4 = toSlide.ActualHeight;
			}
			else if (Direction == SlideDirection.Down)
			{
				fromEndY = fromSlide.ActualHeight;
				num4 = 0.0 - toSlide.ActualHeight;
			}
			TranslateTransform fromTransform = new TranslateTransform(num, num3);
			fromSlide.RenderTransform = fromTransform;
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new LinearDoubleKeyFrame(num, keyTime));
			doubleAnimationUsingKeyFrames.KeyFrames.Add(new EasingDoubleKeyFrame(fromEndX, keyTime2, _sineEase));
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames2 = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames2.KeyFrames.Add(new LinearDoubleKeyFrame(num3, keyTime));
			doubleAnimationUsingKeyFrames2.KeyFrames.Add(new EasingDoubleKeyFrame(fromEndY, keyTime2, _sineEase));
			TranslateTransform toTransform = new TranslateTransform(num2, num4);
			toSlide.RenderTransform = toTransform;
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames3 = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames3.KeyFrames.Add(new LinearDoubleKeyFrame(num2, keyTime));
			doubleAnimationUsingKeyFrames3.KeyFrames.Add(new EasingDoubleKeyFrame(toEndX, keyTime2, _sineEase));
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames4 = new DoubleAnimationUsingKeyFrames();
			doubleAnimationUsingKeyFrames4.KeyFrames.Add(new LinearDoubleKeyFrame(num4, keyTime));
			doubleAnimationUsingKeyFrames4.KeyFrames.Add(new EasingDoubleKeyFrame(toEndY, keyTime2, _sineEase));
			doubleAnimationUsingKeyFrames.Completed += (object? sender, EventArgs args) =>
			{
				fromTransform.BeginAnimation(TranslateTransform.XProperty, null);
				fromTransform.X = fromEndX;
				fromSlide.RenderTransform = null;
			};
			doubleAnimationUsingKeyFrames2.Completed += (object? sender, EventArgs args) =>
			{
				fromTransform.BeginAnimation(TranslateTransform.YProperty, null);
				fromTransform.Y = fromEndY;
				fromSlide.RenderTransform = null;
			};
			doubleAnimationUsingKeyFrames3.Completed += (object? sender, EventArgs args) =>
			{
				toTransform.BeginAnimation(TranslateTransform.XProperty, null);
				toTransform.X = toEndX;
				toSlide.RenderTransform = null;
			};
			doubleAnimationUsingKeyFrames4.Completed += (object? sender, EventArgs args) =>
			{
				toTransform.BeginAnimation(TranslateTransform.YProperty, null);
				toTransform.Y = toEndY;
				toSlide.RenderTransform = null;
			};
			fromTransform.BeginAnimation(TranslateTransform.XProperty, doubleAnimationUsingKeyFrames);
			fromTransform.BeginAnimation(TranslateTransform.YProperty, doubleAnimationUsingKeyFrames2);
			toTransform.BeginAnimation(TranslateTransform.XProperty, doubleAnimationUsingKeyFrames3);
			toTransform.BeginAnimation(TranslateTransform.YProperty, doubleAnimationUsingKeyFrames4);
			zIndexController.Stack(toSlide, fromSlide);
		}
	}
	public class TransitionEffect : TransitionEffectBase
	{
		public TransitionEffectKind Kind { get; set; }

		public TimeSpan OffsetTime { get; set; } = TimeSpan.Zero;

		public TimeSpan Duration { get; set; } = TimeSpan.FromMilliseconds(400L);

		public TransitionEffect()
		{
		}

		public TransitionEffect(TransitionEffectKind kind)
		{
			Kind = kind;
		}

		public TransitionEffect(TransitionEffectKind kind, TimeSpan duration)
		{
			Kind = kind;
			Duration = duration;
		}

		public override Timeline? Build<TSubject>(TSubject effectSubject)
		{
			if (effectSubject == null)
			{
				throw new ArgumentNullException("effectSubject");
			}
			Timeline timeline = null;
			DependencyProperty parameter = null;
			DependencyObject dependencyObject = null;
			string text = null;
			switch (Kind)
			{
			case TransitionEffectKind.ExpandIn:
				return CreateExpandIn(effectSubject);
			case TransitionEffectKind.SlideInFromLeft:
				timeline = CreateSlide(-300.0, 0.0, effectSubject.Offset);
				parameter = TranslateTransform.XProperty;
				text = effectSubject.TranslateTransformName;
				break;
			case TransitionEffectKind.SlideInFromTop:
				timeline = CreateSlide(-300.0, 0.0, effectSubject.Offset);
				parameter = TranslateTransform.YProperty;
				text = effectSubject.TranslateTransformName;
				break;
			case TransitionEffectKind.SlideInFromRight:
				timeline = CreateSlide(300.0, 0.0, effectSubject.Offset);
				parameter = TranslateTransform.XProperty;
				text = effectSubject.TranslateTransformName;
				break;
			case TransitionEffectKind.SlideInFromBottom:
				timeline = CreateSlide(300.0, 0.0, effectSubject.Offset);
				parameter = TranslateTransform.YProperty;
				text = effectSubject.TranslateTransformName;
				break;
			case TransitionEffectKind.FadeIn:
				timeline = CreateFadeIn(effectSubject.Offset);
				parameter = UIElement.OpacityProperty;
				dependencyObject = effectSubject;
				break;
			default:
				throw new ArgumentOutOfRangeException();
			case TransitionEffectKind.None:
				break;
			}
			if (timeline == null || (dependencyObject == null && text == null))
			{
				return null;
			}
			timeline.Duration = Duration + effectSubject.Offset;
			if (dependencyObject != null)
			{
				Storyboard.SetTarget(timeline, dependencyObject);
			}
			if (text != null)
			{
				Storyboard.SetTargetName(timeline, text);
			}
			Storyboard.SetTargetProperty(timeline, new PropertyPath(parameter));
			return timeline;
		}

		private Timeline CreateFadeIn(TimeSpan initialOffset)
		{
			return CreateSlide(0.0, 1.0, initialOffset);
		}

		private Timeline CreateSlide(double from, double to, TimeSpan initialOffset)
		{
			DiscreteDoubleKeyFrame keyFrame = new DiscreteDoubleKeyFrame(from);
			DiscreteDoubleKeyFrame keyFrame2 = new DiscreteDoubleKeyFrame(from, initialOffset + OffsetTime);
			EasingDoubleKeyFrame keyFrame3 = new EasingDoubleKeyFrame(to, initialOffset + OffsetTime + Duration)
			{
				EasingFunction = new SineEase()
			};
			return new DoubleAnimationUsingKeyFrames
			{
				KeyFrames = 
				{
					(DoubleKeyFrame)keyFrame,
					(DoubleKeyFrame)keyFrame2,
					(DoubleKeyFrame)keyFrame3
				}
			};
		}

		private Timeline CreateExpandIn(ITransitionEffectSubject effectSubject)
		{
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames = new DoubleAnimationUsingKeyFrames();
			DiscreteDoubleKeyFrame keyFrame = new DiscreteDoubleKeyFrame(0.0);
			DiscreteDoubleKeyFrame keyFrame2 = new DiscreteDoubleKeyFrame(0.5, effectSubject.Offset + OffsetTime);
			EasingDoubleKeyFrame keyFrame3 = new EasingDoubleKeyFrame(1.0, effectSubject.Offset + OffsetTime + Duration)
			{
				EasingFunction = new SineEase()
			};
			doubleAnimationUsingKeyFrames.KeyFrames.Add(keyFrame);
			doubleAnimationUsingKeyFrames.KeyFrames.Add(keyFrame2);
			doubleAnimationUsingKeyFrames.KeyFrames.Add(keyFrame3);
			Storyboard.SetTargetName(doubleAnimationUsingKeyFrames, effectSubject.ScaleTransformName);
			Storyboard.SetTargetProperty(doubleAnimationUsingKeyFrames, new PropertyPath(ScaleTransform.ScaleXProperty));
			DoubleAnimationUsingKeyFrames doubleAnimationUsingKeyFrames2 = doubleAnimationUsingKeyFrames.Clone();
			Storyboard.SetTargetName(doubleAnimationUsingKeyFrames2, effectSubject.ScaleTransformName);
			Storyboard.SetTargetProperty(doubleAnimationUsingKeyFrames2, new PropertyPath(ScaleTransform.ScaleYProperty));
			return new ParallelTimeline
			{
				Children = 
				{
					(Timeline)doubleAnimationUsingKeyFrames,
					(Timeline)doubleAnimationUsingKeyFrames2
				}
			};
		}
	}
