	public class TransitionEffectTypeConverter : TypeConverter
	{
		public override bool CanConvertFrom(ITypeDescriptorContext? context, Type sourceType)
		{
			if (!(sourceType == typeof(string)))
			{
				return typeof(TransitionEffectKind).IsAssignableFrom(sourceType);
			}
			return true;
		}

		public override object? ConvertFrom(ITypeDescriptorContext? context, CultureInfo? culture, object value)
		{
			TransitionEffectBase transitionEffectBase = ((!(value is string value2) || !Enum.TryParse<TransitionEffectKind>(value2, out var result)) ? (value as TransitionEffectBase) : new TransitionEffect(result));
			if (transitionEffectBase == null)
			{
				throw new XamlParseException($"Could not parse to type {typeof(TransitionEffectKind).FullName} or {typeof(TransitionEffectBase).FullName}.");
			}
			return transitionEffectBase;
		}
	}
	public class Transitioner : Selector, IZIndexController
	{
		private Point? _nextTransitionOrigin;

		public static readonly RoutedCommand MoveNextCommand;

		public static readonly RoutedCommand MovePreviousCommand;

		public static readonly RoutedCommand MoveFirstCommand;

		public static readonly RoutedCommand MoveLastCommand;

		public static readonly DependencyProperty AutoApplyTransitionOriginsProperty;

		public static readonly DependencyProperty DefaultTransitionOriginProperty;

		public bool AutoApplyTransitionOrigins
		{
			get
			{
				return (bool)GetValue(AutoApplyTransitionOriginsProperty);
			}
			set
			{
				SetValue(AutoApplyTransitionOriginsProperty, value);
			}
		}

		public Point DefaultTransitionOrigin
		{
			get
			{
				return (Point)GetValue(DefaultTransitionOriginProperty);
			}
			set
			{
				SetValue(DefaultTransitionOriginProperty, value);
			}
		}

		static Transitioner()
		{
			MoveNextCommand = new RoutedCommand();
			MovePreviousCommand = new RoutedCommand();
			MoveFirstCommand = new RoutedCommand();
			MoveLastCommand = new RoutedCommand();
			AutoApplyTransitionOriginsProperty = DependencyProperty.Register("AutoApplyTransitionOrigins", typeof(bool), typeof(Transitioner), new PropertyMetadata(false));
			DefaultTransitionOriginProperty = DependencyProperty.Register("DefaultTransitionOrigin", typeof(Point), typeof(Transitioner), new PropertyMetadata(new Point(0.5, 0.5)));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(Transitioner), new FrameworkPropertyMetadata(typeof(Transitioner)));
		}

		public Transitioner()
		{
			CommandBindings.Add(new CommandBinding(MoveNextCommand, MoveNextHandler));
			CommandBindings.Add(new CommandBinding(MovePreviousCommand, MovePreviousHandler));
			CommandBindings.Add(new CommandBinding(MoveFirstCommand, MoveFirstHandler));
			CommandBindings.Add(new CommandBinding(MoveLastCommand, MoveLastHandler));
			AddHandler(TransitionerSlide.InTransitionFinished, new RoutedEventHandler(IsTransitionFinishedHandler));
			AddHandler(Selector.SelectionChangedEvent, new RoutedEventHandler(SelectionChangedEventHandler));
			Loaded += (object sender, RoutedEventArgs args) =>
			{
				if (SelectedIndex != -1)
				{
					ActivateFrame(SelectedIndex, -1);
				}
			};
		}

		protected override bool IsItemItsOwnContainerOverride(object item)
		{
			return item is TransitionerSlide;
		}

		protected override DependencyObject GetContainerForItemOverride()
		{
			return new TransitionerSlide();
		}

		protected override void OnPreviewMouseLeftButtonDown(MouseButtonEventArgs e)
		{
			if (AutoApplyTransitionOrigins)
			{
				_nextTransitionOrigin = GetNavigationSourcePoint(e);
			}
			base.OnPreviewMouseLeftButtonDown(e);
		}

		protected override void OnSelectionChanged(SelectionChangedEventArgs e)
		{
			int unselectedIndex = -1;
			if (e.RemovedItems.Count == 1)
			{
				unselectedIndex = Items.IndexOf(e.RemovedItems[0]);
			}
			int selectedIndex = 1;
			if (e.AddedItems.Count == 1)
			{
				selectedIndex = Items.IndexOf(e.AddedItems[0]);
			}
			ActivateFrame(selectedIndex, unselectedIndex);
			base.OnSelectionChanged(e);
		}

		private void IsTransitionFinishedHandler(object sender, RoutedEventArgs routedEventArgs)
		{
			foreach (TransitionerSlide item in from s in Items.OfType<object>().Select(GetSlide)
				where s.State == TransitionerSlideState.Previous
				select s)
			{
				item.SetCurrentValue(TransitionerSlide.StateProperty, TransitionerSlideState.None);
			}
		}

		private static void SelectionChangedEventHandler(object sender, RoutedEventArgs e)
		{
			if (!(e.OriginalSource is Transitioner))
			{
				e.Handled = true;
			}
		}

		private void MoveNextHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (AutoApplyTransitionOrigins)
			{
				_nextTransitionOrigin = GetNavigationSourcePoint(executedRoutedEventArgs);
			}
			int num = 1;
			if (executedRoutedEventArgs.Parameter is int && (int)executedRoutedEventArgs.Parameter > 0)
			{
				num = (int)executedRoutedEventArgs.Parameter;
			}
			SetCurrentValue(Selector.SelectedIndexProperty, Math.Min(Items.Count - 1, SelectedIndex + num));
		}

		private void MovePreviousHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (AutoApplyTransitionOrigins)
			{
				_nextTransitionOrigin = GetNavigationSourcePoint(executedRoutedEventArgs);
			}
			int num = 1;
			if (executedRoutedEventArgs.Parameter is int && (int)executedRoutedEventArgs.Parameter > 0)
			{
				num = (int)executedRoutedEventArgs.Parameter;
			}
			SetCurrentValue(Selector.SelectedIndexProperty, Math.Max(0, SelectedIndex - num));
		}

		private void MoveFirstHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (AutoApplyTransitionOrigins)
			{
				_nextTransitionOrigin = GetNavigationSourcePoint(executedRoutedEventArgs);
			}
			SetCurrentValue(Selector.SelectedIndexProperty, 0);
		}

		private void MoveLastHandler(object sender, ExecutedRoutedEventArgs executedRoutedEventArgs)
		{
			if (AutoApplyTransitionOrigins)
			{
				_nextTransitionOrigin = GetNavigationSourcePoint(executedRoutedEventArgs);
			}
			SetCurrentValue(Selector.SelectedIndexProperty, Items.Count - 1);
		}

		private Point? GetNavigationSourcePoint(RoutedEventArgs executedRoutedEventArgs)
		{
			if (!(executedRoutedEventArgs.OriginalSource is FrameworkElement frameworkElement) || !IsAncestorOf(frameworkElement) || !IsSafePositive(ActualWidth) || !IsSafePositive(ActualHeight) || !IsSafePositive(frameworkElement.ActualWidth) || !IsSafePositive(frameworkElement.ActualHeight))
			{
				return null;
			}
			Point point = frameworkElement.TranslatePoint(new Point(frameworkElement.ActualWidth / 2.0, frameworkElement.ActualHeight), this);
			return new Point(point.X / ActualWidth, point.Y / ActualHeight);
		}

		private static bool IsSafePositive(double @double)
		{
			if (!double.IsNaN(@double) && !double.IsInfinity(@double))
			{
				return @double > 0.0;
			}
			return false;
		}

		private TransitionerSlide GetSlide(object item)
		{
			if (IsItemItsOwnContainer(item))
			{
				return (TransitionerSlide)item;
			}
			return (TransitionerSlide)ItemContainerGenerator.ContainerFromItem(item);
		}

		private void ActivateFrame(int selectedIndex, int unselectedIndex)
		{
			if (!IsLoaded)
			{
				return;
			}
			TransitionerSlide transitionerSlide = null;
			TransitionerSlide transitionerSlide2 = null;
			for (int i = 0; i < Items.Count; i++)
			{
				TransitionerSlide slide = GetSlide(Items[i]);
				if (slide != null)
				{
					if (i == selectedIndex)
					{
						transitionerSlide2 = slide;
						slide.SetCurrentValue(TransitionerSlide.StateProperty, TransitionerSlideState.Current);
					}
					else if (i == unselectedIndex)
					{
						transitionerSlide = slide;
						slide.SetCurrentValue(TransitionerSlide.StateProperty, TransitionerSlideState.Previous);
					}
					else
					{
						slide.SetCurrentValue(TransitionerSlide.StateProperty, TransitionerSlideState.None);
					}
					Panel.SetZIndex(slide, 0);
				}
			}
			ShowSlide(transitionerSlide2);
			AnimateTransition(selectedIndex, unselectedIndex, transitionerSlide, transitionerSlide2);
			HideSlide(transitionerSlide);
			_nextTransitionOrigin = null;
		}

		private void HideSlide(TransitionerSlide? slide)
		{
			if (slide != null)
			{
				slide.Opacity = 0.0;
			}
		}

		private void ShowSlide(TransitionerSlide? slide)
		{
			if (slide != null)
			{
				slide.Opacity = 1.0;
			}
		}

		private void AnimateTransition(int selectedIndex, int unselectedIndex, TransitionerSlide? oldSlide, TransitionerSlide? newSlide)
		{
			if (oldSlide != null && newSlide != null)
			{
				ITransitionWipe transitionWipe = ((selectedIndex > unselectedIndex) ? oldSlide.ForwardWipe : oldSlide.BackwardWipe);
				if (transitionWipe != null)
				{
					transitionWipe.Wipe(oldSlide, newSlide, GetTransitionOrigin(newSlide), this);
					return;
				}
				DoStack(newSlide, oldSlide);
			}
			else if (oldSlide != null || newSlide != null)
			{
				DoStack(oldSlide ?? newSlide);
			}
		}

		private Point GetTransitionOrigin(TransitionerSlide slide)
		{
			if (_nextTransitionOrigin.HasValue)
			{
				return _nextTransitionOrigin.Value;
			}
			if (slide.ReadLocalValue(TransitionerSlide.TransitionOriginProperty) != DependencyProperty.UnsetValue)
			{
				return slide.TransitionOrigin;
			}
			return DefaultTransitionOrigin;
		}

		void IZIndexController.Stack(params TransitionerSlide?[] highestToLowest)
		{
			DoStack(highestToLowest);
		}

		private static void DoStack(params TransitionerSlide?[] highestToLowest)
		{
			int num = highestToLowest.Length;
			foreach (TransitionerSlide item in highestToLowest.Where((TransitionerSlide s) => s != null))
			{
				Panel.SetZIndex(item, num--);
			}
		}
	}
