	public class TransitioningContentBase : ContentControl, ITransitionEffectSubject
	{
		public const string MatrixTransformPartName = "PART_MatrixTransform";

		public const string RotateTransformPartName = "PART_RotateTransform";

		public const string ScaleTransformPartName = "PART_ScaleTransform";

		public const string SkewTransformPartName = "PART_SkewTransform";

		public const string TranslateTransformPartName = "PART_TranslateTransform";

		private MatrixTransform? _matrixTransform;

		private RotateTransform? _rotateTransform;

		private ScaleTransform? _scaleTransform;

		private SkewTransform? _skewTransform;

		private TranslateTransform? _translateTransform;

		public static readonly DependencyProperty OpeningEffectProperty;

		public static readonly DependencyProperty OpeningEffectsOffsetProperty;

		[TypeConverter(typeof(TransitionEffectTypeConverter))]
		public TransitionEffectBase? OpeningEffect
		{
			get
			{
				return (TransitionEffectBase)GetValue(OpeningEffectProperty);
			}
			set
			{
				SetValue(OpeningEffectProperty, value);
			}
		}

		public TimeSpan OpeningEffectsOffset
		{
			get
			{
				return (TimeSpan)GetValue(OpeningEffectsOffsetProperty);
			}
			set
			{
				SetValue(OpeningEffectsOffsetProperty, value);
			}
		}

		public ObservableCollection<TransitionEffectBase> OpeningEffects { get; } = new ObservableCollection<TransitionEffectBase>();

		string ITransitionEffectSubject.MatrixTransformName => "PART_MatrixTransform";

		string ITransitionEffectSubject.RotateTransformName => "PART_RotateTransform";

		string ITransitionEffectSubject.ScaleTransformName => "PART_ScaleTransform";

		string ITransitionEffectSubject.SkewTransformName => "PART_SkewTransform";

		string ITransitionEffectSubject.TranslateTransformName => "PART_TranslateTransform";

		TimeSpan ITransitionEffectSubject.Offset => OpeningEffectsOffset;

		static TransitioningContentBase()
		{
			OpeningEffectProperty = DependencyProperty.Register("OpeningEffect", typeof(TransitionEffectBase), typeof(TransitioningContentBase), new PropertyMetadata((object)null));
			OpeningEffectsOffsetProperty = DependencyProperty.Register("OpeningEffectsOffset", typeof(TimeSpan), typeof(TransitioningContentBase), new PropertyMetadata(default(TimeSpan)));
			FrameworkElement.DefaultStyleKeyProperty.OverrideMetadata(typeof(TransitioningContentBase), new FrameworkPropertyMetadata(typeof(TransitioningContentBase)));
		}

		public override void OnApplyTemplate()
		{
			FrameworkElement nameScopeRoot = GetNameScopeRoot();
			_matrixTransform = GetTemplateChild("PART_MatrixTransform") as MatrixTransform;
			_rotateTransform = GetTemplateChild("PART_RotateTransform") as RotateTransform;
			_scaleTransform = GetTemplateChild("PART_ScaleTransform") as ScaleTransform;
			_skewTransform = GetTemplateChild("PART_SkewTransform") as SkewTransform;
			_translateTransform = GetTemplateChild("PART_TranslateTransform") as TranslateTransform;
			UnregisterNames(new string[5] { "PART_MatrixTransform", "PART_RotateTransform", "PART_ScaleTransform", "PART_SkewTransform", "PART_TranslateTransform" });
			if (_matrixTransform != null)
			{
				nameScopeRoot.RegisterName("PART_MatrixTransform", _matrixTransform);
			}
			if (_rotateTransform != null)
			{
				nameScopeRoot.RegisterName("PART_RotateTransform", _rotateTransform);
			}
			if (_scaleTransform != null)
			{
				nameScopeRoot.RegisterName("PART_ScaleTransform", _scaleTransform);
			}
			if (_skewTransform != null)
			{
				nameScopeRoot.RegisterName("PART_SkewTransform", _skewTransform);
			}
			if (_translateTransform != null)
			{
				nameScopeRoot.RegisterName("PART_TranslateTransform", _translateTransform);
			}
			base.OnApplyTemplate();
			RunOpeningEffects();
			void UnregisterNames(params string[] names)
			{
				foreach (string item in names.Where((string n) => FindName(n) != null))
				{
					UnregisterName(item);
				}
			}
		}

		protected virtual void RunOpeningEffects()
		{
			if (!IsLoaded || _matrixTransform == null)
			{
				return;
			}
			Storyboard storyboard = new Storyboard();
			Timeline timeline = OpeningEffect?.Build(this);
			if (timeline != null)
			{
				storyboard.Children.Add(timeline);
			}
			foreach (Timeline item in from e in OpeningEffects
				select e.Build(this) into tl
				where tl != null
				select tl)
			{
				storyboard.Children.Add(item);
			}
			storyboard.Begin(GetNameScopeRoot());
		}

		private FrameworkElement GetNameScopeRoot()
		{
			if (VisualChildrenCount > 0 && GetVisualChild(0) is FrameworkElement frameworkElement && NameScope.GetNameScope(frameworkElement) != null)
			{
				return frameworkElement;
			}
			if (NameScope.GetNameScope(this) == null)
			{
				NameScope.SetNameScope(this, new NameScope());
			}
			return this;
		}
	}
