	internal class ClockItemIsCheckedConverter(Func<DateTime> currentTimeGetter, ClockDisplayMode displayMode, bool is24Hours) : IValueConverter
	{
		private readonly Func<DateTime> _currentTimeGetter = currentTimeGetter ?? throw new ArgumentNullException("currentTimeGetter");

		private readonly ClockDisplayMode _displayMode = displayMode;

		private readonly bool _is24Hours = is24Hours;

		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			DateTime dateTime = (DateTime)value;
			int num = (int)parameter;
			int num2;
			if (_displayMode != ClockDisplayMode.Hours)
			{
				num2 = ((_displayMode != ClockDisplayMode.Minutes) ? MassageMinuteSecond(dateTime.Second) : MassageMinuteSecond(dateTime.Minute));
			}
			else
			{
				num2 = MassageHour(dateTime.Hour, _is24Hours);
			}
			return num2 == num;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (!(bool)value)
			{
				return Binding.DoNothing;
			}
			DateTime currentTime = _currentTimeGetter();
			return new DateTime(currentTime.Year, currentTime.Month, currentTime.Day, (_displayMode == ClockDisplayMode.Hours) ? ReverseMassageHour((int)parameter, currentTime, _is24Hours) : currentTime.Hour, (_displayMode == ClockDisplayMode.Minutes) ? ReverseMassageMinuteSecond((int)parameter) : currentTime.Minute, (_displayMode == ClockDisplayMode.Seconds) ? ReverseMassageMinuteSecond((int)parameter) : currentTime.Second);
		}

		private static int MassageHour(int val, bool is24Hours)
		{
			if (is24Hours)
			{
				if (val != 0)
				{
					return val;
				}
				return 24;
			}
			if (val == 0)
			{
				return 12;
			}
			if (val > 12)
			{
				return val - 12;
			}
			return val;
		}

		private static int MassageMinuteSecond(int val)
		{
			if (val != 0)
			{
				return val;
			}
			return 60;
		}

		private static int ReverseMassageHour(int val, DateTime currentTime, bool is24Hours)
		{
			if (is24Hours)
			{
				if (val != 24)
				{
					return val;
				}
				return 0;
			}
			if (currentTime.Hour >= 12)
			{
				if (val != 12)
				{
					return val + 12;
				}
				return 12;
			}
			if (val != 12)
			{
				return val;
			}
			return 0;
		}

		private static int ReverseMassageMinuteSecond(int val)
		{
			if (val != 60)
			{
				return val;
			}
			return 0;
		}
	}
