	public class TextBoxLineCountBehavior : Behavior<TextBox>
	{
		private int _uiUpdateInProgress;

		private void AssociatedObjectOnTextChanged(object sender, TextChangedEventArgs e)
		{
			UpdateAttachedProperties();
		}

		private void AssociatedObjectOnLayoutUpdated(object? sender, EventArgs e)
		{
			UpdateAttachedProperties();
		}

		private void UpdateAttachedProperties()
		{
			TextBox associatedObject = AssociatedObject;
			if (associatedObject != null && Interlocked.CompareExchange(ref _uiUpdateInProgress, 1, 0) == 0)
			{
				associatedObject.Dispatcher.BeginInvoke((Action)(() =>
				{
					int lineCount = associatedObject.LineCount;
					associatedObject.SetCurrentValue(TextFieldAssist.TextBoxLineCountProperty, lineCount);
					associatedObject.SetCurrentValue(TextFieldAssist.TextBoxIsMultiLineProperty, lineCount > 1);
					Interlocked.CompareExchange(ref _uiUpdateInProgress, 0, 1);
				}), DispatcherPriority.Background);
			}
		}

		protected override void OnAttached()
		{
			base.OnAttached();
			AssociatedObject.TextChanged += AssociatedObjectOnTextChanged;
			AssociatedObject.LayoutUpdated += AssociatedObjectOnLayoutUpdated;
		}

		protected override void OnDetaching()
		{
			TextBox textBox = AssociatedObject;
			if (textBox != null)
			{
				textBox.TextChanged -= AssociatedObjectOnTextChanged;
				textBox.LayoutUpdated -= AssociatedObjectOnLayoutUpdated;
			}
			base.OnDetaching();
		}
	}
