		public TabControlHeaderScrollBehavior()
		{
			if (DesignerProperties.GetIsInDesignMode(this))
			{
				NextTabCommand = null;
				PreviousTabCommand = null;
				return;
			}
			NextTabCommand = new SimpleICommandImplementation((object? _) =>
			{
				TabControl tabControl = TabControl;
				if (tabControl != null)
				{
					switch (TabAssist.GetNavigationPanelBehavior(tabControl))
					{
					case NavigationPanelBehavior.Scroll:
					{
						_desiredScrollStart = AssociatedObject.ContentHorizontalOffset;
						double offset = Math.Min(AssociatedObject.ContentHorizontalOffset + AssociatedObject.ActualWidth, AssociatedObject.ExtentWidth - AssociatedObject.ActualWidth - AssociatedObject.Margin.Left - AssociatedObject.Margin.Right);
						AssociatedObject.ScrollToHorizontalOffset(offset);
						break;
					}
					case NavigationPanelBehavior.Select:
					{
						if (TryGetNextTabIndex(tabControl, out var nextTabIndex))
						{
							tabControl.SelectedIndex = nextTabIndex;
						}
						break;
					}
					}
				}
			}, CanNextTabCommandExecute);
			PreviousTabCommand = new SimpleICommandImplementation((object? _) =>
			{
				TabControl tabControl = TabControl;
				if (tabControl != null)
				{
					switch (TabAssist.GetNavigationPanelBehavior(tabControl))
					{
					case NavigationPanelBehavior.Scroll:
						_desiredScrollStart = AssociatedObject.ContentHorizontalOffset;
						AssociatedObject.ScrollToHorizontalOffset(AssociatedObject.ContentHorizontalOffset - AssociatedObject.ActualWidth);
						break;
					case NavigationPanelBehavior.Select:
					{
						if (TryGetPreviousTabIndex(tabControl, out var previousTabIndex))
						{
							tabControl.SelectedIndex = previousTabIndex;
						}
						break;
					}
					}
				}
			}, CanPreviousTabCommandExecute);
			bool CanNextTabCommandExecute(object? _)
			{
				TabControl tabControl = TabControl;
				if (tabControl == null)
				{
					return false;
				}
				int nextTabIndex;
				return TabAssist.GetNavigationPanelBehavior(tabControl) switch
				{
					NavigationPanelBehavior.Scroll => AssociatedObject.ContentHorizontalOffset < AssociatedObject.ExtentWidth - AssociatedObject.ActualWidth - AssociatedObject.Margin.Left - AssociatedObject.Margin.Right, 
					NavigationPanelBehavior.Select => TryGetNextTabIndex(tabControl, out nextTabIndex), 
					_ => false, 
				};
			}
			bool CanPreviousTabCommandExecute(object? _)
			{
				TabControl tabControl = TabControl;
				if (tabControl == null)
				{
					return false;
				}
				int previousTabIndex;
				return TabAssist.GetNavigationPanelBehavior(tabControl) switch
				{
					NavigationPanelBehavior.Scroll => AssociatedObject.ContentHorizontalOffset > 0.0, 
					NavigationPanelBehavior.Select => TryGetPreviousTabIndex(tabControl, out previousTabIndex), 
					_ => false, 
				};
			}
			static List<int> GetEnabledTabItemIndices(TabControl tabControl, Predicate<int> predicate)
			{
				return (from object item in tabControl.Items
					select (TabItem)tabControl.ItemContainerGenerator.ContainerFromItem(item) into tab
					where tab?.IsEnabled ?? false
					select tabControl.ItemContainerGenerator.IndexFromContainer(tab) into tabIndex
					where predicate(tabIndex)
					select tabIndex).ToList();
			}
			static bool TryGetNextTabIndex(TabControl tabControl, out int nextTabIndex)
			{
				nextTabIndex = -1;
				List<int> list = GetEnabledTabItemIndices(tabControl, (int index) => index > tabControl.SelectedIndex);
				if (list.Count > 0)
				{
					nextTabIndex = list.First();
					return true;
				}
				return false;
			}
			static bool TryGetPreviousTabIndex(TabControl tabControl, out int previousTabIndex)
			{
				previousTabIndex = -1;
				List<int> list = GetEnabledTabItemIndices(tabControl, (int index) => index < tabControl.SelectedIndex);
				if (list.Count > 0)
				{
					previousTabIndex = list.Last();
					return true;
				}
				return false;
			}
		}

		private void OnTabChanged(object sender, SelectionChangedEventArgs e)
		{
			TabControl tabControl = (TabControl)sender;
			if (e.AddedItems.Count > 0)
			{
				_desiredScrollStart = AssociatedObject.ContentHorizontalOffset;
				SetScrollDirection(tabControl, (!IsMovingForward()) ? TabScrollDirection.Backward : TabScrollDirection.Forward);
				(tabControl.ItemContainerGenerator.ContainerFromItem(e.AddedItems[0]) as TabItem)?.BringIntoView();
			}
			int GetItemIndex(object? item)
			{
				return tabControl.Items.IndexOf(item);
			}
			double GetItemOffset(int index)
			{
				if (index < 0 || !(tabControl.ItemContainerGenerator.ContainerFromIndex(index) is TabItem tabItem))
				{
					return 1.0;
				}
				return tabItem.TranslatePoint(default, AssociatedObject).X;
			}
			bool IsMovingForward()
			{
				if (e.RemovedItems.Count == 0)
				{
					return true;
				}
				int num = GetItemIndex(e.RemovedItems[0]);
				IList addedItems = e.AddedItems;
				int num2 = GetItemIndex(addedItems[addedItems.Count - 1]);
				if (TabAssist.GetNavigationPanelBehavior(tabControl) == NavigationPanelBehavior.Scroll)
				{
					return GetItemOffset(num2) > 0.0;
				}
				return num2 > num;
			}
		}

		private void OnTabsChanged(object sender, ItemsChangedEventArgs e)
		{
			AssociatedObject.Dispatcher.BeginInvoke((Action)(() =>
			{
				AddPaddingToScrollableContentIfWiderThanViewPort();
			}), DispatcherPriority.Loaded);
		}

		private void OnTabControlSizeChanged(object sender, SizeChangedEventArgs _)
		{
			AddPaddingToScrollableContentIfWiderThanViewPort();
		}

		private void AssociatedObject_SizeChanged(object sender, SizeChangedEventArgs _)
		{
			AddPaddingToScrollableContentIfWiderThanViewPort();
		}

		private void AddPaddingToScrollableContentIfWiderThanViewPort()
		{
			if (TabAssist.GetUseHeaderPadding(TabControl) && ScrollableContent != null)
			{
				if (ScrollableContent.ActualWidth > TabControl.ActualWidth - AdditionalHeaderPanelContentWidth)
				{
					double headerPadding = TabAssist.GetHeaderPadding(TabControl);
					ScrollableContent.Margin = new Thickness(headerPadding, 0.0, headerPadding + AdditionalHeaderPanelContentWidth, 0.0);
					TabAssist.SetIsOverflowing(TabControl, value: true);
				}
				else
				{
					ScrollableContent.Margin = default;
					AssociatedObject.SetCurrentValue(CustomHorizontalOffsetProperty, 0.0);
					TabAssist.SetIsOverflowing(TabControl, value: false);
				}
				AssociatedObject.Margin = new Thickness(NavigationPanelLeftWidth, 0.0, AdditionalHeaderPanelContentWidth, 0.0);
			}
		}

		private void OnTabControlPreviewKeyDown(object sender, KeyEventArgs e)
		{
			if (_isAnimatingScroll)
			{
				Key key = e.Key;
				if ((key == Key.Tab || (uint)(key - 19) <= 4u || key == Key.Right) ? true : false)
				{
					e.Handled = true;
				}
			}
		}

		protected override void OnAttached()
		{
			base.OnAttached();
			if (!DesignerProperties.GetIsInDesignMode(this))
			{
				AssociatedObject.ScrollChanged += AssociatedObject_ScrollChanged;
				AssociatedObject.SizeChanged += AssociatedObject_SizeChanged;
				Dispatcher.BeginInvoke((Action)(() =>
				{
					AddPaddingToScrollableContentIfWiderThanViewPort();
				}));
			}
		}

		protected override void OnDetaching()
		{
			base.OnDetaching();
			if (!DesignerProperties.GetIsInDesignMode(this))
			{
				ScrollViewer scrollViewer = AssociatedObject;
				if (scrollViewer != null)
				{
					scrollViewer.ScrollChanged -= AssociatedObject_ScrollChanged;
					scrollViewer.SizeChanged -= AssociatedObject_SizeChanged;
				}
			}
		}

		private void AssociatedObject_ScrollChanged(object sender, ScrollChangedEventArgs e)
		{
			((SimpleICommandImplementation)PreviousTabCommand).Refresh();
			((SimpleICommandImplementation)NextTabCommand).Refresh();
			if (!TabAssist.GetUseHeaderPadding(TabControl))
			{
				return;
			}
			TimeSpan scrollDuration = TabAssist.GetScrollDuration(TabControl);
			if (scrollDuration == TimeSpan.Zero || _isAnimatingScroll)
			{
				return;
			}
			double? desiredScrollStart = _desiredScrollStart;
			if (desiredScrollStart.HasValue)
			{
				double valueOrDefault = desiredScrollStart.GetValueOrDefault();
				double num = valueOrDefault;
				double horizontalOffset = e.HorizontalOffset;
				_isAnimatingScroll = true;
				bool originalIsHitTestVisibleValue = TabControl.IsHitTestVisible;
				TabControl.SetCurrentValue(UIElement.IsHitTestVisibleProperty, false);
				AssociatedObject.ScrollToHorizontalOffset(num);
				DoubleAnimation doubleAnimation = new DoubleAnimation(num, horizontalOffset, new Duration(scrollDuration));
				doubleAnimation.Completed += (object? _, EventArgs _) =>
				{
					((SimpleICommandImplementation)PreviousTabCommand).Refresh();
					((SimpleICommandImplementation)NextTabCommand).Refresh();
					_desiredScrollStart = null;
					_isAnimatingScroll = false;
					TabControl.SetCurrentValue(UIElement.IsHitTestVisibleProperty, originalIsHitTestVisibleValue);
				};
				AssociatedObject.BeginAnimation(CustomHorizontalOffsetProperty, doubleAnimation);
			}
		}
	}
	public enum TabScrollDirection
	{
		Unknown,
		Backward,
		Forward
	}
	public class TextBoxHorizontalScrollBarBehavior : Behavior<ScrollViewer>
	{
		private ScrollBar? _builtInScrollBar;

		public static readonly DependencyProperty TargetScrollBarProperty = DependencyProperty.Register("TargetScrollBar", typeof(ScrollBar), typeof(TextBoxHorizontalScrollBarBehavior), new PropertyMetadata(null, TargetScrollBarChanged));

		public static readonly DependencyProperty TargetScrollBarVisibilityProperty = DependencyProperty.Register("TargetScrollBarVisibility", typeof(ScrollBarVisibility), typeof(TextBoxHorizontalScrollBarBehavior), new PropertyMetadata(ScrollBarVisibility.Hidden));

		public ScrollBar TargetScrollBar
		{
			get
			{
				return (ScrollBar)GetValue(TargetScrollBarProperty);
			}
			set
			{
				SetValue(TargetScrollBarProperty, value);
			}
		}

		public ScrollBarVisibility TargetScrollBarVisibility
		{
			get
			{
				return (ScrollBarVisibility)GetValue(TargetScrollBarVisibilityProperty);
			}
			set
			{
				SetValue(TargetScrollBarVisibilityProperty, value);
			}
		}

		private static void TargetScrollBarChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			TextBoxHorizontalScrollBarBehavior textBoxHorizontalScrollBarBehavior = (TextBoxHorizontalScrollBarBehavior)d;
			if (e.OldValue is ScrollBar scrollBar)
			{
				scrollBar.Scroll -= textBoxHorizontalScrollBarBehavior.TargetScrollBar_OnScroll;
			}
			if (e.NewValue is ScrollBar scrollBar2)
			{
				scrollBar2.Scroll += textBoxHorizontalScrollBarBehavior.TargetScrollBar_OnScroll;
			}
		}

		private void TargetScrollBar_OnScroll(object sender, ScrollEventArgs e)
		{
			AssociatedObject?.ScrollToHorizontalOffset(e.NewValue);
		}

		private void AssociatedObject_Loaded(object sender, RoutedEventArgs e)
		{
			AssociatedObject.HorizontalScrollBarVisibility = ScrollBarVisibility.Hidden;
			_builtInScrollBar = AssociatedObject.FindChild<ScrollBar>("PART_HorizontalScrollBar");
		}

		private void AssociatedObject_SizeChanged(object sender, SizeChangedEventArgs e)
		{
			ScrollBar targetScrollBar = TargetScrollBar;
			if (targetScrollBar != null && _builtInScrollBar != null)
			{
				targetScrollBar.ViewportSize = AssociatedObject.ViewportWidth;
				targetScrollBar.Value = AssociatedObject.HorizontalOffset;
				targetScrollBar.Maximum = _builtInScrollBar.Maximum;
				UpdateTargetScrollBarVisibility(_builtInScrollBar.Maximum > 0.0);
			}
		}

		private void AssociatedObject_ScrollChanged(object sender, ScrollChangedEventArgs e)
		{
			ScrollBar targetScrollBar = TargetScrollBar;
			if (targetScrollBar != null && _builtInScrollBar != null)
			{
				targetScrollBar.Value = AssociatedObject.HorizontalOffset;
				targetScrollBar.Maximum = _builtInScrollBar.Maximum;
				UpdateTargetScrollBarVisibility(_builtInScrollBar.Maximum > 0.0);
			}
		}

		private void UpdateTargetScrollBarVisibility(bool showIfRequired)
		{
			ScrollBar targetScrollBar = TargetScrollBar;
			if (targetScrollBar != null)
			{
				AssociatedObject.HorizontalScrollBarVisibility = ScrollBarVisibility.Hidden;
				ScrollBar scrollBar = targetScrollBar;
				Visibility visibility;
				switch (TargetScrollBarVisibility)
				{
				case ScrollBarVisibility.Disabled:
				case ScrollBarVisibility.Hidden:
					visibility = Visibility.Collapsed;
					break;
				case ScrollBarVisibility.Visible:
					visibility = Visibility.Visible;
					break;
				default:
					visibility = ((!showIfRequired) ? Visibility.Collapsed : Visibility.Visible);
					break;
				}
				scrollBar.Visibility = visibility;
			}
		}

		protected override void OnAttached()
		{
			base.OnAttached();
			AssociatedObject.Loaded += AssociatedObject_Loaded;
			AssociatedObject.SizeChanged += AssociatedObject_SizeChanged;
			AssociatedObject.ScrollChanged += AssociatedObject_ScrollChanged;
		}

		protected override void OnDetaching()
		{
			ScrollViewer scrollViewer = AssociatedObject;
			if (scrollViewer != null)
			{
				scrollViewer.Loaded -= AssociatedObject_Loaded;
				scrollViewer.SizeChanged -= AssociatedObject_SizeChanged;
				scrollViewer.ScrollChanged -= AssociatedObject_ScrollChanged;
			}
			base.OnDetaching();
		}
	}
}
namespace MaterialDesignThemes.Wpf.Automation.Peers
{
	public class TreeListViewAutomationPeer : ListViewAutomationPeer
	{
		public TreeListViewAutomationPeer(TreeListView owner)
			: base(owner)
		{
		}

		protected override AutomationControlType GetAutomationControlTypeCore()
		{
			return AutomationControlType.Tree;
		}

		protected override string GetClassNameCore()
		{
			return "TreeListView";
		}

		protected override List<AutomationPeer>? GetChildrenCore()
		{
			ItemsControl itemsControl = (ItemsControl)Owner;
			ItemCollection items = itemsControl.Items;
			List<AutomationPeer> list = null;
			if (items.Count > 0)
			{
				list = new List<AutomationPeer>(items.Count);
				for (int i = 0; i < items.Count; i++)
				{
					if (itemsControl.ItemContainerGenerator.ContainerFromIndex(i) is TreeListViewItem { Level: 0 })
					{
						list.Add(CreateItemAutomationPeer(items[i]));
					}
				}
			}
			return list;
		}

		protected override ItemAutomationPeer CreateItemAutomationPeer(object item)
		{
			return new TreeListViewItemAutomationPeer(item, this);
		}
	}
	public class TreeListViewItemAutomationPeer : ListBoxItemAutomationPeer
	{
		public TreeListViewItemAutomationPeer(object owner, SelectorAutomationPeer selectorAutomationPeer)
			: base(owner, selectorAutomationPeer)
		{
		}

		protected override List<AutomationPeer> GetChildrenCore()
		{
			List<AutomationPeer> childrenCore = base.GetChildrenCore();
			ItemsControlAutomationPeer itemsControlAutomationPeer = ItemsControlAutomationPeer;
			if (itemsControlAutomationPeer is TreeListViewAutomationPeer selectorAutomationPeer && itemsControlAutomationPeer.Owner is TreeListView treeListView && treeListView.ItemContainerGenerator.ContainerFromItem(Item) is TreeListViewItem container)
			{
				int num = treeListView.ItemContainerGenerator.IndexFromContainer(container);
				if (num >= 0)
				{
					foreach (int item in treeListView.InternalItemsSource?.GetDirectChildrenIndexes(num) ?? Array.Empty<int>())
					{
						childrenCore.Add(new TreeListViewItemAutomationPeer(treeListView.Items[item], selectorAutomationPeer));
					}
				}
			}
			return childrenCore;
		}

		public override object GetPattern(PatternInterface patternInterface)
		{
			if (patternInterface == PatternInterface.ExpandCollapse)
			{
				return this;
			}
			return base.GetPattern(patternInterface);
		}

		protected override AutomationControlType GetAutomationControlTypeCore()
		{
			return AutomationControlType.TreeItem;
		}

		protected override string GetClassNameCore()
		{
			return "TreeListViewItem";
		}
	}
}
